((window.CARDS_BY_LANG = window.CARDS_BY_LANG || {}).en = window.CARDS_BY_LANG.en || {}).artist = [{"name":"The Beatles","emoji":"🪲","meta":["rock","United Kingdom","1960–1970"],"description":"The Liverpool four reshaped twentieth-century pop music and set off Beatlemania on both sides of the Atlantic. In a single decade John Lennon, Paul McCartney, George Harrison and Ringo Starr went from a beat group to the layered studio experiments of \"Sgt. Pepper's Lonely Hearts Club Band\".","fact":"The zebra crossing outside Abbey Road Studios, pictured on the cover of the album of the same name, has become a pilgrimage site for tourists from all over the world.","wiki_en":"The Beatles","top_song":"Hey Jude"},{"name":"Elvis Presley","emoji":"🕺","meta":["rock and roll","United States","1954–1977"],"description":"Known as the King of Rock and Roll, he was among the first to fuse country, blues and gospel and carry the result to a mass American audience. His restless delivery and hip-swinging stagecraft thrilled young fans and outraged conservatives in equal measure.","fact":"He turned Graceland, his Memphis home, into an estate that remains one of the most visited house museums in the United States.","wiki_en":"Elvis Presley","top_song":"Can't Help Falling in Love"},{"name":"Michael Jackson","emoji":"🧤","meta":["pop","United States","1964–2009"],"description":"Called the King of Pop, he started out as a child in The Jackson 5 and grew into one of the most influential figures in the history of show business, thanks to the album \"Thriller\" and a run of groundbreaking music videos. His dance moves, the moonwalk above all, became the signature of the genre.","fact":"The single white rhinestone glove he wore on stage turned into an instantly recognisable symbol of his image.","wiki_en":"Michael Jackson","top_song":"Billie Jean"},{"name":"Madonna","emoji":"💃","meta":["pop","United States","1979–present"],"description":"The Queen of Pop is known for reinventing her look every few years and for keeping her music and videos at the centre of public argument. Hits such as \"Like a Virgin\" and \"Vogue\" made her one of the best-selling recording artists in history.","fact":"She was one of the first pop stars to turn concert tours into large-scale theatrical shows with elaborate sets.","wiki_en":"Madonna","top_song":"Like a Virgin"},{"name":"Queen","emoji":"👑","meta":["rock","United Kingdom","1970–1991"],"description":"Fronted by Freddie Mercury, the British band married rock to operatic scale and pure theatre, nowhere more clearly than in \"Bohemian Rhapsody\". Their set at Live Aid in 1985 is still cited as one of the greatest live performances rock has produced.","fact":"\"Bohemian Rhapsody\" was released as a single despite running almost six minutes and having no conventional chorus.","wiki_en":"Queen (band)","top_song":"Bohemian Rhapsody"},{"name":"Led Zeppelin","emoji":"🎈","meta":["hard rock","United Kingdom","1968–1980"],"description":"One of the bands that stood at the source of hard rock and heavy metal, known for welding blues roots to epic scale and the virtuosity of Jimmy Page and Robert Plant. Their eight-minute \"Stairway to Heaven\" became one of the most recognisable rock recordings ever made.","fact":"The band broke up after drummer John Bonham died in 1980 and has never reunited on a permanent basis since.","wiki_en":"Led Zeppelin","top_song":"Stairway to Heaven"},{"name":"Pink Floyd","emoji":"🔺","meta":["progressive rock","United Kingdom","1965–1995"],"description":"British pioneers of progressive and psychedelic rock, known for concept albums such as \"The Dark Side of the Moon\" and \"The Wall\" and for enormous stage productions. Their music combines philosophical lyrics, sound experiments and the long, patient guitar solos of David Gilmour.","fact":"The cover of \"The Dark Side of the Moon\", a prism splitting light into a spectrum, became one of the most recognisable images in music.","wiki_en":"Pink Floyd","top_song":"Another Brick in the Wall, Part 2"},{"name":"The Rolling Stones","emoji":"👅","meta":["rock","United Kingdom","1962–present"],"description":"One of the oldest working rock bands in the world, led by Mick Jagger and Keith Richards, built on a blues-rock foundation and a deliberately scandalous stage persona. Their tongue-and-lips logo became one of the most recognisable symbols in music.","fact":"The band is still touring and releasing new music more than six decades after it was founded.","wiki_en":"The Rolling Stones","top_song":"(I Can't Get No) Satisfaction"},{"name":"Elton John","emoji":"🕶️","meta":["pop rock","United Kingdom","1969–present"],"description":"A pianist and singer known for outrageous costumes, oversized glasses and melodic hits such as \"Your Song\" and \"Rocket Man\". His song for Princess Diana, \"Candle in the Wind 1997\", became one of the best-selling records ever released.","fact":"He wrote the music for the animated film \"The Lion King\" and won an Academy Award for it.","wiki_en":"Elton John","top_song":"Rocket Man"},{"name":"David Bowie","emoji":"⚡","meta":["rock","United Kingdom","1962–2016"],"description":"He changed musical styles and stage personas constantly, from the glam-rock Ziggy Stardust to the soul and electronic experiments of his later years. Each album arrived as a separate artistic statement with an aesthetic of its own.","fact":"The lightning bolt painted across his face on the cover of \"Aladdin Sane\" became one of the most recognisable images in rock.","wiki_en":"David Bowie","top_song":"Let's Dance"},{"name":"Bob Dylan","emoji":"📻","meta":["folk rock","United States","1961–present"],"description":"A singer and songwriter whose lyrics lifted rock and folk to the standing of serious poetry, and whose \"Blowin' in the Wind\" became an anthem of the civil rights movement. For that body of writing he was awarded the Nobel Prize in Literature.","fact":"In 1965 he walked onto the stage of the Newport Folk Festival with an electric guitar, outraging part of an audience that expected acoustic folk.","wiki_en":"Bob Dylan","top_song":"Like a Rolling Stone"},{"name":"Prince","emoji":"💜","meta":["funk rock","United States","1978–2016"],"description":"A restlessly versatile musician who blended funk, rock, soul and pop, and who wrote, arranged and played almost all of his own records himself. The colour purple and the album \"Purple Rain\" became his trademark.","fact":"In the 1990s he changed his name to an unpronounceable symbol, which led the press to call him the Artist Formerly Known as Prince.","wiki_en":"Prince (musician)","top_song":"Purple Rain"},{"name":"Whitney Houston","emoji":"🎤","meta":["pop soul","United States","1983–2012"],"description":"A singer with one of the most powerful and technically assured voices in pop history, she began in a gospel choir and became a global star with \"I Wanna Dance with Somebody\" and her version of \"I Will Always Love You\". She also starred in the film \"The Bodyguard\".","fact":"Her recording of \"I Will Always Love You\" for the soundtrack of \"The Bodyguard\" became one of the best-selling singles ever by a woman.","wiki_en":"Whitney Houston","top_song":"I Will Always Love You"},{"name":"ABBA","emoji":"🪩","meta":["pop","Sweden","1972–1982"],"description":"The Swedish quartet became a symbol of the disco era after winning the Eurovision Song Contest with \"Waterloo\". Their melodic hits, among them \"Dancing Queen\" and \"Mamma Mia\", are still played around the world every single day.","fact":"In 2021 the group released a new album and a concert show performed by digital avatars of its members, ABBA Voyage.","wiki_en":"ABBA","top_song":"Dancing Queen"},{"name":"Bee Gees","emoji":"🪩","meta":["disco","United Kingdom","1958–2003"],"description":"The three Gibb brothers and their falsetto harmonies came to define the disco era after the soundtrack to the film \"Saturday Night Fever\". Before that they had built a career on melodic soft-rock ballads.","fact":"Besides their own hits, the brothers wrote a great many songs for other performers, Barbra Streisand among them.","wiki_en":"Bee Gees","top_song":"Stayin' Alive"},{"name":"Eagles","emoji":"🦅","meta":["rock","United States","1971–present"],"description":"The Californian band joined country rock to smooth vocal harmonies and became one of the best-selling acts in American history. Their album \"Hotel California\" and its title track are a fixture of classic rock radio.","fact":"Their compilation \"Their Greatest Hits\" is counted among the best-selling albums ever released in the United States.","wiki_en":"Eagles (band)","top_song":"Hotel California"},{"name":"Fleetwood Mac","emoji":"🌙","meta":["rock","United Kingdom","1967–present"],"description":"The British-American band survived endless line-up changes and the turbulent relationships between its members, which became the raw material for \"Rumours\", one of the best-selling albums ever made. Melodic rock with a folk edge kept their sound recognisable for decades.","fact":"The affairs and break-ups inside the band while \"Rumours\" was being recorded became part of the album's legend.","wiki_en":"Fleetwood Mac","top_song":"Dreams"},{"name":"AC/DC","emoji":"⚡","meta":["hard rock","Australia","1973–present"],"description":"The Australian band built on huge, stripped-down guitar riffs is known for guitarist Angus Young appearing on stage in a schoolboy uniform. \"Back in Black\", recorded after the death of first singer Bon Scott, became one of the best-selling albums in rock history.","fact":"The band took its name from the sewing machine of a member's sister, where the letters AC/DC stood for alternating and direct current.","wiki_en":"AC/DC","top_song":"Back in Black"},{"name":"Metallica","emoji":"🤘","meta":["thrash metal","United States","1981–present"],"description":"One of the founding bands of thrash metal, they travelled from the underground to the global mainstream with the album \"Metallica\", known as the Black Album. Their music sets savage riffs alongside melodic ballads such as \"Nothing Else Matters\".","fact":"Their 1991 Black Album remains one of the best-selling albums since sales tracking by SoundScan began.","wiki_en":"Metallica","top_song":"Nothing Else Matters"},{"name":"Nirvana","emoji":"😊","meta":["grunge","United States","1987–1994"],"description":"The Seattle band led by Kurt Cobain pushed grunge and alternative rock into the mainstream in the early 1990s with the album \"Nevermind\" and the single \"Smells Like Teen Spirit\". Their music welded punk energy to pop melody.","fact":"The band ceased to exist after the death of Kurt Cobain in 1994.","wiki_en":"Nirvana (band)","top_song":"Smells Like Teen Spirit"},{"name":"U2","emoji":"🎙️","meta":["rock","Ireland","1976–present"],"description":"The Irish band fronted by Bono combines stadium-sized rock with political and social themes in its lyrics. The albums \"The Joshua Tree\" and \"Achtung Baby\" made them one of the most successful touring acts in the world.","fact":"Bono is also known for his charity and campaigning work, in particular against poverty and AIDS in Africa.","wiki_en":"U2","top_song":"With or Without You"},{"name":"Guns N' Roses","emoji":"🌹","meta":["hard rock","United States","1985–present"],"description":"Led by singer Axl Rose and guitarist Slash, the band became the face of late-1980s hard rock with its debut album \"Appetite for Destruction\". The ballad \"November Rain\", with its cinematic video, is one of the best-known rock ballads ever recorded.","fact":"\"Appetite for Destruction\" remains one of the best-selling debut albums ever released in the United States.","wiki_en":"Guns N' Roses","top_song":"Sweet Child o' Mine"},{"name":"Aerosmith","emoji":"💋","meta":["hard rock","United States","1970–present"],"description":"The Boston band led by Steven Tyler and Joe Perry is one of the great American hard rock acts, with a rise in the 1970s, a long collapse and a huge comeback in the late 1980s. The ballad \"I Don't Want to Miss a Thing\" from the film \"Armageddon\" won them a vast audience beyond rock.","fact":"Tyler and Perry were nicknamed the Toxic Twins for their volatile relationship and the constant conflict inside the band.","wiki_en":"Aerosmith","top_song":"I Don't Want to Miss a Thing"},{"name":"Bon Jovi","emoji":"🎸","meta":["rock","United States","1983–present"],"description":"The band fronted by Jon Bon Jovi joined hard rock to melodic stadium anthems such as \"Livin' on a Prayer\". Their songs became the calling card of rock radio in the 1980s and 1990s all over the world.","fact":"\"Livin' on a Prayer\" tells the story of the fictional Tommy and Gina, a couple the band went on to mention in later songs too.","wiki_en":"Bon Jovi","top_song":"Livin' on a Prayer"},{"name":"Bruce Springsteen","emoji":"🎸","meta":["rock","United States","1972–present"],"description":"The singer and songwriter known as the Boss writes about the American working class and ordinary daily life, backed by the full rock and roll force of the E Street Band. The album \"Born in the U.S.A.\" made him one of the defining rock stars of the 1980s.","fact":"The title track \"Born in the U.S.A.\" is often mistaken for a patriotic anthem, though its lyrics attack the way war veterans were treated.","wiki_en":"Bruce Springsteen","top_song":"Born in the U.S.A."},{"name":"Stevie Wonder","emoji":"🎹","meta":["soul","United States","1961–present"],"description":"Blind since early childhood, the multi-instrumentalist became a central figure in soul and funk with albums such as \"Songs in the Key of Life\". He wrote his own material, played most of the instruments himself and produced his own records.","fact":"He is one of very few artists to have won the Grammy for Album of the Year three times.","wiki_en":"Stevie Wonder","top_song":"Superstition"},{"name":"Frank Sinatra","emoji":"🎩","meta":["jazz pop","United States","1935–1995"],"description":"A singer and actor, one of the great popular vocalists of the twentieth century, known for a velvet baritone and for swinging even the slowest ballad. They called him the Voice, and \"My Way\" became a personal anthem for millions.","fact":"He was part of the Rat Pack, the celebrated circle of entertainers that also included Dean Martin and Sammy Davis Jr.","wiki_en":"Frank Sinatra","top_song":"My Way"},{"name":"Louis Armstrong","emoji":"🎺","meta":["jazz","United States","1919–1971"],"description":"A trumpeter and singer with a gravel voice, he was one of the great pioneers of jazz and did more than anyone to turn it into a solo improviser's art. His version of \"What a Wonderful World\" is among the most recognisable songs about kindness ever recorded.","fact":"He earned the nickname Satchmo because of the distinctive shape his mouth took while he played the trumpet.","wiki_en":"Louis Armstrong","top_song":"What a Wonderful World"},{"name":"Ray Charles","emoji":"🎹","meta":["rhythm and blues","United States","1947–2004"],"description":"A blind pianist and singer, he is called one of the fathers of soul music for the way he fused gospel, blues and rhythm and blues. His hit \"Georgia on My Mind\" was adopted as the official state song of Georgia.","fact":"\"Ray\", the biographical film about his life, won Jamie Foxx the Academy Award for Best Actor.","wiki_en":"Ray Charles","top_song":"Georgia on My Mind"},{"name":"Aretha Franklin","emoji":"👑","meta":["soul","United States","1956–2018"],"description":"The Queen of Soul brought a huge voice and deep gospel roots to \"Respect\", which became an anthem of both the civil rights movement and the fight for women's equality. She was the first woman inducted into the Rock and Roll Hall of Fame.","fact":"\"Respect\" was written and first recorded by Otis Redding, but her version became the definitive one and is far better known.","wiki_en":"Aretha Franklin","top_song":"Respect"},{"name":"James Brown","emoji":"🕺","meta":["funk","United States","1954–2006"],"description":"Called the Godfather of Soul and one of the inventors of funk, he built ferocious live shows out of sharp dance moves and a hard-driving horn section, setting the language for the funk and hip-hop that followed. Endless touring earned him the title of the hardest-working man in show business.","fact":"His rhythmic funk records later became some of the most frequently sampled recordings in the history of hip-hop.","wiki_en":"James Brown","top_song":"I Got You (I Feel Good)"},{"name":"Marvin Gaye","emoji":"🎙️","meta":["soul","United States","1961–1984"],"description":"One of the great voices of Motown, he moved from breezy soul duets to the socially charged concept album \"What's Going On\", about war and injustice. His velvet vocals also made him one of the defining singers of romantic soul.","fact":"He was shot dead by his own father in 1984, one day before his forty-fifth birthday.","wiki_en":"Marvin Gaye","top_song":"What's Going On"},{"name":"Bob Marley & The Wailers","emoji":"🦁","meta":["reggae","Jamaica","1963–1981"],"description":"The Jamaican band led by Bob Marley made reggae known the world over and turned it into the voice of the Rastafari movement and the struggle for justice. Songs such as \"One Love\" and \"No Woman, No Cry\" became cultural emblems of Jamaica.","fact":"Marley was a committed Rastafarian, and that faith shaped much of what his songs were about.","wiki_en":"Bob Marley and the Wailers","top_song":"No Woman, No Cry"},{"name":"Jimi Hendrix","emoji":"🎸","meta":["rock","United States","1966–1970"],"description":"A guitarist whose inventive playing, from his use of effects to the way he drew sound out of the instrument, changed what people believed an electric guitar could do. His distorted version of the American anthem at Woodstock became one of rock's landmark moments.","fact":"He died at the age of 27, joining the list of musicians known as the 27 Club.","wiki_en":"Jimi Hendrix","top_song":"Purple Haze"},{"name":"The Doors","emoji":"🚪","meta":["rock","United States","1965–1973"],"description":"The band led by poet and singer Jim Morrison joined psychedelic rock to dark, literary lyrics and theatrical performances. Their breakthrough hit \"Light My Fire\" and the brooding epic \"The End\" showed just how wide their range was.","fact":"Morrison, like Jimi Hendrix, died at 27 and is also counted among the 27 Club.","wiki_en":"The Doors","top_song":"Light My Fire"},{"name":"The Who","emoji":"🎯","meta":["rock","United Kingdom","1964–present"],"description":"The British band is known for ferocious live shows, for smashing instruments on stage and for \"Tommy\", one of the first rock operas ever written. Guitarist Pete Townshend became famous for his trademark windmill strum, the arm swinging in a full circle over the strings.","fact":"Their rock opera \"Tommy\" was later made into a film and staged as a theatrical musical.","wiki_en":"The Who","top_song":"My Generation"},{"name":"Deep Purple","emoji":"🎹","meta":["hard rock","United Kingdom","1968–present"],"description":"One of the founding bands of hard rock, known for setting heavy guitar riffs against the classically trained organ playing of Jon Lord. The riff from \"Smoke on the Water\" became one of the first things every beginner guitarist learns.","fact":"\"Smoke on the Water\" describes a real fire at a concert venue in Montreux that the band watched with its own eyes.","wiki_en":"Deep Purple","top_song":"Smoke on the Water"},{"name":"Black Sabbath","emoji":"🤘","meta":["heavy metal","United Kingdom","1968–2017"],"description":"The band fronted by Ozzy Osbourne is considered one of the founders of heavy metal: their bleak, crushing riffs and gothic imagery set the language of the genre for decades. They took their name from an old horror film, and the song of the same name opened their debut album.","fact":"Many rock historians call their 1970 debut album the first true heavy metal record.","wiki_en":"Black Sabbath","top_song":"Paranoid"},{"name":"Kiss","emoji":"🎭","meta":["hard rock","United States","1973–present"],"description":"The band became famous not only for its music but for its elaborate face paint and pyrotechnic shows full of fire-breathing and fake blood. Their stage alter egos, the Catman, the Starchild, the Demon and the Spaceman, became part of pop culture.","fact":"The band's fan following is called the Kiss Army, a name the fans themselves came up with back in the 1970s.","wiki_en":"Kiss (band)","top_song":"Rock and Roll All Nite"},{"name":"Van Halen","emoji":"🎸","meta":["hard rock","United States","1972–2020"],"description":"Led by the virtuoso guitarist Eddie Van Halen, the band rewrote the rules of rock guitar with his two-handed tapping technique. The hit \"Jump\", built around a bright synthesiser hook, became their best-known song and their way into the mainstream.","fact":"It was Eddie Van Halen who played the guitar solo on Michael Jackson's \"Beat It\".","wiki_en":"Van Halen","top_song":"Jump"},{"name":"Scorpions","emoji":"🦂","meta":["hard rock","Germany","1965–present"],"description":"One of the most successful bands in the history of European hard rock, the Germans became famous for \"Wind of Change\", a ballad written under the impression of the changes at the end of the Cold War. Their driving guitar hits made them stars well beyond Europe.","fact":"The video and lyrics of \"Wind of Change\" are tied to the fall of the Berlin Wall and the collapse of the USSR, which the band witnessed.","wiki_en":"Scorpions (band)","top_song":"Wind of Change"},{"name":"Depeche Mode","emoji":"🎹","meta":["synth-pop","United Kingdom","1980–present"],"description":"A band present at the birth of synth-pop, they moved over time towards a darker, more industrial sound while remaining one of the most influential electronic rock acts anywhere. Their hit \"Enjoy the Silence\" set melancholy lyrics over a dance beat.","fact":"Despite their electronic sound, the band leans heavily on live instruments in concert.","wiki_en":"Depeche Mode","top_song":"Enjoy the Silence"},{"name":"The Cure","emoji":"🖤","meta":["gothic rock","United Kingdom","1976–present"],"description":"The band led by Robert Smith, whose backcombed hair and bright red lipstick became the visual shorthand for gothic rock and new wave. Their music swings from bleak, atmospheric pieces to light pop hits such as \"Friday I'm in Love\".","fact":"Robert Smith's trademark smudged make-up became a recognisable part of goth subculture style.","wiki_en":"The Cure","top_song":"Friday I'm in Love"},{"name":"The Police","emoji":"🚨","meta":["rock","United Kingdom","1977–1986"],"description":"The trio led by Sting combined punk energy with reggae rhythms and jazz sophistication, which made them one of the most original rock bands of the late 1970s. Their song \"Every Breath You Take\" is often taken for a love song, though it actually describes obsessive surveillance.","fact":"Despite its unsettling lyrics about being watched, \"Every Breath You Take\" is often played at weddings.","wiki_en":"The Police","top_song":"Every Breath You Take"},{"name":"Sting","emoji":"🐝","meta":["rock","United Kingdom","1977–present"],"description":"After The Police broke up, their former frontman built a long solo career mixing rock, jazz and world music. He picked up the stage name Sting because of a black-and-yellow striped jumper that made him look like a bee.","fact":"Before his music career he spent several years working as a schoolteacher in England.","wiki_en":"Sting (musician)","top_song":"Shape of My Heart"},{"name":"Phil Collins","emoji":"🥁","meta":["pop rock","United Kingdom","1970–present"],"description":"The drummer and singer of Genesis also built an enormous solo career on ballads such as \"Against All Odds\" and the brooding hit \"In the Air Tonight\". He is one of very few musicians to have found worldwide success in a band and on his own at the same time.","fact":"The famous drum break in \"In the Air Tonight\" only arrives several minutes into the song, which made it a startling and unforgettable moment.","wiki_en":"Phil Collins","top_song":"In the Air Tonight"},{"name":"Genesis","emoji":"🎹","meta":["progressive rock","United Kingdom","1967–2022"],"description":"The British band began as a theatrical progressive rock outfit fronted by Peter Gabriel, and after he left, under Phil Collins, turned into one of the most successful pop-rock acts of the 1980s. Their sound travelled a long way, from intricate suites to radio-sized hits.","fact":"Their early shows were known for the theatrical costumes and masks that Peter Gabriel wore on stage.","wiki_en":"Genesis (band)","top_song":"Invisible Touch"},{"name":"Dire Straits","emoji":"🎸","meta":["rock","United Kingdom","1977–1995"],"description":"The band led by guitarist Mark Knopfler is known for a clean, instantly recognisable guitar tone free of effects and for wry, observant lyrics. The album \"Brothers in Arms\" and its hit \"Money for Nothing\" made them one of the best-selling acts of the 1980s.","fact":"The video for \"Money for Nothing\" was one of the first to use computer animation and became a landmark of the MTV era.","wiki_en":"Dire Straits","top_song":"Sultans of Swing"},{"name":"Simon & Garfunkel","emoji":"🎼","meta":["folk rock","United States","1957–1970"],"description":"The duo of Paul Simon and Art Garfunkel became famous for delicate harmonies and lyrical folk ballads, among them \"The Sound of Silence\" and the soundtrack to the film \"The Graduate\". Their records became the sound of the American folk scene of the 1960s.","fact":"Their song \"Mrs. Robinson\" was written specially for \"The Graduate\" and names the film's character outright.","wiki_en":"Simon & Garfunkel","top_song":"The Sound of Silence"},{"name":"The Beach Boys","emoji":"🏄","meta":["pop rock","United States","1961–present"],"description":"The Californian band led by Brian Wilson made surf rock famous with songs about surfing, cars and the sunlit coast. Their harmonically intricate album \"Pet Sounds\" went on to shape all the pop music that followed it, The Beatles included.","fact":"In the mid-1960s Brian Wilson stopped touring and concentrated on studio work while the rest of the band played the shows.","wiki_en":"The Beach Boys","top_song":"Good Vibrations"},{"name":"Creedence Clearwater Revival","emoji":"🌧️","meta":["rock","United States","1967–1972"],"description":"The band led by John Fogerty joined rock and roll to the blues and country sound of the swampy American South, even though the musicians themselves came from California. Their song \"Fortunate Son\" became one of the great protest anthems of the Vietnam War years.","fact":"\"Fortunate Son\" is heard in countless films about the Vietnam War and has become its musical shorthand.","wiki_en":"Creedence Clearwater Revival","top_song":"Fortunate Son"},{"name":"Chuck Berry","emoji":"🎸","meta":["rock and roll","United States","1953–2017"],"description":"One of the founding fathers of rock and roll, whose guitar riffs and duck-walk stage move shaped whole generations of rock musicians, The Beatles and The Rolling Stones among them. \"Johnny B. Goode\" became something like the anthem of the genre.","fact":"\"Johnny B. Goode\" was placed on the Voyager golden record and sent into space as a sample of music from Earth.","wiki_en":"Chuck Berry","top_song":"Johnny B. Goode"},{"name":"Johnny Cash","emoji":"🖤","meta":["country","United States","1954–2003"],"description":"They called him the Man in Black for his stage look, and his deep baritone and songs about prisoners, the poor and the outcast made him one of the central figures in country music. The live album \"At Folsom Prison\", recorded inside the prison itself, is a classic of the genre.","fact":"Late in life he recorded a cover of \"Hurt\" by Nine Inch Nails, and its video became one of his best-known pieces of work.","wiki_en":"Johnny Cash","top_song":"Ring of Fire"},{"name":"Dolly Parton","emoji":"🎀","meta":["country","United States","1959–present"],"description":"A singer and songwriter, one of the most successful women in the history of country music, known for her glittering image and for \"I Will Always Love You\", later made famous by Whitney Houston. She is also a prolific philanthropist and owns the Dollywood theme park.","fact":"She wrote \"I Will Always Love You\" as a farewell to her business partner Porter Wagoner, not as a love song.","wiki_en":"Dolly Parton","top_song":"Jolene"},{"name":"Tina Turner","emoji":"⚡","meta":["rock soul","United States","1957–2009"],"description":"Called the Queen of Rock and Roll for her raw voice and electrifying stage presence, she kept performing even after a brutal split from her first husband and musical partner Ike Turner. The solo hit \"What's Love Got to Do with It\" brought her a whole new peak later in life.","fact":"Her story of surviving domestic abuse and returning as a solo star became the basis for a biographical film and a stage musical.","wiki_en":"Tina Turner","top_song":"What's Love Got to Do with It"},{"name":"Cher","emoji":"💫","meta":["pop","United States","1965–present"],"description":"A singer and actress with one of the longest and most successful careers in show business, she started in the duo Sonny & Cher and went on to become a solo pop star. The hit \"Believe\", with its distinctive digital vocal processing, became a defining sound of late-1990s dance pop.","fact":"The autotuned vocal on \"Believe\" was so recognisable that the technique is sometimes called the Cher effect.","wiki_en":"Cher","top_song":"Believe"},{"name":"Diana Ross","emoji":"👑","meta":["soul","United States","1959–present"],"description":"The lead singer of The Supremes became one of the great stars of the Motown label and then built a successful solo career in soul and disco. Her elegant image and voice made her a style icon of the 1960s and 1970s.","fact":"With The Supremes she was part of one of the most commercially successful female vocal trios in American music history.","wiki_en":"Diana Ross","top_song":"I'm Coming Out"},{"name":"Donna Summer","emoji":"🪩","meta":["disco","United States","1968–2012"],"description":"Known as the Queen of Disco, she helped define the sound of the genre in the 1970s with the extended electronic track \"Love to Love You Baby\" and her work with producer Giorgio Moroder. The hit \"I Feel Love\" went on to influence electronic dance music as a whole.","fact":"\"I Feel Love\", built on a purely synthesised backing, is considered one of the first records to foreshadow the sound of electronic music to come.","wiki_en":"Donna Summer","top_song":"I Feel Love"},{"name":"Barbra Streisand","emoji":"🎭","meta":["pop","United States","1962–present"],"description":"A singer and actress, one of the very few performers to win recognition in music, in cinema and on Broadway alike. Her powerful voice made its name in the musical and film \"Funny Girl\", and \"Woman in Love\" became one of the biggest hits of her career.","fact":"Over her career she has collected an Oscar, a Grammy and an Emmy, a combination of awards very few performers manage.","wiki_en":"Barbra Streisand","top_song":"Woman in Love"},{"name":"Céline Dion","emoji":"🚢","meta":["pop","Canada","1981–present"],"description":"The Canadian singer with the soaring voice became a global star thanks to \"My Heart Will Go On\" from the film \"Titanic\". Long before that English-language breakthrough she was already a leading name in French-language pop.","fact":"Her ballad \"My Heart Will Go On\" became one of the best-selling singles ever recorded by a woman.","wiki_en":"Celine Dion","top_song":"My Heart Will Go On"},{"name":"Mariah Carey","emoji":"🎄","meta":["pop","United States","1990–present"],"description":"A singer with an extraordinary vocal range and complete command of the whistle register, she is one of the most commercially successful female artists of all time. Her Christmas song \"All I Want for Christmas Is You\" has become one of the most recognisable holiday records ever made.","fact":"\"All I Want for Christmas Is You\" climbs back into the charts every December, decades after it was first released.","wiki_en":"Mariah Carey","top_song":"All I Want for Christmas Is You"},{"name":"Janet Jackson","emoji":"💃","meta":["pop","United States","1982–present"],"description":"A singer and dancer and Michael Jackson's younger sister, she built a major career of her own with albums such as \"Rhythm Nation 1814\", which set dance pop against social themes. Her intricate, tightly synchronised dance routines became the template for the pop stars who followed.","fact":"\"Rhythm Nation 1814\" tackled social injustice, which was unusual for a mainstream pop album at the time.","wiki_en":"Janet Jackson","top_song":"Rhythm Nation"},{"name":"George Michael","emoji":"🕶️","meta":["pop","United Kingdom","1981–2016"],"description":"He started out in the duo Wham! and then became a solo star with \"Faith\", an album that pulled soul, pop and rock together. \"Last Christmas\", recorded back in his Wham! days, turned into one of Britain's defining Christmas songs.","fact":"For all its popularity, \"Last Christmas\" never reached number one on the British chart in the year it came out.","wiki_en":"George Michael","top_song":"Careless Whisper"},{"name":"Lionel Richie","emoji":"🎤","meta":["soul pop","United States","1968–present"],"description":"A singer and songwriter who began with the Commodores and then built a solo career on melodic ballads such as \"Hello\". He is also one of the co-writers of the charity anthem \"We Are the World\", and his easy, warm songwriting shaped soft soul pop across the 1980s.","fact":"He also recorded the hit \"Endless Love\" as a duet with Diana Ross.","wiki_en":"Lionel Richie","top_song":"Hello"},{"name":"Billy Joel","emoji":"🎹","meta":["pop rock","United States","1964–present"],"description":"A pianist and songwriter known for telling stories about ordinary American lives in songs such as \"Piano Man\" and \"Uptown Girl\". His albums mix rock and pop with traces of the classical music he studied as a young man.","fact":"\"Piano Man\" grew out of his own stint playing a Los Angeles lounge bar under an assumed name.","wiki_en":"Billy Joel","top_song":"Piano Man"},{"name":"Paul McCartney","emoji":"🎸","meta":["rock","United Kingdom","1957–present"],"description":"One of the two main songwriters in The Beatles, he founded another successful band, Wings, after the group broke up, and is still recording under his own name. He is counted among the most successful composers in the history of popular music.","fact":"He is credited with writing more chart-topping songs than almost anyone, both with The Beatles and on his own.","wiki_en":"Paul McCartney","top_song":"Band on the Run"},{"name":"John Lennon","emoji":"👓","meta":["rock","United Kingdom","1957–1980"],"description":"A founder of The Beatles, after the band split he released solo albums with a sharp political edge, among them the anthem \"Imagine\". Together with his wife Yoko Ono he threw himself into anti-war activism.","fact":"He was shot dead by a fan outside his home in New York in 1980.","wiki_en":"John Lennon","top_song":"Imagine"},{"name":"Eric Clapton","emoji":"🎸","meta":["blues rock","United Kingdom","1963–present"],"description":"A guitarist who passed through The Yardbirds, Cream and Derek and the Dominos, he is called one of the greatest guitarists in rock, and fans once wrote \"Clapton is God\" on London walls. His ballad \"Tears in Heaven\" was written after the tragic death of his son.","fact":"He has been inducted into the Rock and Roll Hall of Fame three times: with The Yardbirds, with Cream and as a solo artist.","wiki_en":"Eric Clapton","top_song":"Tears in Heaven"},{"name":"Rod Stewart","emoji":"🎤","meta":["rock","United Kingdom","1964–present"],"description":"A singer with an unmistakable rasp, he travelled from blues-rock bands such as Faces to a solo career spanning rock, pop and the Great American Songbook. The hit \"Maggie May\" made him a star in the early 1970s.","fact":"Besides music, he is a devoted football fan and is known for a huge model railway he spent decades building at home.","wiki_en":"Rod Stewart","top_song":"Maggie May"},{"name":"Tom Petty","emoji":"🎸","meta":["rock","United States","1976–2017"],"description":"The singer and leader of Tom Petty and the Heartbreakers wrote plain-spoken rock songs such as \"Free Fallin'\" and \"American Girl\" that became the backbone of American classic rock radio. His music paired garage-rock directness with pop's melodic precision.","fact":"He was also a member of the supergroup Traveling Wilburys, alongside Bob Dylan, George Harrison, Roy Orbison and Jeff Lynne.","wiki_en":"Tom Petty","top_song":"Free Fallin'"},{"name":"Neil Young","emoji":"🎸","meta":["rock","Canada","1960–present"],"description":"The Canadian singer and guitarist worked both alone and with Buffalo Springfield and Crosby, Stills, Nash & Young, and is known for a piercing voice and a restless range, from acoustic folk to raw garage rock. He is called the godfather of grunge for his influence on bands like Pearl Jam and Nirvana.","fact":"He is one of the founders of Farm Aid, the festival that raises money to support American farmers.","wiki_en":"Neil Young","top_song":"Heart of Gold"},{"name":"Santana","emoji":"🎸","meta":["Latin rock","United States","1966–present"],"description":"The band led by guitarist Carlos Santana welded rock to Latin American and Afro-Cuban rhythms as early as their set at Woodstock. His singing guitar tone, with its endless sustain, has been the group's signature for decades.","fact":"Their performance at Woodstock in 1969 made the band famous before their debut album had even been released.","wiki_en":"Santana (band)","top_song":"Smooth"},{"name":"Earth, Wind & Fire","emoji":"🔥","meta":["funk","United States","1969–present"],"description":"The American band fused funk, soul, jazz and elements of African music into a bright, optimistic sound carried by a powerful horn section. Their hit \"September\", with its irresistible chorus, remains one of the most recognisable dance records ever made.","fact":"The 21st of September, the date named in \"September\", is celebrated by fans every year as an unofficial holiday.","wiki_en":"Earth, Wind & Fire","top_song":"September"},{"name":"Boney M.","emoji":"🪩","meta":["disco","Germany","1976–1986"],"description":"A disco project put together by German producer Frank Farian with singers of Caribbean origin, it became one of the emblems of the European disco era. Hits such as \"Rasputin\" and \"Daddy Cool\" are still played on dance floors today.","fact":"The group was one of the most popular Western acts behind the Iron Curtain, where access to Western pop music was tightly restricted.","wiki_en":"Boney M.","top_song":"Rasputin"},{"name":"Modern Talking","emoji":"🎤","meta":["Euro-disco","Germany","1983–2003"],"description":"The German duo of Dieter Bohlen and Thomas Anders became the face of Euro-disco and synth-pop in the mid-1980s, above all in Eastern Europe. Their unmistakable mix of soaring falsetto choruses and a steady dance beat defined the sound of an era.","fact":"The duo split at the end of the 1980s, then came back more than ten years later and returned to the European charts.","wiki_en":"Modern Talking","top_song":"You're My Heart, You're My Soul"},{"name":"a-ha","emoji":"✏️","meta":["synth-pop","Norway","1982–present"],"description":"The Norwegian trio made their name with \"Take On Me\" and a video that was groundbreaking for its time, blending live action with hand-drawn animation. Their melodic synth-pop made them one of the most successful Scandinavian acts on the world stage.","fact":"The pencil-sketch video for \"Take On Me\" was among the first to use rotoscope animation on such a scale.","wiki_en":"A-ha","top_song":"Take On Me"},{"name":"Roxette","emoji":"🎸","meta":["pop rock","Sweden","1986–2016"],"description":"The Swedish duo of Marie Fredriksson and Per Gessle became one of the most successful European pop-rock acts on the American market with hits such as \"It Must Have Been Love\" and \"Listen to Your Heart\". Their song from the film \"Pretty Woman\" brought them worldwide fame.","fact":"\"It Must Have Been Love\" owes much of its success to the film \"Pretty Woman\", starring Julia Roberts.","wiki_en":"Roxette","top_song":"It Must Have Been Love"},{"name":"Ace of Base","emoji":"🌊","meta":["Eurodance","Sweden","1990–2010s"],"description":"The Swedish group became one of the most successful Eurodance acts of the 1990s with their debut album \"Happy Nation\" and the worldwide hit \"The Sign\". Their blend of reggae rhythms and electronic pop was recognisable from the first few seconds.","fact":"Their debut album is one of the best-selling debut albums in the history of pop music.","wiki_en":"Ace of Base","top_song":"The Sign"},{"name":"Pet Shop Boys","emoji":"🎩","meta":["synth-pop","United Kingdom","1981–present"],"description":"The British duo of Neil Tennant and Chris Lowe are known for a wry, deadpan delivery and for danceable synth-pop hits such as \"West End Girls\". Their deliberately impassive stage presence plays against lush, colourful electronic arrangements.","fact":"Before his music career, Neil Tennant worked as a journalist and editor at the music magazine Smash Hits.","wiki_en":"Pet Shop Boys","top_song":"West End Girls"},{"name":"Duran Duran","emoji":"🦋","meta":["new wave","United Kingdom","1978–present"],"description":"The British band is one of the icons of new wave and the early MTV era, known for stylish videos and the hit \"Hungry Like the Wolf\". They took their name from a villain in the science fiction film \"Barbarella\".","fact":"They recorded the song \"A View to a Kill\" for the James Bond film of the same name.","wiki_en":"Duran Duran","top_song":"Hungry Like the Wolf"},{"name":"Eurythmics","emoji":"🎹","meta":["synth-pop","United Kingdom","1980–2005"],"description":"The duo of Annie Lennox and Dave Stewart set an electronic synth-pop backdrop against Lennox's powerful soul voice. Their hit \"Sweet Dreams (Are Made of This)\", built on a hypnotic synthesiser riff, became one of the emblems of the decade.","fact":"Annie Lennox's androgynous look, with cropped orange hair, became one of the defining images of 1980s pop.","wiki_en":"Eurythmics","top_song":"Sweet Dreams (Are Made of This)"},{"name":"Cyndi Lauper","emoji":"🌈","meta":["pop","United States","1980–present"],"description":"With her riot of colour and a distinctive high voice, she became one of the biggest pop stars of the early 1980s thanks to her debut album \"She's So Unusual\". Her hit \"Girls Just Want to Have Fun\" turned into an unofficial anthem of female independence.","fact":"She also found success writing music for Broadway musicals, notably \"Kinky Boots\".","wiki_en":"Cyndi Lauper","top_song":"Girls Just Want to Have Fun"},{"name":"Blondie","emoji":"💛","meta":["new wave","United States","1974–present"],"description":"The band fronted by Debbie Harry was among the first to carry New York punk aesthetics into the mainstream, mixing rock with disco and the newly emerging sound of rap. Their hit \"Rapture\" contained one of the first rap passages ever to top the pop charts.","fact":"The band's name came from what passers-by used to shout at the blonde Debbie Harry in the street.","wiki_en":"Blondie (band)","top_song":"Heart of Glass"},{"name":"Talking Heads","emoji":"🕴️","meta":["new wave","United States","1975–1991"],"description":"The band led by David Byrne joined art rock to African rhythms and paranoid lyrics about modern city life. Their concert film \"Stop Making Sense\", with Byrne's enormous oversized suit, is considered one of the finest ever made.","fact":"The band formed out of art school students and began playing at the New York club CBGB.","wiki_en":"Talking Heads","top_song":"Once in a Lifetime"},{"name":"Ramones","emoji":"🧥","meta":["punk rock","United States","1974–1996"],"description":"The New York band is considered one of the founders of punk rock: short, fast songs, matching leather jackets and the shared stage surname Ramone set the template for the whole genre. Their energy shaped punk scenes on both sides of the Atlantic.","fact":"They borrowed the surname Ramone from Paul Ramon, the alias Paul McCartney used as a young musician.","wiki_en":"Ramones","top_song":"Blitzkrieg Bop"},{"name":"Sex Pistols","emoji":"🧷","meta":["punk rock","United Kingdom","1975–1978"],"description":"The scandalous British band became the symbol of the punk revolt of the mid-1970s with the defiant lyrics of \"God Save the Queen\" and a raw, aggressive sound. For all their brief existence, their influence on punk culture worldwide was enormous.","fact":"Their single \"God Save the Queen\", released in the year of the Queen's jubilee, was banned by many British radio stations.","wiki_en":"Sex Pistols","top_song":"Anarchy in the U.K."},{"name":"The Clash","emoji":"🧷","meta":["punk rock","United Kingdom","1976–1986"],"description":"Billed as the only band that matters, they mixed punk with reggae, ska and rockabilly and gave their lyrics a sharp political and social edge. The double album \"London Calling\" is regarded as one of the greatest records in rock history.","fact":"The cover of \"London Calling\", showing a bass guitar being smashed, echoes the classic look of 1950s rock and roll sleeves.","wiki_en":"The Clash","top_song":"London Calling"},{"name":"Iron Maiden","emoji":"💀","meta":["heavy metal","United Kingdom","1975–present"],"description":"One of the key bands of the new wave of British heavy metal, known for long multi-part songs, lyrics drawn from myth and history, and the zombie mascot Eddie on their album covers. Their singer Bruce Dickinson is also a professional airline pilot.","fact":"Bruce Dickinson personally flew Ed Force One, the plane that carried the band and its equipment on tour.","wiki_en":"Iron Maiden","top_song":"The Trooper"},{"name":"Judas Priest","emoji":"🖤","meta":["heavy metal","United Kingdom","1969–present"],"description":"The British band is one of those that defined the classic look and sound of heavy metal: leather, studs and blistering solos traded between two lead guitarists. Songs such as \"Breaking the Law\" became textbook examples of the genre.","fact":"Their singer Rob Halford is credited with inventing the leather-and-studs stage look that metal musicians adopted wholesale.","wiki_en":"Judas Priest","top_song":"Breaking the Law"},{"name":"Ozzy Osbourne","emoji":"🦇","meta":["heavy metal","United Kingdom","1968–2025"],"description":"The former Black Sabbath singer launched a hugely successful solo career in heavy metal and later reached a far wider audience through the reality show \"The Osbournes\". His grim stage persona earned him the nickname the Prince of Darkness.","fact":"His scandalous reputation dates from the night he bit the head off a bat that had been thrown onto the stage.","wiki_en":"Ozzy Osbourne","top_song":"Crazy Train"},{"name":"Def Leppard","emoji":"⚡","meta":["hard rock","United Kingdom","1977–present"],"description":"The British band is one of the most successful acts of 1980s glam and hard rock, known for the album \"Hysteria\" and its run of hit singles. Drummer Rick Allen kept playing with the band even after losing an arm in a car crash.","fact":"After losing his left arm in a car accident, drummer Rick Allen designed a custom electronic kit and carried on playing in the band.","wiki_en":"Def Leppard","top_song":"Pour Some Sugar on Me"},{"name":"Journey","emoji":"✨","meta":["rock","United States","1973–present"],"description":"The American band is known for a melodic stadium rock sound and the soaring voice of Steve Perry during their golden years. Their ballad \"Don't Stop Believin'\" was reborn decades later through films and television series.","fact":"Released in 1981, \"Don't Stop Believin'\" went on to become one of the most downloaded songs of the twentieth century.","wiki_en":"Journey (band)","top_song":"Don't Stop Believin'"},{"name":"TOTO","emoji":"🌍","meta":["rock","United States","1977–present"],"description":"Assembled from seasoned Los Angeles session musicians, the band is known for a polished, melodic sound and for the hit \"Africa\" with its instantly recognisable keyboard intro. Their craft made them some of the most sought-after players in the industry.","fact":"In the 2010s \"Africa\" enjoyed a whole new wave of popularity online and in memes, decades after its release.","wiki_en":"Toto (band)","top_song":"Africa"},{"name":"Foreigner","emoji":"🎸","meta":["rock","United States","1976–present"],"description":"The Anglo-American band became one of the great names in melodic stadium rock of the late 1970s with hits such as \"I Want to Know What Love Is\". Their mix of hard riffs and romantic ballads set the template for the arena rock sound.","fact":"The ballad \"I Want to Know What Love Is\" was recorded with a gospel choir, which gave it a scale unusual for a rock hit.","wiki_en":"Foreigner (band)","top_song":"I Want to Know What Love Is"},{"name":"Europe","emoji":"🌌","meta":["hard rock","Sweden","1979–present"],"description":"The Swedish band became famous worldwide for the synthesiser riff and huge sound of \"The Final Countdown\", one of the defining rock anthems of the 1980s. Joey Tempest has remained their frontman and principal songwriter throughout.","fact":"The synth riff of \"The Final Countdown\" is so recognisable that it is used as a standalone musical cue at sports events and shows worldwide.","wiki_en":"Europe (band)","top_song":"The Final Countdown"},{"name":"ZZ Top","emoji":"🧔","meta":["blues rock","United States","1969–present"],"description":"The Texas trio is known for the enormous beards worn by two of its three members and for a blues-rock sound laced with synth-pop, heard in hits such as \"Sharp Dressed Man\". Their look, all sunglasses and fur-covered guitars, became the band's calling card.","fact":"The drummer's name is Frank Beard, though he is, paradoxically, the only member of the band without one.","wiki_en":"ZZ Top","top_song":"Sharp Dressed Man"},{"name":"Lynyrd Skynyrd","emoji":"🎸","meta":["Southern rock","United States","1964–present"],"description":"One of the great Southern rock bands, known for the anthem \"Sweet Home Alabama\" and the epic ballad \"Free Bird\", which ends in a long guitar solo. The original line-up's career was cut short by a plane crash in 1977.","fact":"The 1977 crash killed several members of the band, among them singer Ronnie Van Zant.","wiki_en":"Lynyrd Skynyrd","top_song":"Sweet Home Alabama"},{"name":"Red Hot Chili Peppers","emoji":"🌶️","meta":["alternative rock","United States","1983–present"],"description":"The Californian band joined funk-rock grooves to punk energy and melodic ballads such as \"Under the Bridge\", and has stayed at the top of rock for four decades. Their bassist Flea is famous for his virtuoso slap technique.","fact":"\"Under the Bridge\" was written by singer Anthony Kiedis about his struggle with drug addiction and his loneliness in Los Angeles.","wiki_en":"Red Hot Chili Peppers","top_song":"Under the Bridge"},{"name":"Pearl Jam","emoji":"🎸","meta":["grunge","United States","1990–present"],"description":"One of the central bands of the Seattle grunge scene, known for Eddie Vedder's raw, emotional voice and for socially conscious lyrics. Unlike many of their contemporaries, the band is still touring and recording decades on.","fact":"For years the band refused on principle to sell tickets through Ticketmaster, in protest at its high service fees.","wiki_en":"Pearl Jam","top_song":"Alive"},{"name":"Radiohead","emoji":"🐻","meta":["alternative rock","United Kingdom","1985–present"],"description":"The British band led by Thom Yorke travelled from guitar-driven alternative rock to the experimental electronic sound of \"Kid A\". They are called one of the most influential and least predictable rock bands of their generation.","fact":"The band first released the album \"In Rainbows\" on a pay-what-you-want basis, an unusual experiment for a major artist.","wiki_en":"Radiohead","top_song":"Creep"},{"name":"Oasis","emoji":"🎸","meta":["Britpop","United Kingdom","1991–present"],"description":"The Manchester band built around the Gallagher brothers was one of the defining Britpop acts of the 1990s, known for the anthem \"Wonderwall\" and for the endless public feuding between Liam and Noel. \"(What's the Story) Morning Glory?\" became one of the best-selling albums in British history.","fact":"The constant fighting between the Gallagher brothers eventually broke the band up, and years later led to an unexpected reunion.","wiki_en":"Oasis (band)","top_song":"Wonderwall"},{"name":"Blur","emoji":"🚴","meta":["Britpop","United Kingdom","1988–present"],"description":"The British band led by Damon Albarn fought Oasis for the title of leading Britpop act of the 1990s. Their album \"Parklife\", full of wry observations about everyday British life, became one of the landmark records of the genre.","fact":"The 1995 chart battle between Blur and Oasis for the number one spot was christened the Battle of Britpop by the British press.","wiki_en":"Blur (band)","top_song":"Song 2"},{"name":"The Cranberries","emoji":"🎤","meta":["alternative rock","Ireland","1989–2019"],"description":"The Irish band, with the unmistakable Celtic lilt of singer Dolores O'Riordan, became famous for \"Zombie\", a song about the violence in Northern Ireland. Their melodic alternative rock made them one of the most successful Irish acts of the 1990s.","fact":"\"Zombie\" was written in response to a bombing in the English town of Warrington and dedicated to the victims of the Northern Ireland conflict.","wiki_en":"The Cranberries","top_song":"Zombie"},{"name":"R.E.M.","emoji":"🌙","meta":["alternative rock","United States","1980–2011"],"description":"The band from Georgia were pioneers of American alternative rock, starting out on the independent scene and later becoming a global name with hits such as \"Losing My Religion\". Michael Stipe's famously mumbled singing on the early records became part of their signature sound.","fact":"The band's name was picked at random from a dictionary and happens to be the abbreviation for the dreaming phase of sleep, rapid eye movement.","wiki_en":"R.E.M.","top_song":"Losing My Religion"},{"name":"Green Day","emoji":"💚","meta":["punk rock","United States","1986–present"],"description":"The Californian band brought punk rock back into the mainstream in the 1990s with the album \"Dookie\", then widened their reach with the politically charged rock opera \"American Idiot\". Their short, fast songs made the genre accessible to a mass audience.","fact":"Their rock opera \"American Idiot\" was later adapted into a Broadway musical.","wiki_en":"Green Day","top_song":"Boulevard of Broken Dreams"},{"name":"The Offspring","emoji":"🤘","meta":["punk rock","United States","1984–present"],"description":"The Californian band was one of those that carried pop punk to mass success in the mid-1990s with the album \"Smash\" and sardonic hits such as \"Self Esteem\". Their sound pairs fast punk rock with choruses that stick on first listen.","fact":"Their album \"Smash\" is one of the best-selling albums ever released on an independent label.","wiki_en":"The Offspring","top_song":"Self Esteem"},{"name":"blink-182","emoji":"😜","meta":["pop punk","United States","1992–present"],"description":"The Californian trio became the face of late-1990s pop punk with fast guitar riffs, melodic choruses and a provocative sense of humour running through their lyrics and videos. The album \"Enema of the State\" made them MTV stars.","fact":"Their videos were often built around deliberately crude, outrageous humour, which became part of the band's image.","wiki_en":"Blink-182","top_song":"All the Small Things"},{"name":"Linkin Park","emoji":"⛓️","meta":["nu metal","United States","1996–present"],"description":"The band fronted by Chester Bennington joined nu metal to electronic textures and Mike Shinoda's rapping, which made \"Hybrid Theory\" one of the best-selling debuts of the early 2000s. Their music set aggression against strikingly vulnerable lyrics.","fact":"\"Hybrid Theory\" is one of the best-selling debut albums of the twenty-first century in the United States.","wiki_en":"Linkin Park","top_song":"In the End"},{"name":"System Of A Down","emoji":"🌀","meta":["alternative metal","United States","1994–present"],"description":"The band of Armenian descent is known for lurching shifts of tempo and mood within a single song, politically charged lyrics and the extraordinary voice of Serj Tankian. \"Chop Suey!\" became one of the most recognisable songs in alternative metal.","fact":"The band's members, all of Armenian descent, raise the subject of the Armenian genocide both in their songs and in public.","wiki_en":"System of a Down","top_song":"Chop Suey!"},{"name":"Rammstein","emoji":"🔥","meta":["industrial metal","Germany","1994–present"],"description":"The German band is known for a crushing industrial metal sound, lyrics sung mostly in German, and pyrotechnic stage shows on an enormous scale. Their visual style and provocative videos have repeatedly caused public controversy.","fact":"They spell their name with a double m, even though the German town of Ramstein, which it is associated with, has only one.","wiki_en":"Rammstein","top_song":"Du Hast"},{"name":"Limp Bizkit","emoji":"🧢","meta":["nu metal","United States","1994–present"],"description":"The band led by Fred Durst was one of the most commercially successful nu metal acts of the late 1990s, welding heavy riffs to rapped vocals and hip-hop production. Durst's red baseball cap became a fixed part of his image.","fact":"Their cover of George Michael's \"Faith\" unexpectedly turned into one of the band's biggest hits.","wiki_en":"Limp Bizkit","top_song":"Break Stuff"},{"name":"Korn","emoji":"🌽","meta":["nu metal","United States","1993–present"],"description":"The Californian band is considered one of the founders of nu metal: their heavy, down-tuned guitars and Jonathan Davis's confessional lyrics about childhood trauma set the language of the genre. Their debut album pointed the way for a whole wave of imitators.","fact":"The band's name is deliberately written with a backwards R, a nod to the look of a child's handwriting.","wiki_en":"Korn","top_song":"Freak on a Leash"},{"name":"Slipknot","emoji":"🎭","meta":["nu metal","United States","1995–present"],"description":"Nine members performing in unsettling masks and boiler suits with numbers instead of names, the band is known for an extremely heavy sound that mixes metal with percussion and industrial elements. Their stage look and live intensity became their calling card.","fact":"The band comes from Des Moines, Iowa, far from the main music centres of the United States.","wiki_en":"Slipknot (band)","top_song":"Duality"},{"name":"Foo Fighters","emoji":"🔥","meta":["rock","United States","1994–present"],"description":"Founded by former Nirvana drummer Dave Grohl, the band became one of the most successful rock acts at the meeting point of grunge and stadium rock. Ferocious live shows and Grohl's charisma made them one of the great concert bands of their generation.","fact":"The band's name comes from the term Second World War pilots used for unidentified flying objects.","wiki_en":"Foo Fighters","top_song":"Everlong"},{"name":"Nickelback","emoji":"🎸","meta":["rock","Canada","1995–present"],"description":"The Canadian rock band was one of the biggest radio successes of the 2000s thanks to hits such as \"How You Remind Me\", while also becoming the butt of countless internet jokes about their predictability. Either way, their albums kept selling in the millions.","fact":"Despite their status as a meme, they remain one of the best-selling Canadian rock bands in history.","wiki_en":"Nickelback","top_song":"How You Remind Me"},{"name":"Evanescence","emoji":"🖤","meta":["gothic rock","United States","1995–present"],"description":"The band led by singer Amy Lee joined gothic rock to symphonic and metal elements, which made the debut album \"Fallen\" one of the biggest hits of the early 2000s. The duet \"Bring Me to Life\", with its screamed male vocal, became their calling card.","fact":"Their debut single \"Bring Me to Life\" was first heard on the soundtrack of the film \"Daredevil\".","wiki_en":"Evanescence","top_song":"Bring Me to Life"},{"name":"Coldplay","emoji":"💛","meta":["alternative rock","United Kingdom","1996–present"],"description":"The British band led by Chris Martin became one of the most successful stadium rock acts of the twenty-first century with melodic hits such as \"Yellow\" and vast concert productions in which the whole audience lights up together.","fact":"At their shows the audience is given glowing Xylobands wristbands that change colour in sync as the concert unfolds.","wiki_en":"Coldplay","top_song":"Yellow"},{"name":"Muse","emoji":"🚀","meta":["alternative rock","United Kingdom","1994–present"],"description":"The British band is known for an epic, almost operatic sound that fuses rock with classical music and electronics, and for lyrics about conspiracies and dystopias. Frontman Matthew Bellamy's virtuoso guitar playing is one of the great draws of their live shows.","fact":"Their song \"Supermassive Black Hole\" appeared in the film \"Twilight\" and brought the band a whole new audience.","wiki_en":"Muse (band)","top_song":"Starlight"},{"name":"Gorillaz","emoji":"🦍","meta":["alternative","United Kingdom","1998–present"],"description":"A project by Damon Albarn of Blur and the artist Jamie Hewlett, presented to the public as a virtual band made up of cartoon characters. Their music blends alternative rock, hip-hop and electronics, with a long list of guest artists on every album.","fact":"The band has no visible performers: in place of musicians the public is given four animated characters, each with a name and a backstory.","wiki_en":"Gorillaz","top_song":"Feel Good Inc."},{"name":"The Prodigy","emoji":"🔥","meta":["big beat","United Kingdom","1990–present"],"description":"The British electronic project led by Liam Howlett fused rave and breakbeat with raw punk aggression, which made \"The Fat of the Land\" one of the most successful electronic albums of the 1990s. The videos for \"Firestarter\" and \"Smack My Bitch Up\" provoked outrage and television bans.","fact":"The video for \"Smack My Bitch Up\" was banned by many television channels because of its explicit content.","wiki_en":"The Prodigy","top_song":"Firestarter"},{"name":"Daft Punk","emoji":"🤖","meta":["electronic","France","1993–2021"],"description":"The French duo of Thomas Bangalter and Guy-Manuel de Homem-Christo performed in stylised robot helmets, keeping their faces hidden for their entire career. The album \"Discovery\", and later \"Random Access Memories\" with the hit \"Get Lucky\", made them among the most influential electronic musicians alive.","fact":"Fans learned of the duo's break-up in 2021 from a short video titled \"Epilogue\".","wiki_en":"Daft Punk","top_song":"Get Lucky"},{"name":"The Chemical Brothers","emoji":"🧪","meta":["big beat","United Kingdom","1991–present"],"description":"The British duo of Tom Rowlands and Ed Simons are pioneers of big beat, a style that welded heavy breakbeat rhythms to psychedelic and rock elements. Their sprawling visual shows have become an inseparable part of their live performances.","fact":"The duo started out as The Dust Brothers but changed the name after complaints from the American producers who already used it.","wiki_en":"The Chemical Brothers","top_song":"Galvanize"},{"name":"Moby","emoji":"🎧","meta":["electronic","United States","1989–present"],"description":"The American electronic musician and DJ made his name with the album \"Play\", on which samples of old blues and gospel recordings were laid over electronic beats. Almost every track on the record later turned up in advertising, films and television.","fact":"His stage name comes from the novel \"Moby-Dick\": according to family lore, the writer Herman Melville is a distant relative.","wiki_en":"Moby","top_song":"Porcelain"},{"name":"Fatboy Slim","emoji":"🕺","meta":["big beat","United Kingdom","1996–present"],"description":"The stage name of British DJ and producer Norman Cook, one of the leading figures of 1990s big beat. His hit \"Praise You\" came with a famous low-budget video featuring a shambolic amateur dance routine outside a cinema.","fact":"The video for \"Praise You\", with its deliberately inept dancing, was shot with a hidden camera in front of unsuspecting passers-by at a cinema.","wiki_en":"Fatboy Slim","top_song":"Praise You"},{"name":"Massive Attack","emoji":"🌫️","meta":["trip-hop","United Kingdom","1988–present"],"description":"The British band from Bristol were among the founders of trip-hop, a dark and atmospheric meeting of electronics, soul and hip-hop rhythms. Their album \"Mezzanine\" is considered one of the essential records of the genre.","fact":"The group did much to shape the so-called Bristol sound, which set off a whole wave of trip-hop musicians.","wiki_en":"Massive Attack","top_song":"Teardrop"},{"name":"Enigma","emoji":"🕯️","meta":["electronic","Germany","1990–present"],"description":"The project of German producer Michael Cretu joined Gregorian chant and ethnic motifs to a downtempo electronic backing. Their debut single \"Sadeness (Part I)\", built on samples of church singing, became an unexpected worldwide hit.","fact":"Using Gregorian chant in a dance track like \"Sadeness (Part I)\" caused controversy and complaints from religious organisations.","wiki_en":"Enigma (German band)","top_song":"Sadeness (Part I)"},{"name":"Scooter","emoji":"🛵","meta":["happy hardcore","Germany","1993–present"],"description":"The German electronic act led by H.P. Baxxter is known for driving happy hardcore and rave tracks built around shouted catchphrases, and for a touring schedule that has barely let up in decades. Their music became a fixture of German club culture.","fact":"The group has been releasing albums and touring hard for more than three decades, almost without a break.","wiki_en":"Scooter (band)","top_song":"How Much Is the Fish?"},{"name":"Backstreet Boys","emoji":"💙","meta":["pop","United States","1993–present"],"description":"One of the most successful boy bands in the history of pop music, known for layered vocal harmonies and ballads such as \"I Want It That Way\". Their rivalry with *NSYNC defined the pop scene of the late 1990s.","fact":"Their album \"Millennium\" was one of the fastest-selling albums in American history at the time of its release.","wiki_en":"Backstreet Boys","top_song":"I Want It That Way"},{"name":"*NSYNC","emoji":"💫","meta":["pop","United States","1995–2002"],"description":"The boy band that produced Justin Timberlake was the main rival to the Backstreet Boys on the pop scene of the late 1990s. Their tightly drilled dance routines and close harmonies made hits such as \"Bye Bye Bye\" a touchstone for a whole generation.","fact":"Their album \"No Strings Attached\" set a first-week sales record that stood for many years.","wiki_en":"NSYNC","top_song":"Bye Bye Bye"},{"name":"Spice Girls","emoji":"✨","meta":["pop","United Kingdom","1994–2000"],"description":"The British girl group became the face of the slogan \"girl power\" in the 1990s, with each member given her own vivid persona and nickname. Their debut single \"Wannabe\" turned them into global stars almost overnight.","fact":"Each of the five had a nickname of her own: Sporty, Ginger, Baby, Posh and Scary Spice.","wiki_en":"Spice Girls","top_song":"Wannabe"},{"name":"Britney Spears","emoji":"🎀","meta":["pop","United States","1998–present"],"description":"She became one of the defining pop icons of the turn of the millennium with her debut single \"...Baby One More Time\", and one of the most relentlessly discussed figures in mass culture. After years of fighting a restrictive conservatorship, she had it ended in 2021.","fact":"Her performance at the MTV Video Music Awards with a live python draped over her shoulders became one of the most talked-about sets in the show's history.","wiki_en":"Britney Spears","top_song":"...Baby One More Time"},{"name":"Christina Aguilera","emoji":"🎤","meta":["pop","United States","1999–present"],"description":"A singer with a formidable vocal range, she arrived at the same moment as Britney Spears in the late 1990s and quickly established herself as one of the most technically gifted voices of her generation. The album \"Stripped\" showed a more mature and personal side.","fact":"As a teenager she appeared on the children's television show \"The Mickey Mouse Club\" alongside other future pop stars of her generation.","wiki_en":"Christina Aguilera","top_song":"Beautiful"},{"name":"Justin Timberlake","emoji":"🕺","meta":["pop","United States","2002–present"],"description":"The former *NSYNC member built a successful solo career joining pop to rhythm and blues, and also made his name as a film actor. The album \"FutureSex/LoveSounds\" confirmed him as one of the biggest pop stars of the 2000s.","fact":"Besides music, he has appeared in a number of notable films, among them \"The Social Network\".","wiki_en":"Justin Timberlake","top_song":"Cry Me a River"},{"name":"Destiny's Child","emoji":"💃","meta":["rhythm and blues","United States","1990–2006"],"description":"The female rhythm and blues trio that produced Beyoncé was one of the most successful girl groups at the turn of the millennium. Their hit \"Say My Name\" and the anthem of independence \"Survivor\" became touchstone songs of the era.","fact":"Their song \"Independent Women Part I\" became the theme of the film \"Charlie's Angels\" and topped the American chart.","wiki_en":"Destiny's Child","top_song":"Say My Name"},{"name":"Beyoncé","emoji":"🐝","meta":["rhythm and blues","United States","1997–present"],"description":"The former lead singer of Destiny's Child became one of the great stars of modern pop and rhythm and blues, known for a formidable voice, spectacular live shows and albums such as \"Lemonade\" that deal with female strength and Black American identity.","fact":"She is among the artists with the most Grammy Awards in the history of the ceremony.","wiki_en":"Beyoncé","top_song":"Crazy in Love"},{"name":"Jennifer Lopez","emoji":"💚","meta":["pop","United States","1999–present"],"description":"A singer, dancer and actress, she was one of very few Latina stars to succeed in music and film at the same time around the turn of the 2000s. Her green dress at the Grammy Awards became one of the most discussed outfits in red carpet history.","fact":"The emerald Versace dress she wore to the Grammys in 2000 gave rise to the story behind the creation of Google's image search.","wiki_en":"Jennifer Lopez","top_song":"On the Floor"},{"name":"Ricky Martin","emoji":"💃","meta":["pop","Puerto Rico","1984–present"],"description":"The Puerto Rican singer, once a member of the group Menudo, became one of the main conduits carrying Latin American music into the American mainstream with the hit \"Livin' la Vida Loca\". His high-energy shows bind pop to Latin rhythms.","fact":"\"Livin' la Vida Loca\" is considered one of the songs that set off the Latin explosion in late-1990s pop music.","wiki_en":"Ricky Martin","top_song":"Livin' la Vida Loca"},{"name":"Enrique Iglesias","emoji":"🎤","meta":["pop","Spain","1995–present"],"description":"The Spanish singer, son of Julio Iglesias, built a successful career of his own straddling English- and Spanish-language pop. His duet \"Bailando\" became one of the most successful Latin hits of the 2010s.","fact":"Early on he sent out his demo tapes under a false name so that labels would not know whose son he was.","wiki_en":"Enrique Iglesias","top_song":"Bailando"},{"name":"Kylie Minogue","emoji":"✨","meta":["pop","Australia","1987–present"],"description":"The Australian singer and actress started out in the soap opera \"Neighbours\" and went on to build one of the longest careers in dance pop. The hit \"Can't Get You Out of My Head\" became an emblem of the disco-pop revival of the 2000s.","fact":"One of her first big hits was a cover of the old song \"The Loco-Motion\".","wiki_en":"Kylie Minogue","top_song":"Can't Get You Out of My Head"},{"name":"Robbie Williams","emoji":"🎤","meta":["pop","United Kingdom","1995–present"],"description":"The former Take That member built one of the most successful solo careers in British pop, on the strength of magnetic live shows and hits such as \"Angels\". His wry, deliberately outrageous stage manner set him apart from the usual pop performer.","fact":"His ballad \"Angels\" is regularly named one of Britain's favourite songs for both funerals and weddings.","wiki_en":"Robbie Williams","top_song":"Angels"},{"name":"Shania Twain","emoji":"🤠","meta":["country pop","Canada","1993–present"],"description":"The Canadian singer is one of the best-selling artists in the history of country music, and on the album \"Come On Over\" she joined the genre to a pop-rock sound. Her hit \"Man! I Feel Like a Woman!\" became an anthem of female confidence in country.","fact":"\"Come On Over\" remains one of the best-selling studio albums ever recorded by a woman.","wiki_en":"Shania Twain","top_song":"Man! I Feel Like a Woman!"},{"name":"Alanis Morissette","emoji":"🎤","meta":["alternative rock","Canada","1991–present"],"description":"The Canadian singer's album \"Jagged Little Pill\", with its confessional and emotionally raw lyrics, became one of the defining alternative rock records of the mid-1990s. The single \"Ironic\" set off a long argument about whether the situations it describes are ironic at all.","fact":"She recorded \"Jagged Little Pill\" very young, and it became one of the best-selling albums of the 1990s.","wiki_en":"Alanis Morissette","top_song":"Ironic"},{"name":"No Doubt","emoji":"🎸","meta":["ska punk","United States","1986–present"],"description":"The Californian band fronted by Gwen Stefani started out in ska punk and then moved to a more pop-leaning alternative sound on the album \"Tragic Kingdom\". Their hit \"Don't Speak\", about a painful break-up, became one of the great songs of the 1990s.","fact":"\"Don't Speak\" was written about Gwen Stefani's real break-up with the band's bass player Tony Kanal.","wiki_en":"No Doubt","top_song":"Don't Speak"},{"name":"Gwen Stefani","emoji":"💄","meta":["pop rock","United States","2004–present"],"description":"The lead singer of No Doubt launched a successful solo pop career built on a bold visual style and the hit \"Hollaback Girl\". Her solo work brings together pop, electronics and elements of hip-hop.","fact":"\"Hollaback Girl\" was one of the first digital singles to sell more than a million copies in the United States.","wiki_en":"Gwen Stefani","top_song":"Hollaback Girl"},{"name":"Avril Lavigne","emoji":"🖤","meta":["pop punk","Canada","2002–present"],"description":"The Canadian singer became one of the biggest pop-punk stars of the early 2000s with her debut hit \"Complicated\" and her rebel look, a necktie worn over a T-shirt. Her music married punk trappings to melodies anyone could sing.","fact":"Her debut album \"Let Go\" came out when she was only seventeen and sold many millions of copies.","wiki_en":"Avril Lavigne","top_song":"Complicated"},{"name":"P!nk","emoji":"💗","meta":["pop rock","United States","2000–present"],"description":"She joined pop to rock energy and acrobatic, circus-like stunts in her live shows, which set her apart from the smoother pop stars of the early 2000s. The hit \"So What\" fixed her image as the independent troublemaker of the pop scene.","fact":"Her real name is Alecia Beth Moore, and the stage name stuck to her as a teenager.","wiki_en":"Pink (singer)","top_song":"So What"},{"name":"Nelly Furtado","emoji":"🎤","meta":["pop","Canada","2000–present"],"description":"The Canadian singer debuted with the folk-pop sound of \"Whoa, Nelly!\" and then switched to something far more danceable and rhythm and blues driven on \"Loose\", with the hit \"Promiscuous\". That change of direction showed off the full range of her voice.","fact":"She recorded \"Promiscuous\" as a duet with the producer Timbaland, which turned out to be the pivot of her career.","wiki_en":"Nelly Furtado","top_song":"Promiscuous"},{"name":"Alicia Keys","emoji":"🎹","meta":["rhythm and blues","United States","2001–present"],"description":"A singer and pianist with a classical training, she debuted with the album \"Songs in A Minor\" and announced herself at once as one of the leading rhythm and blues artists of a new generation. The hit \"No One\" confirmed her standing as both a great voice and a songwriter.","fact":"Her debut album \"Songs in A Minor\" won her several Grammy Awards at once, including Best New Artist.","wiki_en":"Alicia Keys","top_song":"No One"},{"name":"USHER","emoji":"🕺","meta":["rhythm and blues","United States","1994–present"],"description":"A singer and dancer and one of the central figures in rhythm and blues around the turn of the 2000s, known for razor-sharp choreography and for \"Confessions\", an album that sold many millions. The hit \"Yeah!\", featuring Lil Jon and Ludacris, became one of the great club records of the era.","fact":"His album \"Confessions\" is one of the best-selling rhythm and blues albums of the 2000s.","wiki_en":"Usher (musician)","top_song":"Yeah!"},{"name":"TLC","emoji":"💕","meta":["rhythm and blues","United States","1990–present"],"description":"The trio was one of the most successful rhythm and blues groups of the 1990s, pairing rich harmonies with lyrics about self-respect and independence in hits such as \"Waterfalls\". Their album \"CrazySexyCool\" is one of the best-selling albums ever by a female group.","fact":"Lisa Lopes, the member known as Left Eye, was killed in a car crash in 2002.","wiki_en":"TLC (group)","top_song":"Waterfalls"},{"name":"2Pac","emoji":"🌹","meta":["hip-hop","United States","1991–1996"],"description":"One of the most influential rappers in the history of hip-hop, known for combining hard street storytelling with socially and politically literate lyrics. His murder in 1996, officially unsolved for decades, became one of the great tragedies of hip-hop culture.","fact":"More albums of his recordings have been released since his death than he managed to put out while he was alive.","wiki_en":"Tupac Shakur","top_song":"California Love"},{"name":"The Notorious B.I.G.","emoji":"👑","meta":["hip-hop","United States","1994–1997"],"description":"The Brooklyn rapper was one of the most influential artists of the East Coast, known for a masterful flow and vivid storytelling about street life. His murder in 1997, only six months after 2Pac's, fuelled the talk of a feud between East and West Coast hip-hop.","fact":"His second album \"Life After Death\" was released just a few weeks after his death.","wiki_en":"The Notorious B.I.G.","top_song":"Juicy"},{"name":"Dr. Dre","emoji":"🎧","meta":["hip-hop","United States","1984–present"],"description":"A rapper and producer, one of the creators of G-funk and one of the most influential producers hip-hop has had, he introduced the world to Snoop Dogg and Eminem. His album \"The Chronic\" set the sound of the entire West Coast for a decade.","fact":"Beyond music, he was one of the founders of the popular Beats by Dre headphone line.","wiki_en":"Dr. Dre","top_song":"Still D.R.E."},{"name":"Snoop Dogg","emoji":"🐶","meta":["hip-hop","United States","1992–present"],"description":"A rapper with an unmistakable drawled flow, he became famous through his work with Dr. Dre on \"The Chronic\" and then his own debut album \"Doggystyle\". His unhurried manner and instantly recognisable voice made him one of hip-hop's best-known faces far beyond the genre.","fact":"His debut album \"Doggystyle\" entered the American album chart straight at number one.","wiki_en":"Snoop Dogg","top_song":"Drop It Like It's Hot"},{"name":"Eminem","emoji":"🎤","meta":["hip-hop","United States","1996–present"],"description":"One of the most successful rappers in history, thanks to a headlong, technically dazzling flow and autobiographical lyrics about a brutal childhood and his own private wreckage. \"The Marshall Mathers LP\" became one of the best-selling hip-hop albums, and the film \"8 Mile\" secured his standing beyond music.","fact":"He is one of very few rappers to win an Academy Award, for \"Lose Yourself\" from the film \"8 Mile\".","wiki_en":"Eminem","top_song":"Lose Yourself"},{"name":"50 Cent","emoji":"💰","meta":["hip-hop","United States","1996–present"],"description":"He became a star after surviving a shooting that left him with nine bullet wounds, and his debut album \"Get Rich or Die Tryin'\", produced by Dr. Dre and Eminem, was one of the most successful hip-hop debuts of the early 2000s. Beyond music he built a real business, including a stake in Vitaminwater.","fact":"He played the lead in a semi-autobiographical film that took its title from his debut album.","wiki_en":"50 Cent","top_song":"In da Club"},{"name":"JAY-Z","emoji":"💎","meta":["hip-hop","United States","since 1986"],"description":"One of the most influential rappers and producers in the industry, a Brooklyn native who became a billionaire as both a musician and a businessman. Alongside his own records he ran the label Roc-A-Fella Records, and he has been married to Beyoncé for many years.","fact":"Jay-Z started out selling his first records straight out of the boot of his car.","wiki_en":"Jay-Z","top_song":"Empire State of Mind"},{"name":"Kanye West","emoji":"🕶️","meta":["hip-hop","United States","since 1996"],"description":"A rapper and producer who began making beats for Jay-Z and others and went on to become one of the most visible and most contested figures in hip-hop. He is known for his experimental albums and for the fashion brand Yeezy.","fact":"He released his debut album \"The College Dropout\" after a serious car crash that nearly cost him his life.","wiki_en":"Kanye West","top_song":"Stronger"},{"name":"Nas","emoji":"📖","meta":["hip-hop","United States","since 1994"],"description":"One of the most respected rappers in New York, he made his name with the debut album \"Illmatic\", widely held up as the benchmark for lyrical hip-hop. He is known for detailed, cinematic writing about life in the Queensbridge projects.","fact":"Nas recorded \"Illmatic\" very young, and the record still turns up regularly on lists of the greatest hip-hop albums ever made.","wiki_en":"Nas","top_song":"If I Ruled the World (Imagine That)"},{"name":"Outkast","emoji":"👽","meta":["hip-hop","United States","1992–2007"],"description":"The Atlanta duo changed Southern hip-hop with an experimental sound that mixed rap, funk and pop in equal measure. Their single \"Hey Ya!\" became one of the most recognisable hits of the 2000s.","fact":"\"Speakerboxxx/The Love Below\" came out as a double album on which each member of the duo recorded his own half of the record.","wiki_en":"Outkast","top_song":"Hey Ya!"},{"name":"Wu-Tang Clan","emoji":"⚔️","meta":["hip-hop","United States","since 1992"],"description":"The New York collective brought nine rappers together and built a signature murky sound out of samples from kung fu films. Their influence on New York rap in the 1990s was enormous.","fact":"The group's name is a nod to martial arts and to the old Hong Kong Shaolin films the members grew up obsessed with.","wiki_en":"Wu-Tang Clan","top_song":"C.R.E.A.M."},{"name":"Beastie Boys","emoji":"🎧","meta":["hip-hop","United States","1981–2012"],"description":"The New York trio started out as a punk band and became one of the first white acts to succeed in hip-hop. They mixed rap, rock and punk energy while staying wilfully funny and experimental.","fact":"The video for \"Sabotage\" was made as a parody of 1970s detective series, with the band in moustaches and wigs.","wiki_en":"Beastie Boys","top_song":"Sabotage"},{"name":"Run-DMC","emoji":"👟","meta":["hip-hop","United States","1981–2002"],"description":"Hip-hop pioneers from Queens, they brought rock guitars into the genre along with a street style of trainers and gold chains. Their collaboration with Aerosmith helped carry hip-hop onto mainstream radio.","fact":"The brand liked the song \"My Adidas\" so much that Adidas signed the group to one of the first sponsorship deals ever given to musicians.","wiki_en":"Run-DMC","top_song":"Walk This Way"},{"name":"Ice Cube","emoji":"🔥","meta":["hip-hop","United States","since 1986"],"description":"A founding member of N.W.A and one of the pioneers of gangsta rap, he later moved successfully into a solo career and into film. His lyrics spoke about life in Compton harshly and without decoration.","fact":"After leaving N.W.A, Ice Cube quickly released a solo debut album and at once secured a reputation as one of the sharpest rappers of the era.","wiki_en":"Ice Cube","top_song":"It Was a Good Day"},{"name":"Missy Elliott","emoji":"🛸","meta":["hip-hop","United States","since 1997"],"description":"A rapper and producer known for futuristic videos and for the inventive sound she built together with the producer Timbaland. She is one of the very few women to become a cult figure in hip-hop production.","fact":"In the video for \"The Rain (Supa Dupa Fly)\" Missy Elliott appeared in an inflated black vinyl suit, one of the most recognisable images in hip-hop video.","wiki_en":"Missy Elliott","top_song":"Get Ur Freak On"},{"name":"Black Eyed Peas","emoji":"🎉","meta":["hip-hop","United States","since 1995"],"description":"The American group went from an underground hip-hop collective to one of the biggest pop acts of the 2000s after singer Fergie joined. Their club hits were played on dance floors all over the world.","fact":"\"I Gotta Feeling\" spent a long time as one of the most downloaded digital tracks in history.","wiki_en":"Black Eyed Peas","top_song":"I Gotta Feeling"},{"name":"Lil Wayne","emoji":"🔥","meta":["hip-hop","United States","since 1995"],"description":"One of the most prolific rappers of his generation, he began as a teenager in the group Hot Boys and became the central figure at Cash Money Records. He is famous for an oddly rasping voice and a staggering number of mixtapes.","fact":"He signed to Cash Money while still at school and was the label's youngest artist.","wiki_en":"Lil Wayne","top_song":"Lollipop"},{"name":"Akon","emoji":"🎶","meta":["R&B","United States","since 2004"],"description":"A singer and producer of Senegalese descent, he became a major figure in the R&B and hip-hop of the 2000s with a distinctive autotuned vocal. He is also known as the producer who discovered a number of young artists, Lady Gaga among them.","fact":"He spent part of his childhood in Senegal, and his father is a well-known Senegalese jazz percussionist.","wiki_en":"Akon","top_song":"Smack That"},{"name":"Sean Paul","emoji":"🌴","meta":["dancehall","Jamaica","since 1996"],"description":"The Jamaican singer did more than almost anyone to put dancehall on the world charts in the 2000s. He combines patois with high-energy rhythms and remains one of the most recognisable voices in Caribbean music.","fact":"Before he took up music seriously, Sean Paul played water polo for the Jamaican national team.","wiki_en":"Sean Paul","top_song":"Temperature"},{"name":"Timbaland","emoji":"🎛️","meta":["hip-hop","United States","since 1996"],"description":"A producer and rapper who defined the sound of R&B and hip-hop around the turn of the 2000s with unusual beats and sound effects nobody else was using. He has worked with Missy Elliott, Justin Timberlake and a long list of other stars.","fact":"His beats for Aaliyah and Missy Elliott, with their broken, stumbling rhythms, noticeably changed the sound of late-1990s R&B.","wiki_en":"Timbaland","top_song":"The Way I Are"},{"name":"Pharrell Williams","emoji":"🎩","meta":["hip-hop","United States","since 1992"],"description":"A singer, producer and one half of The Neptunes, he shaped the sound of pop and hip-hop in the 2000s. His solo hit \"Happy\" became one of the most recognisable feel-good songs of the decade.","fact":"The video for \"Happy\" was released as the first twenty-four-hour music video, with the dancers changing throughout a whole day.","wiki_en":"Pharrell Williams","top_song":"Happy"},{"name":"The White Stripes","emoji":"🎸","meta":["rock","United States","1997–2011"],"description":"The Detroit duo of Jack and Meg White pretended to be brother and sister and played garage rock that was deliberately crude and yet enormous. They became one of the faces of the rock revival of the early 2000s.","fact":"The bass riff in \"Seven Nation Army\" is actually a guitar played through an octave pedal: the band had no bass player.","wiki_en":"The White Stripes","top_song":"Seven Nation Army"},{"name":"The Killers","emoji":"🕺","meta":["rock","United States","since 2001"],"description":"The rock band from Las Vegas broke into the charts in the early 2000s with a bright sound sitting between indie rock and synth-pop. Their song \"Mr. Brightside\" remains one of the longest-running hits in British chart history.","fact":"\"Mr. Brightside\" spent a record number of weeks on the British singles chart, returning to it again and again years after its release.","wiki_en":"The Killers","top_song":"Mr. Brightside"},{"name":"Arctic Monkeys","emoji":"🐒","meta":["indie rock","United Kingdom","since 2002"],"description":"The British indie rock band from Sheffield became famous before their debut album was even out, through demo recordings passed around by fans online. Over the years their sound moved towards something slower and more atmospheric.","fact":"Their debut \"Whatever People Say I Am, That's What I'm Not\" was the fastest-selling debut album in British chart history at the time.","wiki_en":"Arctic Monkeys","top_song":"Do I Wanna Know?"},{"name":"The Strokes","emoji":"🗽","meta":["indie rock","United States","since 1998"],"description":"The New York band's debut album \"Is This It\" is credited with bringing garage rock and indie back into fashion in the early 2000s. They are known for a deliberately dusty guitar sound and their singer's offhand charisma.","fact":"The cover of \"Is This It\" was swapped out for the American edition because the photograph was considered too explicit for that market.","wiki_en":"The Strokes","top_song":"Last Nite"},{"name":"Franz Ferdinand","emoji":"🕺","meta":["indie rock","United Kingdom","since 2002"],"description":"The Scottish band became one of the emblems of the mid-2000s post-punk revival with danceable guitar rhythms and a sharp sense of style. They are named after Archduke Franz Ferdinand, with no deeper connection to the historical events.","fact":"The abrupt change of tempo halfway through \"Take Me Out\" became one of the band's most recognisable trademarks.","wiki_en":"Franz Ferdinand (band)","top_song":"Take Me Out"},{"name":"Kings of Leon","emoji":"🦁","meta":["rock","United States","since 1999"],"description":"The American rock band from Tennessee is made up of three brothers and their cousin, and moved gradually from Southern rock to a more mainstream sound. The album \"Only by the Night\" brought them worldwide fame.","fact":"The name refers to Leon, which was the name of both the members' father and their grandfather.","wiki_en":"Kings of Leon","top_song":"Sex on Fire"},{"name":"Maroon 5","emoji":"🍫","meta":["pop rock","United States","since 1994"],"description":"The American band started out with a funk-rock sound and turned by degrees into one of the most successful pop acts of the present day, fronted by singer Adam Levine. Their songs regularly top charts around the world.","fact":"The band's first album, under the old name Kara's Flowers, went almost unnoticed: success only came after they became Maroon 5.","wiki_en":"Maroon 5","top_song":"Sugar"},{"name":"OneRepublic","emoji":"🎹","meta":["pop rock","United States","since 2002"],"description":"The American pop-rock band is led by Ryan Tedder, who is also known as an in-demand songwriter for other stars. Their melodic, stadium-sized hits are chart fixtures, built to be sung back by a crowd of thousands.","fact":"Alongside his work in the band, frontman Ryan Tedder has written songs for Adele, Beyoncé and many other artists.","wiki_en":"OneRepublic","top_song":"Counting Stars"},{"name":"Thirty Seconds to Mars","emoji":"🚀","meta":["alternative rock","United States","since 1998"],"description":"The American rock band was founded by the actor Jared Leto together with his brother Shannon. They combine a vast stadium sound with electronic textures and carefully staged visual concepts.","fact":"Frontman Jared Leto has kept up a successful film career alongside the music, including a role that won him an Academy Award.","wiki_en":"Thirty Seconds to Mars","top_song":"The Kill"},{"name":"My Chemical Romance","emoji":"🖤","meta":["emo rock","United States","since 2001"],"description":"The American band became one of the emblems of the emo wave of the 2000s with a theatrical look and bleak concept albums. Their single \"Welcome to the Black Parade\" became an anthem for a whole generation.","fact":"\"The Black Parade\" was conceived as a concept story about a cancer patient looking back over his life as he dies.","wiki_en":"My Chemical Romance","top_song":"Welcome to the Black Parade"},{"name":"Fall Out Boy","emoji":"🎸","meta":["pop punk","United States","since 2001"],"description":"The American pop-punk band from Chicago is known for witty, often absurd song titles and a high-octane sound that welds punk to pop. They became one of the leading acts of the mid-2000s emo and pop-punk scene.","fact":"Many of the band's song titles have nothing to do with the lyrics and were invented separately, as jokes in their own right.","wiki_en":"Fall Out Boy","top_song":"Sugar, We're Goin Down"},{"name":"Paramore","emoji":"🔥","meta":["pop punk","United States","since 2004"],"description":"The American rock band from Tennessee became one of the defining voices of the 2000s pop-punk scene, largely thanks to its ferocious frontwoman Hayley Williams. Over time their sound grew steadily more varied.","fact":"Hayley Williams joined the future members of Paramore as a teenager, and the band came together largely around her voice.","wiki_en":"Paramore","top_song":"Misery Business"},{"name":"Panic! At the Disco","emoji":"🎩","meta":["pop punk","United States","since 2004"],"description":"The American project began as a pop-punk band with baroque arrangements and turned over the years into the solo vehicle of singer Brendon Urie. They are known for a theatrical stage style and absurdly long song titles.","fact":"The title of the debut album \"A Fever You Can't Sweat Out\" and many of the band's song titles are quotations from other works and films.","wiki_en":"Panic! at the Disco","top_song":"I Write Sins Not Tragedies"},{"name":"Placebo","emoji":"🖤","meta":["alternative rock","United Kingdom","since 1994"],"description":"The British alternative rock band led by Brian Molko is known for an androgynous image and a dark, electrically charged sound. Their songs often circle around obsession, addiction and identity.","fact":"The song \"Every You Every Me\" was written specially for the soundtrack of the film \"Cruel Intentions\".","wiki_en":"Placebo (band)","top_song":"Every You Every Me"},{"name":"Tokio Hotel","emoji":"⚡","meta":["pop rock","Germany","since 2001"],"description":"The German pop-rock band found success while still in their teens and became one of the most popular German-language acts in Europe in the 2000s. They later began releasing songs in English, which widened their audience well beyond Germany.","fact":"Singer Bill Kaulitz and guitarist Tom Kaulitz are twin brothers who have been playing together since childhood.","wiki_en":"Tokio Hotel","top_song":"Durch den Monsun"},{"name":"Adele","emoji":"🎤","meta":["pop","United Kingdom","since 2006"],"description":"The British singer has one of the great soul voices of her generation, and her albums, each named after her age when she recorded it, are among the best-selling in music history. She writes mostly about her own heartbreak and what is left afterwards.","fact":"\"Hello\" was the first song to pass a million digital sales in the United States in a single week.","wiki_en":"Adele","top_song":"Hello"},{"name":"Amy Winehouse","emoji":"🎙️","meta":["soul","United Kingdom","2002–2011"],"description":"The British singer's unmistakable low voice brought the retro soul and jazz of the mid-twentieth century back into fashion. The album \"Back to Black\" made her a worldwide name, while her life and career were shadowed by her struggle with addiction.","fact":"She died at the age of twenty-seven, joining the musicians who died at that same age, known as the 27 Club.","wiki_en":"Amy Winehouse","top_song":"Rehab"},{"name":"Lady Gaga","emoji":"🎭","meta":["pop","United States","since 2008"],"description":"The American pop singer is known for outrageous stage costumes and a formidable voice. She started out as a club pop star and later proved herself in film as well, and she keeps moving between styles, from electropop to jazz standards.","fact":"At the MTV Video Music Awards in 2010 Lady Gaga walked on stage in a dress made entirely of raw meat.","wiki_en":"Lady Gaga","top_song":"Bad Romance"},{"name":"Rihanna","emoji":"💎","meta":["R&B","Barbados","since 2005"],"description":"The singer from Barbados became one of the great pop and R&B stars of the late 2000s and the 2010s, and later built an equally successful beauty empire in Fenty. Her single \"Umbrella\", featuring Jay-Z, was one of the biggest hits of 2007.","fact":"After a long pause from music, Rihanna focused on Fenty Beauty, famous for an unprecedentedly wide range of foundation shades.","wiki_en":"Rihanna","top_song":"Umbrella"},{"name":"Katy Perry","emoji":"🎆","meta":["pop","United States","since 2008"],"description":"The American pop singer started out in Christian music and then became one of the biggest names in the bright, tongue-in-cheek pop mainstream of the late 2000s and the 2010s. She is known for vivid stage costumes and elaborately conceived videos.","fact":"Before becoming a pop star, Katy Perry released a Christian album under her real name, Katy Hudson.","wiki_en":"Katy Perry","top_song":"Dark Horse"},{"name":"Taylor Swift","emoji":"✒️","meta":["pop","United States","since 2006"],"description":"The American singer and songwriter began her career in country and grew step by step into one of the most influential pop stars in the world. She is known for autobiographical lyrics and, more recently, for re-recording her own early albums to gain control of the rights.","fact":"Her Eras Tour is described as the first concert tour in history to take more than a billion dollars.","wiki_en":"Taylor Swift","top_song":"Anti-Hero"},{"name":"Bruno Mars","emoji":"🌟","meta":["funk","United States","since 2004"],"description":"The American singer and multi-instrumentalist blends funk, soul and pop with the reggae influences of a Hawaiian childhood. He is known for explosive live shows and a retro aesthetic borrowed from classic 1980s funk.","fact":"Bruno Mars grew up in Honolulu in a family of musicians and performed on stage from early childhood, playing Elvis Presley.","wiki_en":"Bruno Mars","top_song":"24K Magic"},{"name":"Ed Sheeran","emoji":"🎸","meta":["pop","United Kingdom","since 2011"],"description":"The British singer and songwriter conquered the charts with nothing more than an acoustic guitar, a loop pedal and melodies that lodge instantly in the head. He names his albums after mathematical symbols, from the plus sign to the equals sign.","fact":"\"Shape of You\" spent a long time as one of the most-streamed songs in the history of Spotify.","wiki_en":"Ed Sheeran","top_song":"Shape of You"},{"name":"Justin Bieber","emoji":"🍁","meta":["pop","Canada","since 2008"],"description":"The Canadian singer became a star as a teenager through clips posted on YouTube, and travelled from teen idol to one of the most successful performers working today. His music moved towards R&B and dance rhythms as he grew up.","fact":"His home videos on YouTube were spotted by the manager Scooter Braun, who brought the teenager into the music industry.","wiki_en":"Justin Bieber","top_song":"Sorry"},{"name":"The Weeknd","emoji":"🌙","meta":["R&B","Canada","since 2010"],"description":"The Canadian singer arrived with a dark, atmospheric take on R&B and later moved towards the retro synthwave of the 1980s. The single \"Blinding Lights\" became one of the most successful songs in chart history.","fact":"\"Blinding Lights\" spent a record number of weeks on the American Billboard Hot 100.","wiki_en":"The Weeknd","top_song":"Blinding Lights"},{"name":"Drake","emoji":"🦉","meta":["hip-hop","Canada","since 2006"],"description":"The Canadian rapper and singer started out as an actor on the series \"Degrassi\" and became one of the most commercially successful artists hip-hop has produced. He blends rap with melodic R&B singing and keeps breaking streaming records.","fact":"Before his music career, Drake spent several years acting in the Canadian teen series \"Degrassi: The Next Generation\".","wiki_en":"Drake (musician)","top_song":"One Dance"},{"name":"Kendrick Lamar","emoji":"🎤","meta":["hip-hop","United States","since 2003"],"description":"The rapper from Compton is regularly named by critics as one of the essential voices in modern hip-hop, for lyrics that are dense and politically charged at once. His album \"To Pimp a Butterfly\" became one of the most discussed records of the 2010s.","fact":"Kendrick Lamar was the first artist outside jazz or classical music to win the Pulitzer Prize.","wiki_en":"Kendrick Lamar","top_song":"HUMBLE."},{"name":"Travis Scott","emoji":"🚀","meta":["hip-hop","United States","since 2012"],"description":"The Houston rapper is known for a psychedelic, cavernous sound and for concerts staged like fairground rides. His album \"Astroworld\" is named after the closed-down Houston amusement park of his childhood.","fact":"Travis Scott's collaboration with McDonald's on a burger under his own name became one of the most talked-about marketing campaigns ever built around a musician.","wiki_en":"Travis Scott","top_song":"SICKO MODE"},{"name":"Post Malone","emoji":"🖤","meta":["hip-hop","United States","since 2015"],"description":"The American rapper and singer erases the borders between hip-hop, rock and pop, and is instantly recognisable by the tattoos across his face. His songs set melancholy melodies against trap beats.","fact":"\"Sunflower\", recorded for the animated film \"Spider-Man: Into the Spider-Verse\", became one of the most-streamed tracks in the history of Spotify.","wiki_en":"Post Malone","top_song":"Sunflower"},{"name":"Nicki Minaj","emoji":"💗","meta":["hip-hop","United States","since 2004"],"description":"She became one of the most successful women in the history of hip-hop through vivid alter egos, a headlong flow and unforgettable visuals. Her career began under the wing of Lil Wayne and the Young Money label.","fact":"Many critics call her guest verse on Kanye West's \"Monster\" one of the best rap verses of the decade.","wiki_en":"Nicki Minaj","top_song":"Super Bass"},{"name":"Cardi B","emoji":"💅","meta":["hip-hop","United States","since 2016"],"description":"The rapper from the Bronx became known through social media and reality television, then made a headlong breakthrough in hip-hop with her debut single \"Bodak Yellow\". She is blunt and fearless in her lyrics and in everything she says in public.","fact":"\"Bodak Yellow\" made Cardi B the first solo female rapper in a very long time to top the Billboard Hot 100.","wiki_en":"Cardi B","top_song":"Bodak Yellow"},{"name":"Ariana Grande","emoji":"🎀","meta":["pop","United States","since 2013"],"description":"The American singer with a vast vocal range began as an actress on Nickelodeon and became one of the biggest pop stars of the 2010s. She combines pop with R&B influences and is instantly recognisable by her signature high ponytail.","fact":"Ariana Grande's voice spans several octaves, and she often shows it off by singing passages in the whistle register.","wiki_en":"Ariana Grande","top_song":"thank u, next"},{"name":"Billie Eilish","emoji":"🖤","meta":["pop","United States","since 2015"],"description":"The American singer recorded most of her early songs at home with her brother Finneas and built a recognisable style out of a hushed, breathy voice laid over dark minimal beats. She is one of the youngest artists ever to win the Grammy for Album of the Year.","fact":"She became the youngest performer ever to sing the title song of a James Bond film.","wiki_en":"Billie Eilish","top_song":"bad guy"},{"name":"Dua Lipa","emoji":"💃","meta":["pop","United Kingdom","since 2015"],"description":"The British singer of Kosovo Albanian descent became one of the faces of the retro disco revival in late-2010s pop. She is known for a deep, smoky voice and dance hits steeped in disco and funk.","fact":"As a teenager she moved from London to Kosovo with her family, then returned alone soon afterwards to pursue music.","wiki_en":"Dua Lipa","top_song":"Levitating"},{"name":"Harry Styles","emoji":"🎀","meta":["pop rock","United Kingdom","since 2010"],"description":"The British singer began his career in One Direction and, after the band went on hiatus, built a successful solo career with a far more rock- and retro-leaning sound. He is also a notable actor and a style icon with eccentric stage outfits.","fact":"In the year it was released, \"As It Was\" became one of the most-streamed tracks in a single day in Spotify's history.","wiki_en":"Harry Styles","top_song":"As It Was"},{"name":"One Direction","emoji":"🧡","meta":["pop","United Kingdom","2010–2016"],"description":"The British-Irish boy band was assembled on \"The X Factor\" from five contestants who had each failed to get through on their own. They became one of the most commercially successful groups of the 2010s before taking a break to pursue solo careers.","fact":"Zayn Malik left the group in 2015, and the remaining four recorded the final album as a quartet.","wiki_en":"One Direction","top_song":"What Makes You Beautiful"},{"name":"Shawn Mendes","emoji":"🎸","meta":["pop","Canada","since 2013"],"description":"The Canadian singer started out posting short cover clips on the app Vine and became one of the biggest young pop stars of the second half of the 2010s. He usually writes his own songs and accompanies himself on guitar.","fact":"He is one of the youngest artists ever to have an album go straight to number one on the American chart.","wiki_en":"Shawn Mendes","top_song":"Stitches"},{"name":"Selena Gomez","emoji":"🌙","meta":["pop","United States","since 2008"],"description":"The American actress and singer began her career on the Disney Channel and then built a parallel career in music, moving between pop and Latin sounds. She is also known as a producer and as the founder of the beauty brand Rare Beauty.","fact":"Selena Gomez started out on the children's show \"Barney & Friends\", which featured other future stars over the years.","wiki_en":"Selena Gomez","top_song":"Lose You to Love Me"},{"name":"Miley Cyrus","emoji":"🔨","meta":["pop rock","United States","since 2006"],"description":"The American singer and actress became famous as a child through the role of Hannah Montana, then deliberately broke with her Disney image for something bolder and grown-up. Over the years her sound has travelled from pop country to rock and disco.","fact":"Her song \"Flowers\" became one of the most successful singles of 2023 and won her a Grammy.","wiki_en":"Miley Cyrus","top_song":"Wrecking Ball"},{"name":"Lana Del Rey","emoji":"🌹","meta":["alternative pop","United States","since 2010"],"description":"The American singer worked out an unmistakable melancholy persona sitting between old-school glamour and modern pop aesthetics. Her music combines orchestral arrangements, trip-hop influences and nostalgic lyrics about America.","fact":"She invented the name Lana Del Rey because it sounded like the stage names of old Hollywood.","wiki_en":"Lana Del Rey","top_song":"Summertime Sadness"},{"name":"Sia","emoji":"🎀","meta":["pop","Australia","since 1997"],"description":"The Australian singer and songwriter was writing hits for other stars long before her own mass success, then became famous for hiding her face on stage behind an enormous wig and bow. Her voice is powerful and recognisable from the first note.","fact":"She wrote or co-wrote hits for other stars, among them \"Diamonds\" for Rihanna.","wiki_en":"Sia (musician)","top_song":"Chandelier"},{"name":"Sam Smith","emoji":"🎙️","meta":["pop","United Kingdom","since 2012"],"description":"The British singer's soaring soul voice first reached a wide audience through the Disclosure track \"Latch\", and they went on to build a successful solo career. Their lyrics circle around love, vulnerability and identity.","fact":"The song \"Writing's on the Wall\", for the James Bond film \"Spectre\", won them an Academy Award.","wiki_en":"Sam Smith","top_song":"Stay With Me"},{"name":"Lorde","emoji":"👑","meta":["alternative pop","New Zealand","since 2013"],"description":"The New Zealand singer found worldwide success as a teenager with \"Royals\", a minimal, wry single taking aim at the glamour of pop culture. She is known for a thoughtful, literary way of writing songs that is unusual in pop.","fact":"Lorde wrote and recorded \"Royals\" while still at school, long before she was of age.","wiki_en":"Lorde","top_song":"Royals"},{"name":"Olivia Rodrigo","emoji":"💜","meta":["pop rock","United States","since 2020"],"description":"The American singer began her career as an actress in Disney shows and then became a star overnight with her debut single \"drivers license\". Her music sets pop melodies against a raw punk and rock charge.","fact":"Soon after its release, \"drivers license\" broke single-day streaming records on several platforms at once.","wiki_en":"Olivia Rodrigo","top_song":"drivers license"},{"name":"Doja Cat","emoji":"🐱","meta":["hip-hop","United States","since 2013"],"description":"The American rapper and singer became known through tracks that went viral online and then established herself as one of the biggest pop stars of the late 2010s and early 2020s. She mixes hip-hop, pop and R&B freely, usually with a wink.","fact":"Doja Cat's early song \"Mooo!\" went viral thanks to a deliberately absurd video in which she played a cow.","wiki_en":"Doja Cat","top_song":"Say So"},{"name":"SZA","emoji":"🌊","meta":["R&B","United States","since 2012"],"description":"The American R&B singer's debut album \"Ctrl\" became one of the essential records of the genre in the 2010s, on the strength of its honest, confessional writing. She is known for a soft, floating voice and a sound well outside the mainstream template.","fact":"The title \"Ctrl\" refers to the singer's wish to take control of her own life and her own work.","wiki_en":"SZA","top_song":"Kill Bill"},{"name":"Imagine Dragons","emoji":"🐉","meta":["rock","United States","since 2008"],"description":"The American rock band from Las Vegas is known for a huge stadium sound with electronic textures and hip-hop rhythms underneath. Their single \"Radioactive\" held the record for the longest run on the American chart for years.","fact":"The band's name is an anagram of a phrase the members have never revealed publicly.","wiki_en":"Imagine Dragons","top_song":"Radioactive"},{"name":"twenty one pilots","emoji":"🎭","meta":["alternative","United States","since 2009"],"description":"The duo from Ohio mixes rock, hip-hop, electronics and reggae, and is known live for stage stunts that border on dangerous. Their lyrics deal again and again with anxiety and what goes on inside the head.","fact":"At concerts the pair often play part of the set in masks, or climb the lighting rig above the crowd.","wiki_en":"Twenty One Pilots","top_song":"Stressed Out"},{"name":"Tame Impala","emoji":"🌀","meta":["psychedelic rock","Australia","since 2007"],"description":"The project of Australian musician Kevin Parker, who writes and records almost everything himself, joining psychedelic rock to elements of disco and electronics. Live shows come wrapped in dizzying psychedelic visuals.","fact":"For concerts Parker puts together a full band, although on the records he plays nearly every part himself.","wiki_en":"Tame Impala","top_song":"The Less I Know the Better"},{"name":"David Guetta","emoji":"🎧","meta":["electronic music","France","since 1984"],"description":"The French DJ and producer was one of the chief architects of electronic dance music's crossover into the global mainstream in the late 2000s. He regularly brings pop and hip-hop stars in to sing on his tracks.","fact":"David Guetta has spent years among the highest-paid DJs in the world according to the trade press.","wiki_en":"David Guetta","top_song":"Titanium"},{"name":"Calvin Harris","emoji":"🎧","meta":["electronic music","United Kingdom","since 2007"],"description":"The Scottish DJ and producer started out making his own electropop records and became one of the most sought-after writers of dance hits for other artists. For years he has regularly topped the lists of the world's highest-paid DJs.","fact":"Before he became an in-demand producer, Calvin Harris sang the vocal parts on his own early singles himself.","wiki_en":"Calvin Harris","top_song":"Summer"},{"name":"Avicii","emoji":"🎹","meta":["electronic music","Sweden","2006–2018"],"description":"The Swedish DJ and producer was one of the defining writers of the EDM boom, joining electronic dance music to folk and country motifs. His single \"Wake Me Up\" became one of the most successful dance tracks of the decade.","fact":"Because of ill health, Avicii stopped performing live several years before his death in 2018 and concentrated on studio work alone.","wiki_en":"Avicii","top_song":"Wake Me Up"},{"name":"Tiësto","emoji":"🎧","meta":["trance","Netherlands","since 1994"],"description":"The Dutch DJ was one of the pioneers of trance and later became a central figure on the global EDM scene. He was the first DJ ever to perform at the opening ceremony of an Olympic Games.","fact":"His real name is Tijs Verwest, and his stage name grew out of a childhood nickname.","wiki_en":"Tiësto","top_song":"Red Lights"},{"name":"Skrillex","emoji":"🎧","meta":["dubstep","United States","since 2004"],"description":"The American producer did more than almost anyone to carry the aggressive dubstep sound, with its lurching bass drops, out of the underground and into the mainstream in the early 2010s. He previously sang in the post-hardcore band From First to Last.","fact":"His early dance releases won him several Grammy Awards in the electronic categories.","wiki_en":"Skrillex","top_song":"Bangarang"},{"name":"Marshmello","emoji":"🍡","meta":["electronic music","United States","since 2015"],"description":"The American DJ and producer performs in a signature helmet shaped like a marshmallow and has never publicly revealed his face. He works at the meeting point of electronic dance music, pop and hip-hop.","fact":"His virtual concert inside the game Fortnite was watched simultaneously by millions of players.","wiki_en":"Marshmello","top_song":"Happier"},{"name":"Swedish House Mafia","emoji":"🎧","meta":["electronic music","Sweden","since 2008"],"description":"The Swedish DJ trio became one of the emblems of the festival EDM boom at the turn of the 2010s. After several years of solo careers the members reunited for new shows and new records.","fact":"After the trio first split, each member — Axwell, Sebastian Ingrosso and Steve Angello — carried on with a successful solo DJ career.","wiki_en":"Swedish House Mafia","top_song":"Don't You Worry Child"},{"name":"Major Lazer","emoji":"🔊","meta":["electronic music","United States","since 2008"],"description":"A project created by the producer Diplo, built on Caribbean rhythms — dancehall and reggae — filtered through electronic dance music. The single \"Lean On\", with its Indian motifs, became one of the most-streamed tracks of its time.","fact":"When it came out, \"Lean On\" became one of the most-watched electronic music videos on YouTube.","wiki_en":"Major Lazer","top_song":"Lean On"},{"name":"BTS","emoji":"💜","meta":["K-pop","South Korea","since 2013"],"description":"The South Korean boy band became one of the most successful musical acts in the world and the chief emblem of K-pop's global rise. Beyond the music they are known for their close bond with the ARMY fan community and for speaking at the United Nations.","fact":"\"Dynamite\", sung entirely in English, was their first song to top the American chart.","wiki_en":"BTS","top_song":"Dynamite"},{"name":"BLACKPINK","emoji":"🖤","meta":["K-pop","South Korea","since 2016"],"description":"The South Korean girl group of four became one of the great global symbols of K-pop alongside BTS. They pair fiercely drilled choreography with elements of hip-hop and glossy electropop.","fact":"BLACKPINK videos are regularly among the fastest-growing on YouTube, across every musical artist on the platform.","wiki_en":"Blackpink","top_song":"DDU-DU DDU-DU"},{"name":"PSY","emoji":"🐎","meta":["K-pop","South Korea","since 2001"],"description":"The South Korean singer became a worldwide star with the viral hit \"Gangnam Style\" and its unmistakable horse-riding dance. The video was the first on YouTube ever to pass a billion views.","fact":"The video collected so many views that YouTube had to raise the maximum value its view counter could hold.","wiki_en":"Psy","top_song":"Gangnam Style"},{"name":"Måneskin","emoji":"⚡","meta":["rock","Italy","since 2016"],"description":"The Italian rock band became known worldwide after winning the Eurovision Song Contest with \"Zitti e buoni\", then confirmed their success with the viral hit \"Beggin'\". They are dragging loud guitar rock back into the mainstream.","fact":"After winning Eurovision in 2021 the band was suspected of taking drugs on stage, but a test taken on the spot found nothing.","wiki_en":"Måneskin","top_song":"Beggin'"},{"name":"Hozier","emoji":"🌿","meta":["rock","Ireland","since 2013"],"description":"The Irish singer-songwriter broke into the charts with his debut single \"Take Me to Church\", a blues- and gospel-tinged attack on religious intolerance. He is known for a deep, low voice and lyrics with a social charge.","fact":"The video for \"Take Me to Church\" deals with the persecution of LGBT people and did much to bring the song worldwide attention.","wiki_en":"Hozier","top_song":"Take Me to Church"},{"name":"John Legend","emoji":"🎹","meta":["R&B","United States","since 2000"],"description":"The American singer-songwriter and pianist is known for a soft soul voice and unabashedly romantic ballads. He is one of very few artists to hold the full EGOT set of awards: an Emmy, a Grammy, an Oscar and a Tony.","fact":"He wrote his best-known ballad, \"All of Me\", about his wife, the model Chrissy Teigen.","wiki_en":"John Legend","top_song":"All of Me"},{"name":"Frank Ocean","emoji":"🌊","meta":["R&B","United States","since 2010"],"description":"The American R&B singer and songwriter, a member of the Odd Future collective, is known for introspective lyrics and for album structures that ignore the conventions of the genre. He gives interviews and performs extraordinarily rarely, which only deepens the cult around his music.","fact":"Frank Ocean released the album \"Blonde\" out of nowhere, with no announced date, catching the whole industry off guard.","wiki_en":"Frank Ocean","top_song":"Thinkin Bout You"},{"name":"Tyler, The Creator","emoji":"🌻","meta":["hip-hop","United States","since 2007"],"description":"The American rapper, producer and Odd Future member began with deliberately aggressive and provocative lyrics and moved over time towards a more melodic, jazz- and soul-inflected sound. He is also known as a designer and the founder of the Golf Wang label.","fact":"Because of the harsh lyrics on his early albums, Tyler, The Creator was banned from entering the United Kingdom for several years.","wiki_en":"Tyler, the Creator","top_song":"EARFQUAKE"},{"name":"J. Cole","emoji":"🎤","meta":["hip-hop","United States","since 2007"],"description":"The rapper from North Carolina is known for introspective lyrics and for a reputation as one of the few hip-hop artists whose albums reliably go platinum with no guest features at all. He founded the Dreamville label and produces younger musicians.","fact":"Besides music, he managed a spell playing in a professional basketball league in Africa.","wiki_en":"J. Cole","top_song":"No Role Modelz"},{"name":"Future","emoji":"🔮","meta":["trap","United States","since 2004"],"description":"The rapper from Atlanta is one of the key architects of the modern trap sound, known for a distinctive use of autotune and a staggering output of mixtapes and albums. His influence on a whole generation of hip-hop artists has been immense.","fact":"The flute in the chorus of \"Mask Off\" was sampled from an old musical theatre song and became one of the most recognisable details of the track.","wiki_en":"Future (rapper)","top_song":"Mask Off"},{"name":"XXXTENTACION","emoji":"🖤","meta":["emo rap","United States","2013–2018"],"description":"The American rapper was one of the pioneers of emo rap, mixing hip-hop with elements of rock and punk, and known for extremely bleak, confessional lyrics. His career and his life were cut short when he was murdered at the age of twenty.","fact":"After his death his album went to number one, and he remains one of the most-streamed artists anywhere, despite a very short career.","wiki_en":"XXXTentacion","top_song":"SAD!"},{"name":"Juice WRLD","emoji":"🌙","meta":["emo rap","United States","2015–2019"],"description":"The American rapper and singer joined hip-hop to emo and pop-punk influences, and was famous for writing and recording songs off the top of his head, with almost no preparation. His single \"Lucid Dreams\" became one of the great emo rap hits of the late 2010s.","fact":"His biggest hit, \"Lucid Dreams\", is built on a sample of Sting's \"Shape of My Heart\".","wiki_en":"Juice Wrld","top_song":"Lucid Dreams"},{"name":"Lil Nas X","emoji":"🤠","meta":["hip-hop","United States","since 2018"],"description":"The American rapper became famous through the viral hit \"Old Town Road\", which mixed country with trap. The track set the record for the most weeks at number one on the Billboard Hot 100.","fact":"He broke the track himself: the song spread across TikTok long before any major label took notice.","wiki_en":"Lil Nas X","top_song":"Old Town Road"},{"name":"Macklemore","emoji":"🧥","meta":["hip-hop","United States","since 2000"],"description":"The American rapper from Seattle works mainly with the producer Ryan Lewis and is known for wry lyrics and for reaching success independently of the major labels. His single \"Thrift Shop\" became one of the most recognisable hip-hop hits of the early 2010s.","fact":"Together with Ryan Lewis he won four Grammy Awards, including Best New Artist.","wiki_en":"Macklemore","top_song":"Thrift Shop"},{"name":"Pitbull","emoji":"🕺","meta":["hip-hop","United States","since 2000"],"description":"The American rapper of Cuban descent is known for relentless dance tracks, for the catchphrase \"Mr. Worldwide\" and for an enormous list of collaborations with pop stars. He raps and sings freely in both English and Spanish.","fact":"His real name is Armando Christian Pérez, and the nickname Mr. 305 refers to the telephone area code of Miami.","wiki_en":"Pitbull (rapper)","top_song":"Timber"},{"name":"Flo Rida","emoji":"🌴","meta":["hip-hop","United States","since 2007"],"description":"The American rapper from Florida became known for dance-floor hip-hop hits built on bold samples and choruses nobody forgets. His single \"Low\", with T-Pain, was one of the defining dance tracks of the late 2000s.","fact":"The stage name Flo Rida is simply a split spelling of Florida, his home state.","wiki_en":"Flo Rida","top_song":"Low"},{"name":"Jason Derulo","emoji":"🎤","meta":["pop","United States","since 2009"],"description":"The American singer is known for the trademark habit of announcing his own name at the start of almost every song. He blends pop, R&B and dance rhythms, and lands in charts around the world with reliable regularity.","fact":"He started out as a songwriter, writing lyrics for other artists before he had any hits of his own.","wiki_en":"Jason Derulo","top_song":"Talk Dirty"},{"name":"Chris Brown","emoji":"🕺","meta":["R&B","United States","since 2005"],"description":"The American R&B singer and dancer debuted as a teenager with the single \"Run It!\" and has remained a major figure in the genre ever since, on the strength of his voice and his dancing. His videos and concerts are known for intricate routines, and his hits include \"Forever\", \"Kiss Kiss\" and \"Under the Influence\".","fact":"He recorded his debut single \"Run It!\" at sixteen, and it went straight to the top of the American chart.","wiki_en":"Chris Brown","top_song":"Run It!"},{"name":"Ne-Yo","emoji":"🎩","meta":["R&B","United States","since 2005"],"description":"The American R&B singer and songwriter was writing hits for other stars before his own solo career took off. He is known for a smooth voice and for setting classic R&B against contemporary dance rhythms.","fact":"Before becoming a solo star, Ne-Yo wrote the hit \"Let Me Love You\" for the singer Mario.","wiki_en":"Ne-Yo","top_song":"So Sick"},{"name":"Michael Bublé","emoji":"🎩","meta":["jazz","Canada","since 2003"],"description":"The Canadian singer brought the classic jazz and big band repertoire, Sinatra-style, back into fashion for a wide modern audience. He is known for a warm baritone and for the Christmas albums he keeps making.","fact":"Michael Bublé's Christmas album has returned to the charts every December for more than a decade running.","wiki_en":"Michael Bublé","top_song":"Haven't Met You Yet"},{"name":"Andrea Bocelli","emoji":"🎼","meta":["operatic crossover","Italy","since 1994"],"description":"The Italian tenor lost his sight as a child and became one of the most commercially successful performers of classical and operatic crossover anywhere in the world. His duets and solo records turn into global hits with striking regularity.","fact":"Andrea Bocelli lost his sight completely at the age of twelve, after an injury sustained while playing football.","wiki_en":"Andrea Bocelli","top_song":"Con te partirò"},{"name":"Luciano Pavarotti","emoji":"🎼","meta":["opera","Italy","1961–2007"],"description":"One of the greatest tenors of the twentieth century, famous for a powerful and improbably clean voice and for the aria \"Nessun dorma\", which became his calling card. He did an enormous amount to carry opera to a mass audience, not least through the Three Tenors.","fact":"Pavarotti's recording of \"Nessun dorma\" was the official theme of the 1990 football World Cup in Italy.","wiki_en":"Luciano Pavarotti","top_song":"Nessun dorma"},{"name":"Norah Jones","emoji":"🎹","meta":["jazz","United States","since 2002"],"description":"The American singer and pianist saw her debut album \"Come Away with Me\" become one of the unlikeliest bestsellers of the early 2000s, bringing jazz, pop and country together. Her soft, warm voice became her signature.","fact":"Norah Jones's debut album \"Come Away with Me\" won several Grammy Awards at once, including Album of the Year.","wiki_en":"Norah Jones","top_song":"Don't Know Why"},{"name":"Nina Simone","emoji":"🎹","meta":["jazz","United States","1954–2003"],"description":"The American singer, pianist and civil rights activist had a deep, dramatic voice and a classical piano training, which made her one of the most singular figures in twentieth-century jazz and soul. Many of her songs spoke directly to the struggle for Black American civil rights.","fact":"Before she became a singer, Nina Simone dreamed of a career as a classical concert pianist.","wiki_en":"Nina Simone","top_song":"Feeling Good"},{"name":"Ella Fitzgerald","emoji":"🎤","meta":["jazz","United States","1934–1993"],"description":"The American jazz singer was called the First Lady of Song for her immaculate voice and her dazzling command of scat improvisation. She recorded hundreds of songs from the Great American Songbook and set the standard for how jazz standards are sung.","fact":"Her road to the stage began with a win at an amateur night at the Apollo Theater in New York.","wiki_en":"Ella Fitzgerald","top_song":"Summertime"},{"name":"Miles Davis","emoji":"🎺","meta":["jazz","United States","1944–1991"],"description":"The American trumpeter and composer was one of the most influential musicians in the history of jazz, and several times over his career he redirected the whole genre, from bebop to jazz rock. His album \"Kind of Blue\" remains one of the best-selling jazz records ever made.","fact":"Much of \"Kind of Blue\" was played by the musicians almost at sight, with barely any rehearsal, which gave the record its extraordinary freshness.","wiki_en":"Miles Davis","top_song":"So What"},{"name":"Sade","emoji":"🌹","meta":["soul","United Kingdom","since 1982"],"description":"The British band led by singer Sade Adu built a velvet, spare soul sound that made them one of the most recognisable acts of 1980s smooth soul. New albums come rarely, and yet their audience around the world has never drifted away.","fact":"The singer's full name is Helen Folasade Adu, and the band takes its name from her middle name.","wiki_en":"Sade (band)","top_song":"Smooth Operator"},{"name":"Enya","emoji":"🍃","meta":["new age","Ireland","since 1982"],"description":"The Irish singer and composer builds a layered, cavernous sound by stacking dozens of her own vocal tracks one on top of another. Her music joins Celtic motifs to new age and electronic textures.","fact":"Her song \"May It Be\" plays over the closing credits of the first film in \"The Lord of the Rings\" trilogy.","wiki_en":"Enya","top_song":"Only Time"},{"name":"Björk","emoji":"🦢","meta":["alternative","Iceland","since 1977"],"description":"The Icelandic singer and composer is known for fearless experiments where electronics, the avant-garde and pop meet, and for her eccentric stage costumes. She is one of the most singular and influential figures on the alternative scene of the past few decades.","fact":"At the Academy Awards in 2001 Björk appeared in the famous swan dress, one of the most discussed outfits in red carpet history.","wiki_en":"Björk","top_song":"It's Oh So Quiet"},{"name":"Leonard Cohen","emoji":"🕯️","meta":["folk","Canada","1967–2016"],"description":"The Canadian poet, novelist and singer began his music career as an adult, after he had already made his name in literature. His song \"Hallelujah\" became one of the most covered pieces in popular music, though it went almost unnoticed when it first appeared.","fact":"He managed to release his last album, \"You Want It Darker\", just a few weeks before his death at the age of 82.","wiki_en":"Leonard Cohen","top_song":"Hallelujah"},{"name":"Joe Cocker","emoji":"🎤","meta":["rock","United Kingdom","1961–2014"],"description":"The British rock and blues singer had a hoarse, straining voice and made his name largely through ferocious cover versions of other people's songs. His performance at Woodstock of \"With a Little Help from My Friends\" became legendary.","fact":"Joe Cocker's convulsive, wildly expressive way of moving on stage became so recognisable that it has been parodied many times.","wiki_en":"Joe Cocker","top_song":"With a Little Help from My Friends"},{"name":"Chris Rea","emoji":"🚗","meta":["rock","United Kingdom","since 1978"],"description":"The British rock musician, with his trademark rasp and unmistakable slide guitar, became especially popular in continental Europe. His song \"Driving Home for Christmas\" has turned into one of the great Christmas staples of radio.","fact":"\"Driving Home for Christmas\" has grown so popular over the years that it now returns to the airwaves and the charts every December.","wiki_en":"Chris Rea","top_song":"Driving Home for Christmas"},{"name":"Bryan Adams","emoji":"🎸","meta":["rock","Canada","since 1978"],"description":"The Canadian rock musician wrote melodic stadium rock hits and ballads that played on radio all over the world for decades. His ballad \"(Everything I Do) I Do It for You\", from the film \"Robin Hood: Prince of Thieves\", became one of the longest-running number ones in British chart history.","fact":"\"(Everything I Do) I Do It for You\" spent a record number of weeks at number one on the British singles chart.","wiki_en":"Bryan Adams","top_song":"(Everything I Do) I Do It for You"},{"name":"Joe Dassin","emoji":"🎶","meta":["chanson","France","1965–1980"],"description":"The French-American singer became one of the best-loved performers of French chanson on the strength of warm, melodic songs and a soft baritone. His \"Les Champs-Élysées\" remains one of the most recognisable French songs in the world.","fact":"Joe Dassin was born in the United States, the son of the film director Jules Dassin, but found worldwide fame as a French-language singer.","wiki_en":"Joe Dassin","top_song":"Les Champs-Élysées"},{"name":"Adriano Celentano","emoji":"🕺","meta":["pop","Italy","since 1957"],"description":"The Italian singer, actor and director is one of the great emblems of Italian popular song in the second half of the twentieth century. He is known for an explosive, almost danced delivery and for \"Prisencolinensinainciusol\", a spoof song that imitates the sound of English without using any real words.","fact":"On \"Prisencolinensinainciusol\" Celentano deliberately sang nonsense that sounds like English, to show how the language comes across to those who do not speak it.","wiki_en":"Adriano Celentano","top_song":"Azzurro"},{"name":"Toto Cutugno","emoji":"🎶","meta":["pop","Italy","1966–2023"],"description":"The Italian singer and composer wrote \"L'italiano\", one of the great anthems of Italian popular song, a celebration of national identity and culture. He won the Sanremo Festival and represented Italy at the Eurovision Song Contest.","fact":"Toto Cutugno won Eurovision in 1990, representing Italy with the song \"Insieme: 1992\".","wiki_en":"Toto Cutugno","top_song":"L'italiano"},{"name":"Mylène Farmer","emoji":"🖤","meta":["pop","France","since 1984"],"description":"The French singer is one of the most successful and most enigmatic figures in French-language pop, known for darkly theatrical personas and for giving almost no public interviews at all. Her concerts are staged as vast visual productions.","fact":"Almost all of her major songs were written in tandem with the composer Laurent Boutonnat.","wiki_en":"Mylène Farmer","top_song":"Désenchantée"},{"name":"Patricia Kaas","emoji":"🎤","meta":["chanson","France","since 1985"],"description":"The French singer has a low, velvet voice and moves between chanson, pop and jazz inflections. She is one of the most popular French-language performers in Eastern Europe, Russia included.","fact":"In 2009 she represented France at the Eurovision Song Contest with \"Et s'il fallait le faire\".","wiki_en":"Patricia Kaas","top_song":"Mademoiselle chante le blues"},{"name":"Édith Piaf","emoji":"🕊️","meta":["chanson","France","1935–1963"],"description":"The French singer is the legend of chanson, and her tiny frame paired with an enormous, breaking voice earned her the nickname the Little Sparrow. After a brutal childhood and a long string of personal tragedies, she poured everything she had lived into songs about love and loss.","fact":"She was given the name Piaf, Parisian slang for sparrow, as a young woman, because of how small she was.","wiki_en":"Édith Piaf","top_song":"La Vie en rose"},{"name":"Charles Aznavour","emoji":"🎩","meta":["chanson","France","1946–2018"],"description":"The French singer and songwriter of Armenian descent was one of the most prolific and longest-performing artists in twentieth-century French chanson. His song \"La Bohème\", about the lives of poor Parisian painters, became one of the calling cards of the genre.","fact":"Charles Aznavour went on giving concerts almost to the very end, still on stage into his nineties.","wiki_en":"Charles Aznavour","top_song":"La Bohème"},{"name":"C.C. Catch","emoji":"💿","meta":["Euro-disco","Germany","since 1985"],"description":"The Dutch-German singer became one of the stars of the 1980s Euro-disco scene through her work with the producer Dieter Bohlen. Her dance hits were especially popular in Eastern Europe.","fact":"The stage name C.C. Catch was invented for her by Dieter Bohlen, the producer also behind the success of Modern Talking.","wiki_en":"C.C. Catch","top_song":"Heaven and Hell"},{"name":"Haddaway","emoji":"💃","meta":["Eurodance","Germany","since 1993"],"description":"His Eurodance hit \"What Is Love\" became one of the most recognisable dance songs of the 1990s and later picked up a whole second life thanks to the head-nodding sketch on \"Saturday Night Live\".","fact":"His real name is Nestor Alexander Haddaway, and he was born in Trinidad.","wiki_en":"Haddaway","top_song":"What Is Love"},{"name":"Aqua","emoji":"🧜‍♀️","meta":["Eurodance","Denmark","since 1994"],"description":"The Danish-Norwegian group became famous for the tongue-in-cheek Eurodance hit \"Barbie Girl\", built around the image of the famous doll. The song drew a lawsuit from Mattel and went on to become one of the great dance hits of the 1990s.","fact":"Mattel, the maker of the Barbie doll, sued the band over its use of the toy's image, and lost the case.","wiki_en":"Aqua (band)","top_song":"Barbie Girl"},{"name":"Eiffel 65","emoji":"💙","meta":["Eurodance","Italy","since 1998"],"description":"The Italian group became known for the hit \"Blue (Da Ba Dee)\", with its trademark vocoder and a chorus of nonsense syllables that nobody could shake off. The song became one of the defining emblems of the late-1990s Eurodance sound.","fact":"Their follow-up single \"Move Your Body\" also became a substantial European dance hit.","wiki_en":"Eiffel 65","top_song":"Blue (Da Ba Dee)"},{"name":"Kino","emoji":"🖤","meta":["rock","USSR","1981–1990"],"description":"The Leningrad rock band led by Viktor Tsoi became one of the great symbols of Soviet rock during the upheaval of the late 1980s. Their songs \"Peremen!\" (\"Changes!\") and \"Gruppa krovi\" (\"Blood Type\") turned into the unofficial anthems of an entire generation.","fact":"Viktor Tsoi died in a car crash in 1990, yet the band remains one of the most listened-to acts across the former Soviet Union.","wiki_en":"Kino (band)","top_song":"Группа крови","ru":true},{"name":"Alla Pugacheva","emoji":"👑","meta":["pop","Russia","since 1965"],"description":"One of the best-known Soviet and Russian pop singers, she began her career back in the 1960s and kept it going for decade after decade. She is known for a fierce stage temperament and for her standing as the biggest star of Soviet, and then Russian, popular song.","fact":"Alla Pugacheva sang \"A Million Scarlet Roses\" to music a Latvian composer had originally written as a completely different piece.","wiki_en":"Alla Pugacheva","top_song":"Миллион алых роз","ru":true},{"name":"Zemfira","emoji":"🎸","meta":["rock","Russia","since 1999"],"description":"The Russian rock singer and songwriter burst onto the scene at the end of the 1990s with a debut album that became a cult record among young listeners overnight. She is known for a raw, highly charged voice and lyrics about love and loneliness.","fact":"Ilya Lagutenko, the leader of the band Mumiy Troll, helped her get her debut album released.","wiki_en":"Zemfira","top_song":"Искала","ru":true},{"name":"Splean","emoji":"🎸","meta":["rock","Russia","since 1994"],"description":"The St Petersburg rock band led by Alexander Vasilyev is known for poetic, faintly melancholy lyrics and an unmistakably level, unhurried voice. They have been one of the most consistently popular Russian rock acts for three decades.","fact":"The title of their song \"Orbit bez sakhara\" plays on a chewing gum advertising slogan, though the lyrics have nothing to do with advertising.","wiki_en":"Splean","top_song":"Орбит без сахара","ru":true},{"name":"DDT","emoji":"🎸","meta":["rock","Russia","since 1980"],"description":"The rock band led by Yuri Shevchuk is one of the essential acts of Soviet and Russian rock, known for its frontman's outspoken politics and for poetic, often pointedly social lyrics. They started out in Ufa and became famous across the whole country after moving to Leningrad.","fact":"Yuri Shevchuk trained as an artist: he graduated from an art and graphics faculty and worked for a while as a drawing teacher.","wiki_en":"DDT (band)","top_song":"Что такое осень","ru":true},{"name":"Aquarium","emoji":"🐟","meta":["rock","USSR","since 1972"],"description":"One of the oldest and most influential bands in Russian rock, founded by Boris Grebenshchikov in the early 1970s. They joined rock to folk, Eastern motifs and poetic, often philosophical lyrics, and in doing so opened up a whole strand of Soviet rock culture.","fact":"The song \"Gorod zolotoy\" (\"The Golden City\") owes much of its fame to the version Aquarium played in the cult film \"Assa\".","wiki_en":"Aquarium (band)","top_song":"Город золотой","ru":true},{"name":"Nautilus Pompilius","emoji":"🌊","meta":["rock","USSR","1982–1997"],"description":"The Sverdlovsk rock band led by Vyacheslav Butusov was one of the central acts of the Urals rock wave of the late 1980s. Their songs \"Chained Together\" and \"I Want to Be with You\" are classics of Russian rock.","fact":"The lyrics to many of the band's best-known songs were written not by any of the musicians but by the poet Ilya Kormiltsev.","wiki_en":"Nautilus Pompilius (band)","top_song":"Я хочу быть с тобой","ru":true},{"name":"Agata Kristi","emoji":"🖤","meta":["rock","Russia","1985–2010"],"description":"The rock band from Yekaterinburg, built around the Samoylov brothers, was known for a theatrical, faintly decadent look and dark lyrics sitting between rock and electronics. They were one of the most recognisable acts of the 1990s Urals rock scene.","fact":"The band is named after the famous detective novelist Agatha Christie, though the music has nothing to do with her books.","wiki_en":"Agatha Christie (band)","top_song":"Как на войне","wiki_ru":"Агата Кристи (группа)","ru":true},{"name":"Bi-2","emoji":"🎸","meta":["rock","Russia","since 1988"],"description":"The rock band was founded in Belarus but made its name in Russia, where its songs turned up in popular films and television series. They are known for a melodic, atmospheric sound and the unmistakable pairing of their two founders' voices.","fact":"The duo became famous across Russia with \"No One Writes to the Colonel\", heard in the film \"Brother 2\".","wiki_en":"Bi-2","top_song":"Полковнику никто не пишет","ru":true},{"name":"Mumiy Troll","emoji":"🌊","meta":["rock","Russia","since 1983"],"description":"The rock band from Vladivostok led by Ilya Lagutenko became one of the emblems of Russian rock in the late 1990s, thanks to a deliberately slurred, sticky vocal delivery and bright melodies. The album \"Morskaya\" carried them into the hits of the decade.","fact":"Before his music career, Ilya Lagutenko studied Chinese and spent several years working in China.","wiki_en":"Mumiy Troll","top_song":"Владивосток 2000","ru":true},{"name":"Leningrad","emoji":"🎺","meta":["rock","Russia","since 1997"],"description":"The St Petersburg band led by Sergey Shnurov is known for blunt, frequently obscene lyrics, a full horn section and a wry eye for Russian daily life. Their videos have repeatedly gone viral online.","fact":"The video for \"V Pitere — pit\" (\"Drinking in Petersburg\") drew tens of millions of views and became one of the most recognisable music videos in the Russian-speaking internet.","wiki_en":"Leningrad (band)","top_song":"В Питере — пить","ru":true},{"name":"Korol i Shut","emoji":"🃏","meta":["punk rock","Russia","1988–2013"],"description":"The St Petersburg punk rock band was known for theatrical costumes drawn from medieval ballads and for the horror stories their lyrics told. They were one of the most popular Russian rock bands of the 2000s among younger listeners.","fact":"The band's two singers were known to the public by nicknames: Gorshok and Knyaz, for Mikhail Gorshenev and Andrey Knyazev.","wiki_en":"Korol i Shut","top_song":"Кукла колдуна","ru":true},{"name":"Aria","emoji":"🤘","meta":["heavy metal","Russia","since 1985"],"description":"One of the first and best-known heavy metal bands in the Soviet Union and Russia, they set the standard for the whole Russian-language metal scene. They are known for a powerful voice, long guitar solos and lyrics drawn from epic fantasy and philosophy.","fact":"The lyrics to many of the band's best-known songs were written by the poet Margarita Pushkina.","wiki_en":"Aria (band)","top_song":"Штиль","ru":true},{"name":"Alisa","emoji":"⚔️","meta":["rock","USSR","since 1983"],"description":"The Leningrad rock band led by Konstantin Kinchev pairs a hard guitar sound with patriotic and pagan-philosophical themes in its lyrics. They were one of the central acts of the Leningrad Rock Club in the 1980s.","fact":"Konstantin Kinchev joined a band that already existed and soon became its leader and chief songwriter.","wiki_en":"Alisa (Russian band)","top_song":"Небо славян","ru":true},{"name":"Mashina Vremeni","emoji":"⏳","meta":["rock","USSR","since 1969"],"description":"One of the oldest Russian rock bands, founded by Andrey Makarevich at the end of the 1960s and still performing more than half a century later. Their songs became classics of Russian rock long ago and play on the radio whatever the listener's generation.","fact":"The band took its name from H. G. Wells's novel \"The Time Machine\".","wiki_en":"Mashina Vremeni","top_song":"Поворот","ru":true},{"name":"Chaif","emoji":"🎸","meta":["rock","USSR","since 1985"],"description":"The rock band from Yekaterinburg led by Vladimir Shakhrin is known for a warm, slightly wry sound and lyrics about ordinary human feeling. They are one of the steadiest acts on the Urals rock scene.","fact":"The name Chaif started as a joke, a contraction of the Russian words for tea and a good buzz.","wiki_en":"Chaif","top_song":"Ой-йо","ru":true},{"name":"Sektor Gaza","emoji":"🎸","meta":["punk rock","Russia","1987–2000"],"description":"The punk rock band from Voronezh led by Yuri Khoy was known for deliberately crude humour, provincial colour and songs about life in the Russian backwoods. Despite their leader's early death, they remain a cult band for several generations of listeners.","fact":"The real surname of the band's leader, Yuri Khoy, was Klinskikh; the nickname stuck to him as a young man.","wiki_en":"Sektor Gaza","top_song":"Лирика","ru":true},{"name":"Grazhdanskaya Oborona","emoji":"✊","meta":["punk rock","USSR","1984–2008"],"description":"The Siberian punk band led by Yegor Letov was one of the most radical and influential acts in the Soviet and Russian underground. They are known for a wilfully filthy lo-fi sound and harshly social, often anarchist lyrics.","fact":"The band's early albums were recorded on improvised home equipment, which gave them the lo-fi sound that later became their trademark.","wiki_en":"Grazhdanskaya Oborona","top_song":"Всё идёт по плану","ru":true},{"name":"Zveri","emoji":"🐺","meta":["pop rock","Russia","since 2000"],"description":"The Russian pop-rock band led by Roman Bilyk became one of the biggest radio acts of the mid-2000s with plain, unforgettable lyrics about city life. At their peak their songs seemed to be playing out of every window.","fact":"\"Rayony-kvartaly\" (\"Districts and Blocks\") became so popular that its title turned into everyday shorthand for the outer housing estates.","wiki_en":"Zveri","top_song":"Районы-кварталы","ru":true},{"name":"Ruki Vverh!","emoji":"🙌","meta":["pop","Russia","since 1996"],"description":"The Russian pop duo of Sergey Zhukov and Alexey Potekhin is one of the most recognisable emblems of Russian dance pop from the late 1990s and early 2000s. Their simple, instantly memorable songs played at every school disco of the era.","fact":"The duo stopped working in the mid-2000s, then returned years later and began filling stadiums.","wiki_en":"Ruki Vverh!","top_song":"18 мне уже","ru":true},{"name":"t.A.T.u.","emoji":"💋","meta":["pop","Russia","since 1999"],"description":"The Russian pop duo of Lena Katina and Yulia Volkova was one of very few Russian acts to achieve large-scale international success. Their image was built on the subject of same-sex relationships, which was deeply provocative in the late 1990s and caused a considerable stir.","fact":"The single \"All the Things She Said\" topped the charts in several European countries at once, a rare thing for a Russian pop act.","wiki_en":"t.A.T.u.","top_song":"All the Things She Said","ru":true},{"name":"Valery Meladze","emoji":"🎤","meta":["pop","Russia","since 1993"],"description":"The Russian pop singer of Georgian descent has been one of the most consistently popular figures on the Russian pop scene since the mid-1990s. He is known for melodic ballads and an unmistakably warm voice.","fact":"He trained as an engineer: before his music career he graduated from the shipbuilding institute in Nikolayev.","wiki_en":"Valery Meladze","top_song":"Сэра","ru":true},{"name":"Nu Virgos","emoji":"💃","meta":["pop","Ukraine","2000–2013"],"description":"The pop group put together by producer Konstantin Meladze became famous for glossy dance hits and for a line-up that changed constantly. They were one of the most commercially successful girl groups of the 2000s across the former Soviet Union.","fact":"The group's first two singers were Alyona Vinnitskaya and Nadezhda Granovskaya.","wiki_en":"Nu Virgos","top_song":"Стоп! Снято!","ru":true},{"name":"Philipp Kirkorov","emoji":"👑","meta":["pop","Russia","since 1988"],"description":"One of the most decorated performers in Russian popular music, known for outrageous stage costumes and a long shelf of music awards. He has worked with the leading Russian composers and has stayed a conspicuous figure in show business for decades.","fact":"Philipp Kirkorov is often called the king of Russian pop, an informal title that stuck to him back in the 1990s.","wiki_en":"Philipp Kirkorov","top_song":"Зайка моя","ru":true},{"name":"Vladimir Vysotsky","emoji":"🎸","meta":["bard song","USSR","1960s–1980"],"description":"The Soviet poet, actor and bard sang in a hoarse, straining voice with nothing but a guitar, and his songs became the unofficial chronicle of the Soviet era. He wrote about the war, the camps, sport and ordinary people, and remains one of the best-loved and most quoted writers in the country.","fact":"Vysotsky was barely released on official records in his lifetime, and his songs spread across the country on homemade tape recordings.","wiki_en":"Vladimir Vysotsky","top_song":"Кони привередливые","ru":true},{"name":"Muslim Magomayev","emoji":"🎤","meta":["estrada pop","USSR","1960s–2008"],"description":"The Soviet popular and operatic singer of Azerbaijani descent had a formidable baritone and was called one of the great voices of Soviet popular song. He moved between operatic arias and popular hits with equal confidence.","fact":"His grandfather and namesake, Muslim Magomayev, was a well-known Azerbaijani composer.","wiki_en":"Muslim Magomayev (musician)","top_song":"Лучший город земли","ru":true},{"name":"Mikhail Krug","emoji":"🎸","meta":["Russian chanson","Russia","1995–2002"],"description":"The Russian chanson singer from Tver wrote songs about prison and the street that made him one of the most popular artists in the genre at the end of the 1990s. His song \"Vladimirsky Tsentral\", named after a notorious prison, became one of the best-known pieces in Russian chanson.","fact":"Mikhail Krug was killed during a robbery at his own house in Tver in 2002.","wiki_en":"Mikhail Krug","top_song":"Владимирский централ","ru":true},{"name":"Sofia Rotaru","emoji":"🌹","meta":["pop","USSR","since 1966"],"description":"The Soviet and Ukrainian pop singer is one of the most decorated and longest-performing artists in the former Soviet Union. She is known for a wide repertoire, from Ukrainian folk songs to Russian-language pop hits.","fact":"Her duet with Jaak Joala on \"Lavanda\" (\"Lavender\") became one of the great hits of 1980s Soviet popular song.","wiki_en":"Sofia Rotaru","top_song":"Луна, луна","ru":true},{"name":"Dima Bilan","emoji":"🏆","meta":["pop","Russia","since 2000"],"description":"The Russian pop singer became a star in the early 2000s under the producer Yuri Aizenshpis, and then the first Russian artist to win the Eurovision Song Contest. His winning song \"Believe\" became one of the emblems of Russian pop in the 2000s.","fact":"Two years earlier he had already appeared at Eurovision, finishing second with \"Never Let You Go\".","wiki_en":"Dima Bilan","top_song":"Believe","ru":true},{"name":"Yuri Shatunov","emoji":"🎤","meta":["pop","USSR","1987–2022"],"description":"The Soviet and Russian pop singer became a teen idol in the group Laskovy May with \"White Roses\", which quickly turned into one of the defining hits of the late Soviet years. His thin, unmistakable voice made him a symbol of the music of the late 1980s.","fact":"\"White Roses\" grew so popular that it was sung all over the country, although Shatunov was only about fifteen when he recorded it.","wiki_en":"Yuri Shatunov","top_song":"Белые розы","ru":true},{"name":"Basta","emoji":"🎤","meta":["hip-hop","Russia","since 1995"],"description":"The Russian rapper and producer is one of the most prominent figures in the country's hip-hop, and over the years he widened his sound from straight rap to more melodic pop-rock songs. He is also known as the founder of the Gazgolder label.","fact":"He also recorded under the alter ego Noggano, in a completely different and deliberately thuggish style.","wiki_en":"Basta (rapper)","top_song":"Сансара","ru":true},{"name":"Oxxxymiron","emoji":"🎤","meta":["hip-hop","Russia","since 2011"],"description":"The Russian rapper is known for dense, many-layered lyrics and for his standing as one of the pioneers of battle rap in Russia, through his bouts on the Versus platform. He studied at Oxford, which is echoed in his stage name.","fact":"His battle with the rapper Gnoyny on Versus drew tens of millions of views and was the biggest event in Russian rap in 2017.","wiki_en":"Oxxxymiron","top_song":"Город под подошвой","ru":true},{"name":"Scriptonite","emoji":"🎧","meta":["hip-hop","Kazakhstan","since 2011"],"description":"The rapper and producer from Kazakhstan is known for a dark, atmospheric sound and for saying very little in public, giving interviews only rarely. He is one of the most influential figures in Russian-language hip-hop of the past decade.","fact":"He comes from Pavlodar in Kazakhstan, and the album \"A House with Normal Phenomena\" made his name.","wiki_en":"Scriptonite","top_song":"Танцуй сама","ru":true},{"name":"Noize MC","emoji":"🎤","meta":["hip-hop","Russia","since 2005"],"description":"The Russian rapper is known for sharp social and political lyrics and for ferocious live shows with an edge of punk rock. He is one of very few Russian hip-hop artists who regularly performs with a live band behind him.","fact":"The rapper's real name is Ivan Alexeyev, and he first became known through the internet while still a student.","wiki_en":"Noize MC","top_song":"Выдыхай","ru":true},{"name":"Max Korzh","emoji":"🎤","meta":["hip-hop","Belarus","since 2010"],"description":"The Belarusian artist combines hip-hop with melodic pop and has become one of the most popular Russian-language performers on the stadium circuit. His songs are built on plain, emotionally direct lyrics about growing up and about friendship.","fact":"Max Korzh fills some of the largest stadium tours of any Russian-language artist, although for a long time he barely appeared on television.","wiki_en":"Max Korzh","top_song":"Малый повзрослел","ru":true},{"name":"Miyagi & Andy Panda","emoji":"🎧","meta":["hip-hop","Russia","since 2016"],"description":"The Russian hip-hop duo from Vladikavkaz is known for a light, melodic sound sitting between rap and pop. Their track \"I Got Love\" became one of the most-streamed Russian-language hits ever released.","fact":"Their videos set off several viral dance challenges across the Russian-speaking internet.","wiki_en":"Miyagi & Andy Panda","top_song":"I Got Love","ru":true},{"name":"Little Big","emoji":"🎉","meta":["rave","Russia","since 2013"],"description":"The Russian rave band is known for grotesque, wilfully absurd videos and for a tongue-in-cheek mix of electronic dance music with trash and punk. Their video for \"Skibidi\", with its own dance, went viral all over the world.","fact":"In 2020 the band was due to represent Russia at Eurovision with \"Uno\", but the contest was cancelled because of the pandemic.","wiki_en":"Little Big (band)","top_song":"Skibidi","ru":true},{"name":"Monetochka","emoji":"🪙","meta":["pop","Russia","since 2016"],"description":"The Russian singer arrived with an ironic, wilfully naive pop sound hiding sharp and often sarcastic lyrics about modern life. Her real name is Yelizaveta Gyrdymova, and she first became known through releases put out online.","fact":"The album \"Coloring Books for Grown-Ups\" came out when she was about twenty and made her a notable figure in Russian indie pop at once.","wiki_en":"Monetochka","top_song":"Каждый раз","ru":true},{"name":"MORGENSHTERN","emoji":"💸","meta":["hip-hop","Russia","since 2016"],"description":"The Russian rapper and blogger shot to popularity on the back of an outrageous image, wry lyrics about money and status, and a relentless presence online. He was one of the most-streamed Russian-language artists of the late 2010s.","fact":"MORGENSHTERN started out making parody and comedy clips online, well before he took a music career seriously.","wiki_en":"Morgenshtern","top_song":"Cadillac","ru":true},{"name":"Zivert","emoji":"🎤","meta":["pop","Russia","since 2018"],"description":"The Russian pop singer became known through her work with a production house and through danceable electropop hits with choruses that lodge in the memory. Her songs are built on strong melodic hooks and a striking vocal range.","fact":"Before music she worked as a flight attendant, and her stage name is simply her real surname: Yulia Zivert.","wiki_en":"Zivert","top_song":"Life","ru":true},{"name":"The Kinks","emoji":"🎸","meta":["rock","United Kingdom","1963–1996"],"description":"The British rock band, founded by brothers Ray and Dave Davies, was one of the essential acts of the 1960s British Invasion. They are known for a savage guitar riff and witty lyrics about ordinary English life.","fact":"Their song \"You Really Got Me\", with its distorted riff, is regarded as one of the forerunners of both hard rock and punk.","wiki_en":"The Kinks","top_song":"You Really Got Me"},{"name":"Yes","emoji":"🌀","meta":["progressive rock","United Kingdom","since 1968"],"description":"One of the great progressive rock bands, formed in London and famous for long multi-part compositions and dazzling musicianship. Dozens of members have passed through the line-up, but the appetite for vast sonic architecture has never changed.","fact":"The fantastical landscapes on Yes album covers were painted by the artist Roger Dean, and his style became the band's visual signature.","wiki_en":"Yes (band)","top_song":"Owner of a Lonely Heart"},{"name":"Electric Light Orchestra","emoji":"🛸","meta":["rock","United Kingdom","1970–1986"],"description":"Jeff Lynne's British band joined rock instruments to symphonic arrangements and synthesisers, which earned them the description of the Beatles with strings. Their concerts came with a spectacular stage set built as a flying saucer.","fact":"The band's logo, an alien spacecraft, became one of the most recognisable symbols in 1970s rock.","wiki_en":"Electric Light Orchestra","top_song":"Mr. Blue Sky"},{"name":"Supertramp","emoji":"🎷","meta":["art rock","United Kingdom","1970–1988"],"description":"The British band made its name with philosophical lyrics and the unmistakable sound of a Wurlitzer electric piano set against a saxophone. The album \"Breakfast in America\" made them stars on both sides of the Atlantic.","fact":"The cover of \"Breakfast in America\", a waitress posed against the New York skyline, became one of the most recognisable in rock history.","wiki_en":"Supertramp","top_song":"The Logical Song"},{"name":"Steely Dan","emoji":"🎷","meta":["jazz rock","United States","since 1972"],"description":"The American duo of Walter Becker and Donald Fagen joined rock to intricate jazz harmony and lyrics thick with irony. They were famous for studio perfectionism and would bring in dozens of session musicians to make a single album.","fact":"In pursuit of the perfect sound, the duo would re-record the same guitar break with different players dozens of times over.","wiki_en":"Steely Dan","top_song":"Reelin' In the Years"},{"name":"Chicago","emoji":"🎺","meta":["rock","United States","since 1967"],"description":"The American band was one of the first to put a full horn section inside a rock line-up, which gave them their unmistakable sound. Over half a century they have released dozens of albums and remain among the most successful acts ever by number of chart hits.","fact":"For years the band simply numbered its albums, from \"Chicago II\" all the way to \"Chicago XXX\".","wiki_en":"Chicago (band)","top_song":"25 or 6 to 4"},{"name":"Crosby, Stills & Nash","emoji":"🎸","meta":["folk rock","United States","1968–2023"],"description":"The vocal trio of David Crosby, Stephen Stills and Graham Nash was known for intricate vocal harmonies and anti-war lyrics at the end of the 1960s. At times they played as a quartet with Neil Young, under the name Crosby, Stills, Nash & Young.","fact":"The trio played Woodstock as one of their first concerts ever, only a couple of weeks after the three had first sung together.","wiki_en":"Crosby, Stills & Nash","top_song":"Suite: Judy Blue Eyes"},{"name":"The Byrds","emoji":"🐦","meta":["folk rock","United States","1964–1973"],"description":"The American band was one of the first to join folk music to the chime of twelve-string electric guitars, and in doing so set the course of folk rock. Their version of Bob Dylan's \"Mr. Tambourine Man\" became the benchmark for how the genre should sound.","fact":"A great many musicians passed through the line-up, including the future founders of Crosby, Stills & Nash and The Flying Burrito Brothers.","wiki_en":"The Byrds","top_song":"Mr. Tambourine Man"},{"name":"Grateful Dead","emoji":"💀","meta":["psychedelic rock","United States","1965–1995"],"description":"The band from San Francisco was the emblem of the psychedelic era and of jam band culture, with concert improvisations that went on and on. Around them grew one of the most devoted fan communities in rock history, the Deadheads.","fact":"The band encouraged the audience to tape its concerts, which is why thousands of amateur recordings of their shows survive.","wiki_en":"Grateful Dead","top_song":"Truckin'"},{"name":"Jethro Tull","emoji":"🪈","meta":["progressive rock","United Kingdom","since 1967"],"description":"The British band is unusual in rock in that its leader Ian Anderson made the flute one of the principal solo instruments. They combined folk motifs, hard rock and thoroughly theatrical live shows.","fact":"The band took its name from an eighteenth-century English agriculturist, the inventor of the mechanical seed drill.","wiki_en":"Jethro Tull (band)","top_song":"Aqualung"},{"name":"Rush","emoji":"🎸","meta":["progressive rock","Canada","1968–2018"],"description":"The Canadian trio was famous for the virtuosity of every one of its three members and for intricate concept pieces sitting between progressive rock and hard rock. Drummer Neil Peart is considered one of the most technically gifted in the history of the genre.","fact":"For all their cult standing, the band was long undervalued by critics and was only inducted into the Rock and Roll Hall of Fame in 2013.","wiki_en":"Rush (band)","top_song":"Tom Sawyer"},{"name":"Whitesnake","emoji":"🐍","meta":["hard rock","United Kingdom","since 1978"],"description":"David Coverdale's British hard rock band grew out of the blues rock of the late 1970s into one of the emblems of glam metal in the MTV era. The video for the re-recorded version of \"Here I Go Again\" became a touchstone for the whole decade.","fact":"The name Whitesnake comes from a song on David Coverdale's solo album, released soon after he left Deep Purple at the end of the 1970s.","wiki_en":"Whitesnake","top_song":"Here I Go Again"},{"name":"Motörhead","emoji":"♠️","meta":["heavy metal","United Kingdom","1975–2015"],"description":"Lemmy Kilmister's British band played where punk met heavy metal: as loud, as fast and as coarse as it could possibly be. Their calling card, \"Ace of Spades\", became an anthem of speed and reckless nerve.","fact":"Lemmy was the only constant member across the band's entire history and kept performing until the last months of his life.","wiki_en":"Motörhead","top_song":"Ace of Spades"},{"name":"Twisted Sister","emoji":"🤘","meta":["glam metal","United States","since 1972"],"description":"Dee Snider's American glam metal band was known for lurid stage costumes and for the defiant anthem \"We're Not Gonna Take It\". Their videos were among the most heavily rotated on MTV in the mid-1980s.","fact":"Frontman Dee Snider testified before the United States Congress, alongside Frank Zappa, against labelling albums for explicit content.","wiki_en":"Twisted Sister","top_song":"We're Not Gonna Take It"},{"name":"Poison","emoji":"🌹","meta":["glam metal","United States","since 1983"],"description":"The American glam metal band was an emblem of the gaudy Los Angeles rock scene of the 1980s, all towering hair and relentless hooks. The ballad \"Every Rose Has Its Thorn\" became one of the most recognisable tracks of the hair metal era.","fact":"Before they became MTV stars, the band moved to Los Angeles with almost no money and spent the first stretch sleeping in their car.","wiki_en":"Poison (American band)","top_song":"Every Rose Has Its Thorn"},{"name":"Mötley Crüe","emoji":"🔥","meta":["glam metal","United States","since 1981"],"description":"The American band became the emblem of unrestrained 1980s rock star living, with the scandals, the crashes and the addictions that the members later described in detail in the book \"The Dirt\". Musically they set hard rock against glam theatricality.","fact":"A biographical film, \"The Dirt\", was made about the band's turbulent history, based on their own memoir of the same name.","wiki_en":"Mötley Crüe","top_song":"Kickstart My Heart"},{"name":"Alice Cooper","emoji":"🎭","meta":["shock rock","United States","since 1964"],"description":"The American musician is one of the founders of shock rock, a genre in which the theatrical spectacle of guillotines, snakes and blood matters as much as the music itself. His real name is Vincent Furnier, and Alice Cooper was originally the name of the whole band.","fact":"In concert Cooper regularly executed himself on stage, in an electric chair or a guillotine, and then walked out unharmed for the encore.","wiki_en":"Alice Cooper","top_song":"Poison"},{"name":"Meat Loaf","emoji":"🦇","meta":["rock","United States","1968–2022"],"description":"The American singer and actor made his name with a huge dramatic voice and the rock-opera album \"Bat Out of Hell\", which sold tens of millions of copies. His real name was Marvin Lee Aday.","fact":"\"Bat Out of Hell\" went on selling steadily for decades after its release and remains one of the most successful albums ever made.","wiki_en":"Meat Loaf","top_song":"I'd Do Anything for Love (But I Won't Do That)"},{"name":"Billy Idol","emoji":"🤘","meta":["rock","United Kingdom","since 1976"],"description":"The British singer came out of a punk past in the band Generation X and became one of the great MTV-era stars, on the strength of a snarling voice and a glare from under the brow. The hits \"White Wedding\" and \"Rebel Yell\" made him a style icon of the 1980s.","fact":"Billy Idol's trademark sneer, upper lip curled, became a visual signature parodied every bit as much as his music.","wiki_en":"Billy Idol","top_song":"White Wedding"},{"name":"INXS","emoji":"🎸","meta":["rock","Australia","1977–2012"],"description":"The Australian band became one of the most successful in the world in the late 1980s, on the strength of danceable rock and the magnetism of frontman Michael Hutchence. The album \"Kick\" and the single \"Need You Tonight\" brought them worldwide fame.","fact":"After Michael Hutchence's death in 1997, the band spent several years looking for a new singer, including through the television show \"Rock Star: INXS\".","wiki_en":"INXS","top_song":"Need You Tonight"},{"name":"Simple Minds","emoji":"🎹","meta":["new wave","United Kingdom","since 1977"],"description":"The Scottish band made its name with an atmospheric synth-rock sound and above all with \"Don't You (Forget About Me)\", written for the film \"The Breakfast Club\". The musicians themselves at first doubted whether they should record someone else's song.","fact":"The band only agreed to record \"Don't You (Forget About Me)\" after other performers had turned it down, Billy Idol among them.","wiki_en":"Simple Minds","top_song":"Don't You (Forget About Me)"},{"name":"Tears for Fears","emoji":"🌍","meta":["synth-pop","United Kingdom","since 1981"],"description":"The British duo of Roland Orzabal and Curt Smith took their name from the primal scream technique used in psychotherapy. Their album \"Songs from the Big Chair\", with the hit \"Everybody Wants to Rule the World\", became one of the defining pop records of the 1980s.","fact":"The band's name refers to the psychotherapist Arthur Janov's theory of the primal scream, which the two were fascinated by as young men.","wiki_en":"Tears for Fears","top_song":"Everybody Wants to Rule the World"},{"name":"Culture Club","emoji":"🦎","meta":["new wave","United Kingdom","since 1981"],"description":"Boy George's British band joined pop, reggae and soul to their frontman's arresting androgynous image. The single \"Karma Chameleon\" became one of the best-selling records of the 1980s in Britain.","fact":"Boy George's extravagant look in the band's early days caused such argument that television presenters sometimes could not tell whether he was a man or a woman.","wiki_en":"Culture Club","top_song":"Karma Chameleon"},{"name":"Wham!","emoji":"🎄","meta":["pop","United Kingdom","1981–1986"],"description":"The British pop duo of George Michael and Andrew Ridgeley was one of the most successful acts of the first half of the 1980s, built on light dance hits and their frontman's charm. Their song \"Last Christmas\" returns to the charts every year at Christmas.","fact":"\"Last Christmas\" only topped the British singles chart for the first time thirty-six years after its release, in January 2021.","wiki_en":"Wham!","top_song":"Last Christmas"},{"name":"Spandau Ballet","emoji":"🎷","meta":["new romantic","United Kingdom","since 1979"],"description":"The British band was one of the leading acts of the new romantic movement of the early 1980s, with an elegant sound and an even more carefully styled look. The ballad \"True\" became their great international hit.","fact":"The band's name, so the story goes, came after a friend saw the word Spandau written on the wall of a Berlin prison while travelling.","wiki_en":"Spandau Ballet","top_song":"True"},{"name":"Human League","emoji":"🎹","meta":["synth-pop","United Kingdom","since 1977"],"description":"The British band from Sheffield were pioneers of electronic synth-pop, built entirely on synthesisers instead of guitars. The single \"Don't You Want Me\" was a Christmas number one and became the benchmark of the genre.","fact":"The band was originally all male, but before recording the album \"Dare\", leader Phil Oakey found two singers in a nightclub.","wiki_en":"The Human League","top_song":"Don't You Want Me"},{"name":"Soft Cell","emoji":"💔","meta":["synth-pop","United Kingdom","since 1977"],"description":"The British electronic duo of Marc Almond and David Ball made their name with a darkly impassioned take on synth-pop. Their cover of the soul song \"Tainted Love\" became one of the most successful singles of the early 1980s worldwide.","fact":"\"Tainted Love\" began as a little-known soul record from 1964, and Soft Cell's version turned it into one of the most recognisable tracks of the decade.","wiki_en":"Soft Cell","top_song":"Tainted Love"},{"name":"New Order","emoji":"🎛️","meta":["electronic rock","United Kingdom","since 1980"],"description":"The British band emerged from the post-punk line-up of Joy Division after the death of their singer Ian Curtis, and was one of the first to weld rock to dance electronics. The single \"Blue Monday\" became the best-selling twelve-inch single in history.","fact":"The sleeve of \"Blue Monday\" was so expensive to produce that, as the story goes, the label lost money on every copy sold.","wiki_en":"New Order (band)","top_song":"Blue Monday"},{"name":"The Smiths","emoji":"🥀","meta":["indie rock","United Kingdom","1982–1987"],"description":"The British band of Morrissey and Johnny Marr is one of the most influential in the history of British indie rock, thanks to Marr's chiming guitars and their singer's witty, melancholy words. Generations of bands since have been formed in their image.","fact":"For all their cult standing, the band never once climbed higher than number five on the British singles chart.","wiki_en":"The Smiths","top_song":"This Charming Man"},{"name":"Morrissey","emoji":"🥀","meta":["indie rock","United Kingdom","since 1988"],"description":"The British singer, once the frontman of The Smiths, built a substantial solo career on an unmistakable melancholy irony and literary lyrics. He is also known for blunt and frequently contentious public statements.","fact":"Before his music career, Morrissey ran the British fan club of the New York Dolls and wrote music criticism.","wiki_en":"Morrissey","top_song":"Suedehead"},{"name":"UB40","emoji":"🍷","meta":["reggae","United Kingdom","since 1978"],"description":"The British reggae band from Birmingham took its name from the form used to claim unemployment benefit in Britain. Their cover of \"Red Red Wine\" became one of the great reggae hits of the pop charts worldwide.","fact":"They took the name UB40 from the dole form they were filling in themselves as unemployed young men.","wiki_en":"UB40","top_song":"Red Red Wine"},{"name":"Seal","emoji":"🌹","meta":["pop","United Kingdom","since 1990"],"description":"The British singer has an unmistakable velvet voice and the distinctive scars on his face left by lupus he suffered as a child. The ballad \"Kiss from a Rose\", heard in a Batman film, brought him worldwide fame and a Grammy.","fact":"\"Kiss from a Rose\" sat unused for several years before it became a hit through the soundtrack of \"Batman Forever\".","wiki_en":"Seal (musician)","top_song":"Kiss from a Rose"},{"name":"Peter Gabriel","emoji":"🔨","meta":["art rock","United Kingdom","since 1977"],"description":"The British musician, formerly the singer in Genesis, built a striking solo career on bold experiments with sound and image. The stop-motion video for \"Sledgehammer\" became one of the most awarded in MTV history.","fact":"The \"Sledgehammer\" video held the record for years as the most played video in the history of MTV.","wiki_en":"Peter Gabriel","top_song":"Sledgehammer"},{"name":"Kate Bush","emoji":"🔮","meta":["art pop","United Kingdom","since 1978"],"description":"The British singer has a singular, almost operatic voice and a dancer's presence, and began her career as a teenager with \"Wuthering Heights\". Decades after its release, \"Running Up That Hill\" became a hit all over again through the series \"Stranger Things\".","fact":"At seventeen Kate Bush became the first woman to top the British singles chart with a song she had written herself, \"Wuthering Heights\".","wiki_en":"Kate Bush","top_song":"Running Up That Hill"},{"name":"Annie Lennox","emoji":"🎤","meta":["pop","United Kingdom","since 1980"],"description":"The Scottish singer is known both as the voice of the duo Eurythmics and as a solo artist with a powerful, inimitable voice. The solo album \"Diva\" confirmed her standing as one of the great singers of her generation.","fact":"Annie Lennox's cover of \"No More I Love You's\" won her a Grammy and became one of the biggest hits of her solo career.","wiki_en":"Annie Lennox","top_song":"No More I Love You's"},{"name":"Tracy Chapman","emoji":"🚗","meta":["folk","United States","since 1988"],"description":"The American singer and songwriter made her name with a searching low voice and \"Fast Car\", a song about dreaming of a way out of poverty. Her debut album became one of the great folk records of the late 1980s.","fact":"In 2023 Luke Combs's country cover of \"Fast Car\" made Tracy Chapman's song a worldwide hit all over again, thirty-five years on.","wiki_en":"Tracy Chapman","top_song":"Fast Car"},{"name":"Joan Baez","emoji":"🕊️","meta":["folk","United States","since 1958"],"description":"The American singer and songwriter was one of the central figures of the folk revival and of the civil rights movement of the 1960s. Her pure soprano and her lifelong activism made her an emblem of the era of protest song.","fact":"Joan Baez performed at the historic March on Washington in 1963, where Martin Luther King gave his \"I Have a Dream\" speech.","wiki_en":"Joan Baez","top_song":"Diamonds & Rust"},{"name":"Joni Mitchell","emoji":"🎨","meta":["folk rock","Canada","since 1964"],"description":"The Canadian singer and songwriter is one of the most influential figures in folk and rock, thanks to poetic lyrics and guitar tunings nobody else was using. Her album \"Blue\" is considered one of the greatest in the history of popular music.","fact":"Besides music, Joni Mitchell has painted seriously all her life and made the cover art for many of her own albums.","wiki_en":"Joni Mitchell","top_song":"Big Yellow Taxi"},{"name":"Carole King","emoji":"🎹","meta":["pop","United States","since 1970"],"description":"The American singer and pianist wrote dozens of hits for other performers with her husband Gerry Goffin long before her own solo career. The 1971 album \"Tapestry\" became one of the best-selling records ever made and the benchmark of singer-songwriter craft.","fact":"Before she sang herself, Carole King wrote hits such as \"Will You Love Me Tomorrow\" and \"(You Make Me Feel Like) A Natural Woman\".","wiki_en":"Carole King","top_song":"It's Too Late"},{"name":"James Taylor","emoji":"🌧️","meta":["folk rock","United States","since 1968"],"description":"The American singer-songwriter has a soft, warm voice and a beautifully worked acoustic guitar style, and was one of the leading figures in the genre in the 1970s. \"Fire and Rain\", about his own personal losses, became his calling card.","fact":"James Taylor was one of the first artists signed to Apple Records, the label founded by The Beatles.","wiki_en":"James Taylor","top_song":"Fire and Rain"},{"name":"Cat Stevens","emoji":"🌍","meta":["folk","United Kingdom","since 1966"],"description":"The British singer-songwriter wrote some of the gentlest and most searching songs of the 1970s: \"Father and Son\", \"Wild World\", \"Morning Has Broken\". In 1977 he converted to Islam, took the name Yusuf Islam and stepped away from pop music for many years.","fact":"After converting he recorded no secular songs for years, devoting himself to religious and charitable work, and only returned to music in the 2000s.","wiki_en":"Cat Stevens","top_song":"Wild World"},{"name":"Van Morrison","emoji":"👁️","meta":["rock","United Kingdom","since 1964"],"description":"The Northern Irish singer and composer brought soul, blues, folk and Celtic motifs together in one sound. \"Brown Eyed Girl\" became one of the most recognisable and most frequently played songs on radio anywhere.","fact":"The album \"Astral Weeks\", later held up as one of the greatest ever made, met with near-indifference when it came out.","wiki_en":"Van Morrison","top_song":"Brown Eyed Girl"},{"name":"Billy Ocean","emoji":"🌊","meta":["pop","United Kingdom","since 1976"],"description":"The British singer, born in Trinidad, became one of the most successful performers of danceable soul pop in the mid-1980s. The hit \"Caribbean Queen\" won him a Grammy and worldwide fame.","fact":"Billy Ocean's real name is Leslie Sebastian Charles, and he took his stage name in honour of his home island of Trinidad.","wiki_en":"Billy Ocean","top_song":"Caribbean Queen (No More Love on the Run)"},{"name":"Luther Vandross","emoji":"🎤","meta":["rhythm and blues","United States","since 1976"],"description":"The American soul singer had one of the most velvet male voices in R&B and began as a backing singer and arranger for David Bowie and other stars. \"Never Too Much\" became his first major solo hit.","fact":"Before his solo career, Luther Vandross sang backing vocals on David Bowie's album \"Young Americans\" and helped write songs on it.","wiki_en":"Luther Vandross","top_song":"Never Too Much"},{"name":"Al Green","emoji":"💚","meta":["soul","United States","since 1967"],"description":"The American soul singer has a soft, sensual voice and was one of the defining performers of the genre in the 1970s, working with the producer Willie Mitchell. He later became a pastor and combined his music career with preaching.","fact":"After a personal upheaval in the mid-1970s, Al Green became pastor of his own church in Memphis, which he leads to this day.","wiki_en":"Al Green","top_song":"Let's Stay Together"},{"name":"Otis Redding","emoji":"⚓","meta":["soul","United States","1958–1967"],"description":"The American soul singer was one of the great voices of the Stax label and the emblem of Memphis soul in the 1960s. His song \"(Sittin' On) The Dock of the Bay\" was released after he died in a plane crash and became the first posthumous number one single in history.","fact":"Otis Redding recorded \"Dock of the Bay\" only a few days before he died in a plane crash in December 1967.","wiki_en":"Otis Redding","top_song":"(Sittin' On) The Dock of the Bay"},{"name":"Wilson Pickett","emoji":"🌙","meta":["soul","United States","1959–2006"],"description":"The American soul singer had a huge, cutting voice and was one of the leading performers of Southern soul on the Stax label. The hit \"In the Midnight Hour\" became one of the great dance floor soul records of the 1960s.","fact":"Wilson Pickett's nickname, the Wicked Pickett, caught the ferocious, almost feral energy of his performances on stage.","wiki_en":"Wilson Pickett","top_song":"In the Midnight Hour"},{"name":"Sam Cooke","emoji":"🕊️","meta":["soul","United States","1957–1964"],"description":"The American singer is called the King of Soul: he was among the first to cross from gospel to secular pop and laid the foundations of the genre. His song \"A Change Is Gonna Come\" became one of the great anthems of the civil rights movement.","fact":"Sam Cooke was shot dead in unclear circumstances in 1964 at the age of 33, and \"A Change Is Gonna Come\" was released after his death.","wiki_en":"Sam Cooke","top_song":"A Change Is Gonna Come"},{"name":"The Temptations","emoji":"🎩","meta":["soul","United States","since 1960"],"description":"The American vocal group on the Motown label was known for immaculate harmonies, tightly synchronised choreography and elegant suits. Their song \"My Girl\" became one of the most recognisable soul hits of all time.","fact":"The line-up has changed dozens of times across more than half a century, yet the name and the manner of performing have stayed the same.","wiki_en":"The Temptations","top_song":"My Girl"},{"name":"The Four Tops","emoji":"✋","meta":["soul","United States","since 1953"],"description":"The American Motown vocal group was remarkable for the stability of its line-up: all four men sang together for more than four decades without a single replacement. The hit \"Reach Out I'll Be There\" was one of the summits of 1960s soul.","fact":"The original Four Tops line-up stayed unchanged for more than forty years, which was extraordinary for a vocal group of that era.","wiki_en":"Four Tops","top_song":"Reach Out I'll Be There"},{"name":"Smokey Robinson","emoji":"🎤","meta":["soul","United States","since 1955"],"description":"The American singer was one of the key writers and producers at Motown, where for years he led the group The Miracles. His songs are full of intricate metaphor and lyricism, which is why he was called the poet of soul music.","fact":"Motown's founder Berry Gordy called Smokey Robinson his chief creative adviser and made him a vice-president of the label.","wiki_en":"Smokey Robinson","top_song":"The Tears of a Clown"},{"name":"The Jackson 5","emoji":"🕺","meta":["soul","United States","1964–1990"],"description":"The American family group of the Jackson brothers came from Gary, Indiana, and had the young Michael Jackson as its lead singer. Their debut single \"I Want You Back\" went straight to the top of the charts and made them Motown stars.","fact":"All four of the group's first Motown singles went to number one on the Billboard Hot 100 in a row, which no debut act had managed before.","wiki_en":"The Jackson 5","top_song":"I Want You Back"},{"name":"Gladys Knight","emoji":"🚂","meta":["soul","United States","since 1952"],"description":"The American soul singer performed for many years with the group The Pips and earned the nickname the Empress of Soul. Her song \"Midnight Train to Georgia\", about going home after a dream falls through, became her great hit.","fact":"Gladys Knight first performed on stage at the age of four and won a children's television talent show at seven.","wiki_en":"Gladys Knight","top_song":"Midnight Train to Georgia"},{"name":"Patti LaBelle","emoji":"💋","meta":["soul","United States","since 1962"],"description":"The American soul singer has a huge multi-octave voice, began her career in the group Labelle and then built a successful solo career. The hit \"Lady Marmalade\", which features her, became one of the most recognisable soul-disco tracks of the 1970s.","fact":"Patti LaBelle is known not only for her music but for a thriving food business, a line of sauces and desserts under her own name.","wiki_en":"Patti LaBelle","top_song":"Lady Marmalade"},{"name":"Chaka Khan","emoji":"👑","meta":["funk","United States","since 1973"],"description":"The American singer is known as the Queen of Funk, first as the voice of the band Rufus and then through a successful solo career. Her song \"I'm Every Woman\" became one of the great anthems of female confidence in pop.","fact":"Whitney Houston's cover of \"I'm Every Woman\" in 1992 introduced Chaka Khan's song to a whole new generation of listeners.","wiki_en":"Chaka Khan","top_song":"I'm Every Woman"},{"name":"Kool & the Gang","emoji":"🎉","meta":["funk","United States","since 1964"],"description":"The American funk band started out with jazz experiments and became one of the great forces in dance music of the 1970s and 1980s. Their song \"Celebration\" turned into the universal anthem of every party on earth.","fact":"\"Celebration\" was played to mark the return of the American hostages from Iran in 1981 and became an unofficial anthem of celebration in the United States.","wiki_en":"Kool & the Gang","top_song":"Celebration"},{"name":"Commodores","emoji":"🎤","meta":["funk","United States","since 1968"],"description":"The American funk band that produced Lionel Richie combined dance floor funk hits with lyrical soul ballads. Their song \"Easy\" became one of the most recognisable ballads in their whole catalogue.","fact":"Before settling on Commodores, the band picked its name by opening a dictionary at random and taking what it found.","wiki_en":"Commodores","top_song":"Easy"},{"name":"Chic","emoji":"🕺","meta":["disco","United States","since 1976"],"description":"The American band of Nile Rodgers and Bernard Edwards was one of the most influential acts in the history of disco, thanks to instantly recognisable guitar riffs and bass lines. The bass line from \"Good Times\" became the foundation of the hip-hop hit \"Rapper's Delight\".","fact":"The bass part of \"Good Times\" became one of the most sampled in the history of music, and helped bring hip-hop itself into being.","wiki_en":"Chic (band)","top_song":"Good Times"},{"name":"Sister Sledge","emoji":"👯","meta":["disco","United States","since 1971"],"description":"The American group of four sisters became one of the emblems of the disco era thanks to the production of Nile Rodgers and Bernard Edwards of Chic. Their song \"We Are Family\" turned into a universal anthem of belonging.","fact":"\"We Are Family\" became the unofficial anthem of the Pittsburgh Pirates baseball team in the year they won the 1979 World Series.","wiki_en":"Sister Sledge","top_song":"We Are Family"},{"name":"KC and the Sunshine Band","emoji":"☀️","meta":["disco","United States","since 1973"],"description":"The American disco band from Florida, led by Harry Wayne Casey, gave the disco era some of its most recognisable dance floor hits. Their music was built on bright horn arrangements and Latin American rhythms.","fact":"The band's name comes from the leader's surname, Casey, shortened to KC, and from the Miami recording studio where he worked as a sound engineer.","wiki_en":"KC and the Sunshine Band","top_song":"That's the Way (I Like It)"},{"name":"Village People","emoji":"🎭","meta":["disco","United States","since 1977"],"description":"The American disco group played up a set of broad masculine characters — the cowboy, the policeman, the construction worker, the Native American chief — in fully costumed stage routines. \"Y.M.C.A.\", with its own dance, became one of the great disco anthems.","fact":"Spelling out the letters with your arms to \"Y.M.C.A.\" became one of the most recognisable mass rituals at stadiums and weddings worldwide.","wiki_en":"Village People","top_song":"Y.M.C.A."},{"name":"Gloria Gaynor","emoji":"💪","meta":["disco","United States","since 1965"],"description":"The American singer's hit \"I Will Survive\" became one of the great anthems of resilience and independence in all of pop music. The song found a second life as an emblem of the LGBT movement and of women's emancipation.","fact":"\"I Will Survive\" was originally released as the B-side to another song, and it was the B-side that unexpectedly became a worldwide hit.","wiki_en":"Gloria Gaynor","top_song":"I Will Survive"},{"name":"Boyz II Men","emoji":"🎤","meta":["rhythm and blues","United States","since 1988"],"description":"The American vocal quartet from Philadelphia became one of the most successful R&B groups of the 1990s on the strength of immaculate a cappella harmonies with no instruments at all. Their ballad \"End of the Road\" long held the record for time at the top of the American chart.","fact":"They owe their first public break to chance: they walked up to Michael Bivins of New Edition at a venue's back door and sang for him a cappella.","wiki_en":"Boyz II Men","top_song":"End of the Road"},{"name":"Salt-N-Pepa","emoji":"🧂","meta":["hip-hop","United States","since 1985"],"description":"The American female hip-hop trio was among the first to achieve mass commercial success in a genre that had been treated as strictly male. The hit \"Push It\" was one of the first rap songs ever nominated for a Grammy.","fact":"The name Salt-N-Pepa comes from the stage names of two of its members, Salt and Pepa.","wiki_en":"Salt-N-Pepa","top_song":"Push It"},{"name":"MC Hammer","emoji":"👖","meta":["hip-hop","United States","since 1986"],"description":"The American rapper was one of the first hip-hop artists to sell albums in the millions, thanks to explosive dancing and the hit \"U Can't Touch This\". His baggy parachute trousers became a fashion phenomenon in their own right.","fact":"The bass line and riff of \"U Can't Touch This\" were sampled from Rick James's \"Super Freak\", and MC Hammer later shared the songwriting credit with him.","wiki_en":"MC Hammer","top_song":"U Can't Touch This"},{"name":"Vanilla Ice","emoji":"🧊","meta":["hip-hop","United States","since 1988"],"description":"The American rapper's single \"Ice Ice Baby\" was the first hip-hop track ever to top the American Billboard Hot 100 singles chart. Using the bass line from \"Under Pressure\" by Queen and David Bowie without clearing the rights later led to a lawsuit.","fact":"Vanilla Ice long insisted that his bass line differed from \"Under Pressure\" by an extra note, though in the end he paid the writers compensation.","wiki_en":"Vanilla Ice","top_song":"Ice Ice Baby"},{"name":"Will Smith","emoji":"🕺","meta":["hip-hop","United States","since 1985"],"description":"The American rapper and actor began his music career in the duo DJ Jazzy Jeff & The Fresh Prince and then became a solo pop-rap star with bright, family-friendly hits. His song \"Gettin' Jiggy wit It\" won him a Grammy.","fact":"Will Smith and DJ Jazzy Jeff were the first ever to win the Grammy for Best Rap Performance, in 1989, for \"Parents Just Don't Understand\".","wiki_en":"Will Smith","top_song":"Gettin' Jiggy wit It"},{"name":"LL Cool J","emoji":"🥊","meta":["hip-hop","United States","since 1984"],"description":"The American rapper was one of hip-hop's first superstars and one of the first artists to sign to the legendary Def Jam label. The hit \"Mama Said Knock You Out\" became the emblem of his combative, forward-leaning delivery.","fact":"The stage name LL Cool J stands for Ladies Love Cool James.","wiki_en":"LL Cool J","top_song":"Mama Said Knock You Out"},{"name":"Public Enemy","emoji":"✊","meta":["hip-hop","United States","since 1985"],"description":"The American hip-hop group is one of the most politically charged in the history of the genre, taking on racism and social injustice head-on. \"Fight the Power\", from Spike Lee's film \"Do the Right Thing\", became one of hip-hop's great protest anthems.","fact":"The band's production team, The Bomb Squad, became famous for a dense, layered sound built from dozens of samples stacked on top of each other.","wiki_en":"Public Enemy","top_song":"Fight the Power"},{"name":"N.W.A","emoji":"🎤","meta":["gangsta rap","United States","1986–1991"],"description":"The American group from Compton stood at the very source of gangsta rap and introduced the world to Ice Cube, Dr. Dre and Eazy-E. The album \"Straight Outta Compton\" shocked listeners with unvarnished lyrics about life in poor neighbourhoods and clashes with the police.","fact":"Because of their blunt lyrics about the police, the group received a warning letter from the FBI, an extraordinary federal response to a music album.","wiki_en":"N.W.A","top_song":"Straight Outta Compton"},{"name":"Ice-T","emoji":"🎤","meta":["hip-hop","United States","since 1983"],"description":"The American rapper and actor was one of the pioneers of West Coast gangsta rap, and is also widely known for playing a detective in the series \"Law & Order: Special Victims Unit\". \"Colors\", from the film of the same name about Los Angeles gangs, is one of his signature works.","fact":"Ice-T is also the frontman of the thrash metal band Body Count, known for the scandalous song \"Cop Killer\".","wiki_en":"Ice-T","top_song":"Colors"},{"name":"Coolio","emoji":"🕶️","meta":["hip-hop","United States","since 1987"],"description":"The American rapper's great hit \"Gangsta's Paradise\", written for the film \"Dangerous Minds\", became one of the best-selling singles of the 1990s. The song is built on a Stevie Wonder sample and sets bleak lyrics against a melody nobody forgets.","fact":"\"Gangsta's Paradise\" won the Grammy for Best Solo Rap Performance and became one of the best-selling singles of the 1990s worldwide.","wiki_en":"Coolio","top_song":"Gangsta's Paradise"},{"name":"Cypress Hill","emoji":"🌿","meta":["hip-hop","United States","since 1988"],"description":"The American hip-hop group from Los Angeles was one of the first with Latin American roots to reach the mainstream, known for a nasal delivery and open advocacy of legalising marijuana. The track \"Insane in the Brain\" became one of the most recognisable hip-hop hits of the 1990s.","fact":"Cypress Hill were among the first Latin American hip-hop groups whose albums went platinum in the United States.","wiki_en":"Cypress Hill","top_song":"Insane in the Brain"},{"name":"Fugees","emoji":"🎤","meta":["hip-hop","United States","since 1992"],"description":"The American trio of Wyclef Jean, Pras and Lauryn Hill joined hip-hop to soul, reggae and Caribbean motifs. Their cover of \"Killing Me Softly with His Song\" became one of the most successful singles anywhere in 1996.","fact":"The name Fugees is short for refugees, and a nod to the Haitian roots of some of the members.","wiki_en":"Fugees","top_song":"Killing Me Softly with His Song"},{"name":"Lauryn Hill","emoji":"🎤","meta":["rhythm and blues","United States","since 1992"],"description":"The American singer and rapper, formerly of the Fugees, made one solo album, \"The Miseducation of Lauryn Hill\", which is considered one of the greatest records in the history of hip-hop and soul. The single \"Doo Wop (That Thing)\" was her biggest solo hit.","fact":"\"The Miseducation of Lauryn Hill\" was the first hip-hop album to win the Grammy for Album of the Year.","wiki_en":"Lauryn Hill","top_song":"Doo Wop (That Thing)"},{"name":"Toni Braxton","emoji":"💔","meta":["rhythm and blues","United States","since 1989"],"description":"The American R&B singer has a distinctive deep contralto and was one of the most successful ballad singers of the 1990s. \"Un-Break My Heart\" topped the American chart for weeks and won her a Grammy.","fact":"Toni Braxton has a contralto that is rare in pop, one of the lowest of all female singing voices.","wiki_en":"Toni Braxton","top_song":"Un-Break My Heart"},{"name":"Aaliyah","emoji":"🕊️","meta":["rhythm and blues","United States","1994–2001"],"description":"The American R&B singer was one of the great stars of the genre in the late 1990s, known for a restrained, elegant delivery and a style that joined R&B to electronics. She died in a plane crash in 2001 at the age of 22.","fact":"The single \"Try Again\" was the first song to reach number one on the Billboard Hot 100 with no physical release, on airplay and sales alone.","wiki_en":"Aaliyah","top_song":"Try Again"},{"name":"Mary J. Blige","emoji":"👑","meta":["rhythm and blues","United States","since 1989"],"description":"The American singer is called the Queen of Hip-Hop Soul for being among the first to put a raw R&B voice over hip-hop beats and hip-hop attitude. The hit \"Family Affair\" was one of the peaks of her career at the turn of the 2000s.","fact":"Mary J. Blige's debut album \"What's the 411?\" is considered one of the records that defined the sound of hip-hop soul.","wiki_en":"Mary J. Blige","top_song":"Family Affair"},{"name":"R. Kelly","emoji":"🎤","meta":["rhythm and blues","United States","since 1991"],"description":"The American R&B singer and producer was one of the most commercially successful artists in the genre across the 1990s and 2000s, writing both ballads and dance floor R&B hits. \"I Believe I Can Fly\", written for the film \"Space Jam\", became one of the most recognisable inspirational hits of the era.","fact":"\"I Believe I Can Fly\" won three Grammy Awards and was played at graduation ceremonies all over the world for many years.","wiki_en":"R. Kelly","top_song":"I Believe I Can Fly"},{"name":"Ashanti","emoji":"💫","meta":["rhythm and blues","United States","since 2002"],"description":"The American R&B singer broke into the charts in the early 2000s through her work with the rapper Ja Rule and the label Murder Inc. Her debut single \"Foolish\" made her one of the best-selling new artists of the year.","fact":"In 2002 Ashanti held the top spots on both the American singles and albums charts at once, a rare feat for a newcomer.","wiki_en":"Ashanti (singer)","top_song":"Foolish"},{"name":"Ja Rule","emoji":"🎤","meta":["hip-hop","United States","since 1998"],"description":"The American rapper was one of the chief hitmakers at the Murder Inc label in the early 2000s, known for a raspy voice and duets with R&B singers. The single \"Always on Time\", with Ashanti, was one of the first rap tracks to top the Billboard Hot 100.","fact":"Ja Rule's duets with Ashanti produced so many hits that in the early 2000s their joint records barely left the top of the charts.","wiki_en":"Ja Rule","top_song":"Always on Time"},{"name":"DMX","emoji":"🐕","meta":["hip-hop","United States","1991–2021"],"description":"The American rapper had a distinctive hoarse growl and a trademark dog bark in his tracks, and was one of the most successful performers of hard New York rap in the late 1990s. \"Party Up (Up in Here)\" became one of his most recognisable hits.","fact":"DMX's first five studio albums all entered the Billboard 200 at number one, a rare achievement for any rapper.","wiki_en":"DMX (rapper)","top_song":"Party Up (Up in Here)"},{"name":"Busta Rhymes","emoji":"🎤","meta":["hip-hop","United States","since 1990"],"description":"The American rapper is known for a wildly expressive, headlong delivery and for vivid videos full of science fiction imagery. He started out in the group Leaders of the New School and then built a successful solo career.","fact":"Busta Rhymes's videos in the 1990s were known for bold visual effects and were often directed by Hype Williams.","wiki_en":"Busta Rhymes","top_song":"Put Your Hands Where My Eyes Could See"},{"name":"Ludacris","emoji":"🎤","meta":["hip-hop","United States","since 1999"],"description":"The American rapper from Atlanta was one of the leading figures in Southern hip-hop in the early 2000s, and is also an actor known from the \"Fast & Furious\" franchise. He pairs a rapid-fire technique with lyrics full of jokes.","fact":"Alongside his music career, Ludacris played one of the key roles in the \"Fast & Furious\" film series.","wiki_en":"Ludacris","top_song":"Stand Up"},{"name":"T.I.","emoji":"🎤","meta":["hip-hop","United States","since 1999"],"description":"The American rapper from Atlanta calls himself the King of the South and was one of the key figures in turning Southern hip-hop into a mainstream genre. The single \"Whatever You Like\" was one of his most successful hits.","fact":"T.I. played the lead in the semi-autobiographical film \"ATL\", about young people in Atlanta.","wiki_en":"T.I.","top_song":"Whatever You Like"},{"name":"Rick Ross","emoji":"🎤","meta":["hip-hop","United States","since 2005"],"description":"The American rapper from Miami is known for a thick, booming voice and for casting himself as a crime boss in his lyrics. His debut single \"Hustlin'\" set out his signature style at once and brought him wide recognition.","fact":"The stage name Rick Ross was borrowed in part from a real convicted drug trafficker nicknamed Freeway Rick Ross, which later led to a lawsuit.","wiki_en":"Rick Ross","top_song":"Hustlin'"},{"name":"Lil Jon","emoji":"📣","meta":["hip-hop","United States","since 1993"],"description":"The American rapper and producer was one of the chief creators of crunk, the shouted, high-energy strain of Southern hip-hop. The track \"Get Low\", with its trademark yells, became one of the club anthems of the early 2000s.","fact":"Lil Jon's signature shouts of \"Yeah!\" and \"Okay!\" became so recognisable that they turned into a piece of his brand in their own right.","wiki_en":"Lil Jon","top_song":"Get Low"},{"name":"Gucci Mane","emoji":"🍋","meta":["hip-hop","United States","since 2001"],"description":"The American rapper from Atlanta is one of the most prolific artists on the trap scene and has had an enormous influence on the sound of modern Southern hip-hop. Despite dozens of mixtapes and legal trouble early on, he has kept his standing as one of the genre's central figures.","fact":"Gucci Mane has released a record number of mixtapes and albums — the count runs into dozens, making him one of the most prolific artists in hip-hop history.","wiki_en":"Gucci Mane","top_song":"Lemonade"},{"name":"Migos","emoji":"🎤","meta":["trap","United States","2008–2022"],"description":"The American trio from Atlanta — Quavo, Offset and Takeoff — did much to define the sound of modern trap and its distinctive triplet flow. The single \"Bad and Boujee\" became their first number one hit.","fact":"The Migos trademark, rapping in fast triplets, had an enormous influence on a whole generation of rappers in the 2010s.","wiki_en":"Migos","top_song":"Bad and Boujee"},{"name":"21 Savage","emoji":"🎤","meta":["hip-hop","United States","since 2014"],"description":"The American rapper is known for a bleak, flat monotone flow and terse lyrics about life on the streets of Atlanta, where almost nothing is spelled out. The single \"Bank Account\" was one of his first big solo hits.","fact":"21 Savage was born in London but grew up in Atlanta, which came to light unexpectedly in the British press years into his career.","wiki_en":"21 Savage","top_song":"Bank Account"},{"name":"Lil Baby","emoji":"🎤","meta":["hip-hop","United States","since 2017"],"description":"The American rapper from Atlanta rose faster than almost anyone on the late-2010s trap scene: only a few years passed between his first mixtape and full superstardom. His song \"The Bigger Picture\" was written in response to the protests against police violence in 2020.","fact":"Lil Baby only took up music seriously at twenty-one, an unusually late start by the standards of the modern rap scene.","wiki_en":"Lil Baby","top_song":"The Bigger Picture"},{"name":"DaBaby","emoji":"🎤","meta":["hip-hop","United States","since 2014"],"description":"The American rapper from North Carolina is known for a high-energy delivery and videos that stick in the mind. The single \"Suge\" was his breakthrough and carried him into the mainstream in 2019.","fact":"The name DaBaby comes from a childhood nickname he was given for his youthful face.","wiki_en":"DaBaby","top_song":"Suge"},{"name":"Megan Thee Stallion","emoji":"🐴","meta":["hip-hop","United States","since 2016"],"description":"The American rapper from Houston is known for a forceful delivery and confident lyrics about female independence. Her single \"Savage\", in a remix featuring Beyoncé, won her a Grammy.","fact":"Megan picked up the name Thee Stallion as a young woman, for her height and the way she carried herself.","wiki_en":"Megan Thee Stallion","top_song":"Savage"},{"name":"Stone Temple Pilots","emoji":"🎸","meta":["grunge","United States","since 1989"],"description":"The American rock band from San Diego was one of the most commercially successful acts of the early-1990s grunge and alternative wave, despite critics accusing them of copying the Seattle scene. The magnetic singer Scott Weiland made their live shows particularly hard to forget.","fact":"For all the scepticism of some critics, their debut album \"Core\" sold in the millions, and its song \"Plush\" won the band its first Grammy.","wiki_en":"Stone Temple Pilots","top_song":"Interstate Love Song"},{"name":"Soundgarden","emoji":"☀️","meta":["grunge","United States","since 1984"],"description":"The American band from Seattle was one of the founders of grunge, joining the weight of hard rock to psychedelia and the vocal range of Chris Cornell. \"Black Hole Sun\", with its surreal video, became one of the emblems of the 1990s Seattle scene.","fact":"Chris Cornell had a vocal range of more than four octaves, which was rare among rock singers of his generation.","wiki_en":"Soundgarden","top_song":"Black Hole Sun"},{"name":"Alice in Chains","emoji":"⛓️","meta":["grunge","United States","since 1987"],"description":"The American band from Seattle stood out for a particularly bleak, heavy sound and for the distinctive two-part harmonies of Layne Staley and Jerry Cantrell. \"Man in the Box\" became one of the great anthems of the early-1990s Seattle scene.","fact":"After singer Layne Staley died in 2002, the band only returned to performing several years later, with a new singer, William DuVall.","wiki_en":"Alice in Chains","top_song":"Man in the Box"},{"name":"Smashing Pumpkins","emoji":"🎃","meta":["alternative rock","United States","since 1988"],"description":"The American band from Chicago, led by Billy Corgan, joined heavy guitars to ambitious concept albums such as the double \"Mellon Collie and the Infinite Sadness\". The song \"1979\" became one of the most recognisable alternative tracks of the 1990s.","fact":"According to Billy Corgan, the name Smashing Pumpkins came out of a throwaway joke with no hidden meaning behind it.","wiki_en":"The Smashing Pumpkins","top_song":"1979"},{"name":"Weezer","emoji":"🤓","meta":["alternative rock","United States","since 1992"],"description":"The American band joined punk energy to melodic power pop and lyrics about awkwardness and not fitting in. The video for \"Buddy Holly\", cut together with scenes from the series \"Happy Days\", became one of the classic MTV videos.","fact":"The \"Buddy Holly\" video was one of the first to splice a rock band technically into archive footage from an old television show.","wiki_en":"Weezer","top_song":"Buddy Holly"},{"name":"Goo Goo Dolls","emoji":"🎸","meta":["alternative rock","United States","since 1986"],"description":"The American rock band from Buffalo found worldwide fame with the ballad \"Iris\", written for the soundtrack of the film \"City of Angels\". The song held on in the charts for months and became one of the most recognisable rock ballads of the 1990s.","fact":"\"Iris\" became one of the longest-running songs in the history of the Billboard Hot 100, staying on the chart for more than six months.","wiki_en":"Goo Goo Dolls","top_song":"Iris"},{"name":"Papa Roach","emoji":"🪳","meta":["nu metal","United States","since 1993"],"description":"The American rock band from California was one of the acts of the nu metal wave of the late 1990s. \"Last Resort\", about teenage crisis and suicidal thoughts, became their calling card and is still one of the most-streamed songs of the genre.","fact":"For all the bleakness of its lyrics, \"Last Resort\" became an unexpected mainstream hit and is still heard regularly on radio and at sporting events.","wiki_en":"Papa Roach","top_song":"Last Resort"},{"name":"Disturbed","emoji":"🎤","meta":["alternative metal","United States","since 1994"],"description":"The American metal band from Chicago is known for David Draiman's powerful voice and his trademark growled \"ooh-ah-ah-ah\". Their acoustic cover of Simon & Garfunkel's \"The Sound of Silence\" unexpectedly went viral decades after the band's debut.","fact":"The video for their cover of \"The Sound of Silence\" drew hundreds of millions of views and introduced the band to an audience that knew nothing of its metal work.","wiki_en":"Disturbed (band)","top_song":"The Sound of Silence"},{"name":"Tool","emoji":"🌀","meta":["progressive metal","United States","since 1990"],"description":"The American band joins the weight of metal to intricate polyrhythms and to visual art, including guitarist Adam Jones's work on their videos. The song \"Schism\" won the band a Grammy for Best Metal Performance.","fact":"The band is known for releasing extremely rarely: more than ten years passed between some Tool albums.","wiki_en":"Tool (band)","top_song":"Schism"},{"name":"Rage Against the Machine","emoji":"✊","meta":["rap metal","United States","since 1991"],"description":"The American band welded heavy guitar riffs to rapped vocals and a sharply left-wing politics in its lyrics. \"Killing in the Name\", with its famous closing scream, became a protest anthem for several generations.","fact":"\"Killing in the Name\" unexpectedly topped the British Christmas singles chart in 2009, thanks to a mass online campaign by fans against talent shows.","wiki_en":"Rage Against the Machine","top_song":"Killing in the Name"},{"name":"Audioslave","emoji":"🎸","meta":["alternative rock","United States","2001–2007"],"description":"The American supergroup brought Soundgarden's singer Chris Cornell together with the musicians of Rage Against the Machine after both bands broke up. The ballad \"Like a Stone\", with Cornell's searching vocal, became one of the band's defining songs.","fact":"The band came together almost by accident: the RATM musicians were looking for a new singer and invited Chris Cornell simply to try singing together.","wiki_en":"Audioslave","top_song":"Like a Stone"},{"name":"Beck","emoji":"🎸","meta":["alternative rock","United States","since 1988"],"description":"The American musician is known for eating every genre in sight, from folk and hip-hop to psychedelia and electronics, all within one career. The wry single \"Loser\", with its line \"I'm a loser, baby\", became an accidental hit and an unofficial anthem for the slacker generation of the early 1990s.","fact":"Beck recorded \"Loser\" almost by accident in a friend's home studio and expected nothing from a song he thought of as a joke.","wiki_en":"Beck","top_song":"Loser"},{"name":"Weird Al Yankovic","emoji":"🪗","meta":["comedy music","United States","since 1976"],"description":"The American musician is the great master of the musical parody, and for decades has been rebuilding the biggest pop hits into comic versions with absurd lyrics. His parody \"Eat It\", of Michael Jackson's \"Beat It\", was one of his first big successes.","fact":"Weird Al Yankovic always asks the original artists for permission personally before releasing a parody of their song.","wiki_en":"Weird Al Yankovic","top_song":"Eat It"},{"name":"Camila Cabello","emoji":"🌴","meta":["pop","United States","since 2016"],"description":"The Cuban-American singer, formerly of Fifth Harmony, built a successful solo career threading Latin American motifs through her pop. The single \"Havana\", about the city she was born in, became a worldwide number one.","fact":"In \"Havana\" Camila Cabello sings about Havana, the city she left with her family as a child.","wiki_en":"Camila Cabello","top_song":"Havana"},{"name":"Fifth Harmony","emoji":"🌟","meta":["pop","United States","2012–2018"],"description":"The American girl group was formed on \"The X Factor USA\" and became one of the most successful girl groups of the 2010s. The single \"Work from Home\" was their biggest international hit.","fact":"The group was assembled by producers literally days before the show's final, from five contestants who had each been competing alone.","wiki_en":"Fifth Harmony","top_song":"Work from Home"},{"name":"Halsey","emoji":"🎤","meta":["pop","United States","since 2014"],"description":"The American singer and songwriter is known for candid lyrics about mental health and about her own life. The single \"Without Me\" became her first solo number one in the United States.","fact":"The stage name Halsey is an anagram of her real first name, Ashley, and also the name of Halsey Street in Brooklyn.","wiki_en":"Halsey (singer)","top_song":"Without Me","wiki_ru":"Холзи"},{"name":"Charlie Puth","emoji":"🎹","meta":["pop","United States","since 2015"],"description":"The American singer and songwriter began as a musician on YouTube before finding fame with \"See You Again\", from \"Furious 7\", written in memory of the actor Paul Walker. The solo hit \"Attention\" confirmed him as a pop star in his own right.","fact":"Charlie Puth wrote and sang \"See You Again\" as a tribute to the memory of the actor Paul Walker, who had died during filming.","wiki_en":"Charlie Puth","top_song":"Attention"},{"name":"Niall Horan","emoji":"🎸","meta":["pop","Ireland","since 2016"],"description":"The Irish singer-songwriter, formerly of One Direction, built a solo career in a softer pop-rock register, writing warm, guitar-led songs of his own. The single \"Slow Hands\" became his first major solo hit.","fact":"Niall Horan is the only member of One Direction from Ireland; the rest of the band were British.","wiki_en":"Niall Horan","top_song":"Slow Hands"},{"name":"Jonas Brothers","emoji":"👬","meta":["pop rock","United States","since 2005"],"description":"The American trio of Jonas brothers started as a teen pop-rock band on the Disney Channel and then reunited, after years apart, as grown-up artists. Their 2019 single \"Sucker\" marked a triumphant return to the top of the charts.","fact":"After breaking up in 2013 the Jonas brothers did not speak for several years and only came back together for music after a long rift.","wiki_en":"Jonas Brothers","top_song":"Sucker"},{"name":"Demi Lovato","emoji":"🎤","meta":["pop","United States","since 2008"],"description":"The American singer and actress started out on the Disney Channel and then built a solo career on a huge voice and unsparing lyrics about her own struggles. The single \"Sorry Not Sorry\" became one of her biggest pop hits.","fact":"Demi Lovato speaks openly about her mental health struggles, which has made her one of the more prominent voices on the subject in the pop industry.","wiki_en":"Demi Lovato","top_song":"Sorry Not Sorry"},{"name":"Meghan Trainor","emoji":"🎤","meta":["pop","United States","since 2014"],"description":"The American singer broke into the charts with her debut single \"All About That Bass\", a cheerful retro-pop anthem about accepting your own body. The song went straight to the top of the American chart and became one of the great pop hits of 2014.","fact":"Meghan Trainor wrote \"All About That Bass\" in about an hour, and it was originally intended for another performer.","wiki_en":"Meghan Trainor","top_song":"All About That Bass"},{"name":"Kesha","emoji":"🕺","meta":["pop","United States","since 2009"],"description":"The American singer arrived with a brash dance-pop sound and an image built entirely on parties without rules. Her debut single \"Tik Tok\" set a digital sales record and topped charts around the world.","fact":"\"Tik Tok\" long held the record for digital sales in a single week by a debut single.","wiki_en":"Kesha","top_song":"Tik Tok"},{"name":"Carly Rae Jepsen","emoji":"📞","meta":["pop","Canada","since 2007"],"description":"The Canadian singer became a star almost overnight with \"Call Me Maybe\", one of the most viral pop hits of the early 2010s. Although the wider public thinks of her as a one-hit artist, she has kept releasing music that critics hold in high regard.","fact":"\"Call Me Maybe\" owes much of its success to a tweet by Justin Bieber recommending the song to his millions of followers.","wiki_en":"Carly Rae Jepsen","top_song":"Call Me Maybe"},{"name":"Charli XCX","emoji":"💚","meta":["pop","United Kingdom","since 2008"],"description":"The British singer and songwriter joins mainstream pop to an experimental hyperpop sound. The single \"Boom Clap\", from the soundtrack of \"The Fault in Our Stars\", became one of her most recognisable hits.","fact":"The 2024 album \"Brat\" and its acid-green cover turned into a full-scale cultural meme and an aesthetic in their own right, brat summer.","wiki_en":"Charli XCX","top_song":"Boom Clap"},{"name":"Florence and the Machine","emoji":"🎤","meta":["indie rock","United Kingdom","since 2007"],"description":"Florence Welch's British project joins indie rock to baroque pop, a huge voice and an almost mystical energy on stage. The single \"Dog Days Are Over\" became her calling card and one of the most recognisable songs of the late-2000s indie scene.","fact":"Florence Welch is known for performing barefoot: she often kicks off her shoes on stage.","wiki_en":"Florence and the Machine","top_song":"Dog Days Are Over"},{"name":"Mumford & Sons","emoji":"🪕","meta":["folk rock","United Kingdom","since 2007"],"description":"The British band did much to bring acoustic folk rock, with banjos and full-throated backing vocals, back into fashion at the end of the 2000s. The single \"I Will Wait\" and the album \"Babel\" won them the Grammy for Album of the Year.","fact":"The banjo that became the band's signature sound is played by Winston Marshall, who had almost no folk background before.","wiki_en":"Mumford & Sons","top_song":"I Will Wait"},{"name":"MGMT","emoji":"🎈","meta":["indie pop","United States","since 2002"],"description":"The American duo joined psychedelic electronics to bright synth-pop melodies and became an unlikely star of the second half of the 2000s. The singles \"Kids\" and \"Electric Feel\" turned into anthems of their moment, though the musicians themselves later avoided repeating that sound.","fact":"After the overwhelming success of their debut album, MGMT deliberately moved towards something more experimental, refusing to repeat the formula of \"Kids\".","wiki_en":"MGMT","top_song":"Kids"},{"name":"The 1975","emoji":"🖤","meta":["pop rock","United Kingdom","since 2002"],"description":"The British band from Manchester is known for a stylish, carefully designed sound sitting between pop rock, synth-pop and emo, and for the striking visual identity of their albums. The single \"Girls\" was one of the first big hits to carry them into the mainstream.","fact":"Matt Healy found the name The 1975 in an old book about the Beat writers, where someone had written the date in by hand.","wiki_en":"The 1975","top_song":"Girls"},{"name":"Fun.","emoji":"🎉","meta":["indie pop","United States","2008–2015"],"description":"The American band brought together members of The Format and Steel Train and became superstars almost overnight with the single \"We Are Young\", featuring Janelle Monáe. The song topped charts around the world and won the band a Grammy.","fact":"\"We Are Young\" became a hit largely thanks to its use in a Chevrolet commercial during the Super Bowl broadcast.","wiki_en":"Fun (band)","top_song":"We Are Young"},{"name":"Jason Mraz","emoji":"☀️","meta":["pop","United States","since 1999"],"description":"The American singer-songwriter is known for a sunny acoustic sound and easy summer hits. The single \"I'm Yours\" held on in the charts for months and became one of the longest-running songs in the history of the Billboard Hot 100.","fact":"\"I'm Yours\" set the record for the longest run on the Billboard Hot 100 of any single up to that point.","wiki_en":"Jason Mraz","top_song":"I'm Yours"},{"name":"Train","emoji":"🚂","meta":["pop rock","United States","since 1993"],"description":"The American rock band from San Francisco is known for melodic pop-rock hits carried by a ukulele and an incurably cheerful mood. The single \"Hey, Soul Sister\" became one of the best-selling digital singles of the late 2000s.","fact":"\"Hey, Soul Sister\" spent a long time as one of the best-selling digital singles in the history of iTunes.","wiki_en":"Train (band)","top_song":"Hey, Soul Sister"},{"name":"Garth Brooks","emoji":"🤠","meta":["country","United States","since 1987"],"description":"The American country singer is one of the best-selling solo artists in American music history, and joined country to the trappings of a rock show and vast stadium tours. The song \"Friends in Low Places\" became one of the genre's great anthems.","fact":"By total album sales in the United States, some counts put Garth Brooks second only to The Beatles among all recording artists.","wiki_en":"Garth Brooks","top_song":"Friends in Low Places"},{"name":"Kenny Rogers","emoji":"🎰","meta":["country","United States","1957–2017"],"description":"The American country singer, with his unmistakable low voice and white beard, was one of the most commercially successful performers in the genre and crossed easily between country and pop. \"The Gambler\", with its philosophical refrain about when to hold and when to fold, became his calling card.","fact":"Several television films were made based on the song \"The Gambler\", with Kenny Rogers himself in the lead role.","wiki_en":"Kenny Rogers","top_song":"The Gambler"},{"name":"Willie Nelson","emoji":"🎸","meta":["country","United States","since 1956"],"description":"The American country singer and songwriter was one of the founders of outlaw country, a movement set against the glossy Nashville sound. Beyond music he is known for decades of activism in support of farmers through the Farm Aid festival.","fact":"Willie Nelson co-founded the annual Farm Aid benefit festival in support of American farmers, together with Neil Young and John Mellencamp.","wiki_en":"Willie Nelson","top_song":"On the Road Again"},{"name":"Reba McEntire","emoji":"👑","meta":["country","United States","since 1975"],"description":"The American country singer and actress is called the Queen of Country for a long and remarkably steady career in the genre. Her cover of \"Fancy\", about a girl who claws her way out of poverty, became one of her best-known hits.","fact":"Besides music, Reba McEntire has had a successful career in film and television, including her own sitcom \"Reba\".","wiki_en":"Reba McEntire","top_song":"Fancy"},{"name":"Blake Shelton","emoji":"🤠","meta":["country","United States","since 2001"],"description":"The American country singer became widely known not only for his music but as a long-serving coach on the television show \"The Voice\". The single \"God's Country\" was one of his most successful hits.","fact":"Blake Shelton was one of the fixed coaches on the American show \"The Voice\" for more than twenty seasons in a row.","wiki_en":"Blake Shelton","top_song":"God's Country"},{"name":"Carrie Underwood","emoji":"🔨","meta":["country","United States","since 2005"],"description":"The American country singer won the television show \"American Idol\" and became one of the most successful performers in the genre. The hit \"Before He Cheats\", about taking revenge on a cheating boyfriend, became one of the defining country songs of the 2000s.","fact":"Carrie Underwood won the fourth season of \"American Idol\" in 2005 and became a country star almost immediately afterwards.","wiki_en":"Carrie Underwood","top_song":"Before He Cheats"},{"name":"Keith Urban","emoji":"🎸","meta":["country","Australia","since 1991"],"description":"The Australian country singer and virtuoso guitarist built a successful career in Nashville, joining traditional country to elements of pop and rock. The ballad \"Blue Ain't Your Color\" became one of his most successful singles.","fact":"Keith Urban is considered one of the finest country guitarists of his generation and regularly plays demanding solos live in stadiums.","wiki_en":"Keith Urban","top_song":"Blue Ain't Your Color"},{"name":"Luke Bryan","emoji":"🤠","meta":["country","United States","since 2007"],"description":"The American country singer is one of the leading figures in the bro-country subgenre, with danceable hits about parties and country living. The single \"Country Girl (Shake It for Me)\" became one of his most recognisable tracks.","fact":"Luke Bryan spent several years in a row as one of the judges on the music television show \"American Idol\".","wiki_en":"Luke Bryan","top_song":"Country Girl (Shake It for Me)"},{"name":"Tim McGraw","emoji":"🤠","meta":["country","United States","since 1990"],"description":"The American country singer and actor was one of the most decorated performers in the genre across the 1990s and 2000s, and often sings in duet with his wife Faith Hill. \"Live Like You Were Dying\", about rethinking your life in the face of death, became one of the most affecting songs of his career.","fact":"Tim McGraw and his wife Faith Hill are considered one of the most successful married couples in the history of country music.","wiki_en":"Tim McGraw","top_song":"Live Like You Were Dying"},{"name":"Faith Hill","emoji":"🎤","meta":["country","United States","since 1993"],"description":"The American country singer was one of the most successful performers in the genre in the 1990s, and her songs frequently crossed the line between country and pop. The ballad \"Breathe\" became one of the best-selling country hits of the decade.","fact":"Faith Hill recorded several duets with her husband Tim McGraw, including the Grammy-winning hit \"Let's Make Love\".","wiki_en":"Faith Hill","top_song":"Breathe"},{"name":"Kacey Musgraves","emoji":"🌈","meta":["country","United States","since 2012"],"description":"The American country singer is known for liberal lyrics unusual in the genre and for a soft psychedelic sound sitting between country and pop. The album \"Golden Hour\" won her the Grammy for Album of the Year.","fact":"\"Follow Your Arrow\", urging listeners to be themselves and not fear judgement, was an unexpectedly bold statement for the conservative country scene.","wiki_en":"Kacey Musgraves","top_song":"Follow Your Arrow"},{"name":"Chris Stapleton","emoji":"🥃","meta":["country","United States","since 2001"],"description":"The American country singer has a huge bluesy voice and spent years writing hits for other Nashville performers before his own solo career. His cover of \"Tennessee Whiskey\" became his calling card and one of the great country hits of the 2010s.","fact":"Before becoming a solo artist, Chris Stapleton wrote dozens of songs for others, including hits for Kenny Chesney and George Strait.","wiki_en":"Chris Stapleton","top_song":"Tennessee Whiskey"},{"name":"The Chicks","emoji":"🎻","meta":["country","United States","since 1989"],"description":"The American trio is one of the most successful acts in the history of country music, known for virtuoso fiddle and banjo playing and for the independence of their lyrics. \"Wide Open Spaces\", about growing up and striking out alone, became one of the group's great hits.","fact":"The group changed its name from Dixie Chicks to The Chicks in 2020, dropping a word with historical associations to the slaveholding South.","wiki_en":"The Chicks","top_song":"Wide Open Spaces"},{"name":"Toby Keith","emoji":"🤠","meta":["country","United States","1993–2024"],"description":"The American country singer had a cowboy image and patriotic themes running through his songs, and was one of the most commercially successful performers in the genre around the turn of the 2000s. His debut hit \"Should've Been a Cowboy\" became one of the most played country songs of the decade.","fact":"\"Should've Been a Cowboy\" was long considered one of the most frequently broadcast country songs on radio in the 1990s.","wiki_en":"Toby Keith","top_song":"Should've Been a Cowboy"},{"name":"Alan Jackson","emoji":"🤠","meta":["country","United States","since 1989"],"description":"The American country singer is one of the leading figures of the traditional neo-Nashville sound, set against the pop country of the 1990s. \"Chattahoochee\", about growing up beside the river of the same name, became one of his most recognisable hits.","fact":"Alan Jackson wrote \"Where Were You (When the World Stopped Turning)\" about the events of 11 September 2001, only weeks after the attacks.","wiki_en":"Alan Jackson","top_song":"Chattahoochee"},{"name":"George Strait","emoji":"🤠","meta":["country","United States","since 1975"],"description":"The American country singer is called the King of Country for an enormous run of number one hits and an unbroken loyalty to the traditional Texas sound. The ballad \"Amarillo by Morning\", about life as a rodeo cowboy, is considered one of his most piercing songs.","fact":"George Strait holds the record for the most number one country singles of any artist in the history of the genre.","wiki_en":"George Strait","top_song":"Amarillo by Morning"},{"name":"Kenny Chesney","emoji":"🏖️","meta":["country","United States","since 1989"],"description":"The American country singer is known for a relaxed beach sound and lyrics about easy living by the sea, which is why he is counted among the leading figures of beach country. The ballad \"There Goes My Life\", about unexpected fatherhood, is one of the most affecting songs of his career.","fact":"Kenny Chesney draws some of the largest stadium crowds in country music, through his No Shoes Nation tours.","wiki_en":"Kenny Chesney","top_song":"There Goes My Life"},{"name":"Miranda Lambert","emoji":"🏠","meta":["country","United States","since 2001"],"description":"The American country singer is one of the most decorated performers in the genre, known for fearless lyrics and a rock charge in the way she sings. The ballad \"The House That Built Me\", about going back to a childhood home, became her most personal and most acclaimed hit.","fact":"\"The House That Built Me\" won Miranda Lambert a Grammy and is considered one of the finest country ballads of the twenty-first century.","wiki_en":"Miranda Lambert","top_song":"The House That Built Me"},{"name":"Morgan Wallen","emoji":"🤠","meta":["country","United States","since 2015"],"description":"The American country singer is one of the most-streamed performers in the genre today, joining traditional country to elements of hip-hop and pop. The single \"Last Night\" became one of the most successful country hits in the history of the charts.","fact":"\"Last Night\" spent sixteen weeks at number one on the all-genre Billboard Hot 100, one of the longest runs ever for a country hit.","wiki_en":"Morgan Wallen","top_song":"Last Night"},{"name":"Duke Ellington","emoji":"🎹","meta":["jazz","United States","1917–1974"],"description":"The American jazz composer, pianist and bandleader was one of the most influential musicians of the twentieth century and raised big band jazz to the standing of serious art. \"Take the 'A' Train\", written by his collaborator Billy Strayhorn, became his orchestra's signature tune.","fact":"From 1927 to 1931 Duke Ellington's orchestra was the house band at Harlem's legendary Cotton Club, and its performances were broadcast nationwide on radio.","wiki_en":"Duke Ellington","top_song":"Take the 'A' Train"},{"name":"Count Basie","emoji":"🎹","meta":["jazz","United States","1935–1984"],"description":"The American jazz pianist and bandleader had an orchestra famous for a particularly powerful and springy swing rhythm section. \"One O'Clock Jump\" became the unofficial signature tune of his big band.","fact":"Basie got the nickname Count from a radio DJ who tacked it onto his ordinary surname as a joke.","wiki_en":"Count Basie","top_song":"One O'Clock Jump"},{"name":"Charlie Parker","emoji":"🎷","meta":["jazz","United States","1937–1955"],"description":"The American jazz saxophonist was one of the chief creators of bebop, the style that remade jazz in the middle of the twentieth century with its headlong improvising technique. \"Now's the Time\" became one of the textbook examples of that new sound.","fact":"The nickname Bird stuck to Charlie Parker for life, and the New York jazz club Birdland was later named in his honour.","wiki_en":"Charlie Parker","top_song":"Now's the Time"},{"name":"John Coltrane","emoji":"🎷","meta":["jazz","United States","1945–1967"],"description":"The American jazz saxophonist was one of the most influential musicians in the history of the genre, known for his spiritual searching and a headlong improvising technique. His soprano saxophone version of \"My Favorite Things\" became one of the most recognisable recordings in jazz.","fact":"Coltrane's album \"A Love Supreme\" was made as a musical expression of a profound spiritual reckoning and is still counted among the greatest jazz albums.","wiki_en":"John Coltrane","top_song":"My Favorite Things"},{"name":"Dizzy Gillespie","emoji":"🎺","meta":["jazz","United States","1935–1993"],"description":"The American jazz trumpeter and co-founder of bebop was instantly recognisable by his ballooning cheeks and his distinctive bent trumpet. \"A Night in Tunisia\" became a jazz standard bound firmly to his name.","fact":"The bent bell of Dizzy Gillespie's trumpet, which became his trademark, happened by accident: the instrument was damaged at a party and he liked the new sound.","wiki_en":"Dizzy Gillespie","top_song":"A Night in Tunisia"},{"name":"Billie Holiday","emoji":"🌸","meta":["jazz","United States","1929–1959"],"description":"The American jazz singer had an inimitable sense of phrasing and a piercing emotional directness, and is one of the most influential vocalists in the history of music. \"Strange Fruit\", about the lynchings of the American South, was one of the first open musical statements against racism.","fact":"Billie Holiday performed with a fresh gardenia in her hair, and the image became one of the most recognisable details of her stage presence.","wiki_en":"Billie Holiday","top_song":"Strange Fruit"},{"name":"Herbie Hancock","emoji":"🎹","meta":["jazz","United States","since 1960"],"description":"The American jazz pianist and composer played in Miles Davis's classic quintet and later experimented boldly with funk, electronics and hip-hop. The instrumental \"Rockit\", with its trademark scratching, became one of the first jazz hits on MTV.","fact":"The video for \"Rockit\", with its dancing mechanical mannequins, won several MTV Video Music Awards and became a defining visual image of the era.","wiki_en":"Herbie Hancock","top_song":"Rockit"},{"name":"Kid Cudi","emoji":"🌙","meta":["hip-hop","United States","since 2003"],"description":"The American rapper and singer was one of the first artists to join hip-hop to a melancholy, almost psychedelic mood and to themes of anxiety and loneliness. His debut hit \"Day 'n' Nite\", with its hypnotic beat, became one of the most recognisable tracks of the late 2000s.","fact":"Kid Cudi often uses the Man on the Moon figure as a creative alter ego, and it gives several of his albums their titles.","wiki_en":"Kid Cudi","top_song":"Day 'n' Nite"},{"name":"Chance the Rapper","emoji":"🧢","meta":["hip-hop","United States","since 2011"],"description":"The Chicago rapper made his name with independent mixtapes he gave away free, bypassing the major labels entirely. His album \"Coloring Book\" won the Grammy for Best Rap Album, a rare thing for a streaming-only release. He blends rap with gospel motifs and jazz arrangements.","fact":"Chance the Rapper never signed to a major label, staying independent even at the height of his career.","wiki_en":"Chance the Rapper","top_song":"No Problem"},{"name":"Mac Miller","emoji":"🎧","meta":["hip-hop","United States","1992–2018"],"description":"The rapper and producer from Pittsburgh started with playful, melodic mixtapes and moved gradually towards far more personal and melancholy music. His album \"Swimming\" became one of hip-hop's most piercing statements about depression and the struggle with addiction. He died at twenty-six.","fact":"He chose the name Mac Miller as a teenager; his real name was Malcolm McCormick.","wiki_en":"Mac Miller","top_song":"Self Care"},{"name":"A$AP Rocky","emoji":"🕶️","meta":["hip-hop","United States","since 2011"],"description":"The rapper from Harlem leads the A$AP Mob collective and is known for a melancholy, cloud-like sound and a serious eye for fashion: he is one of very few rappers to become the face of major fashion houses. The debut album \"Long.Live.A$AP\" fixed him as one of the great stylists of New York rap.","fact":"The name A$AP stands for Always Strive And Prosper, the motto of the A$AP Mob collective.","wiki_en":"ASAP Rocky","top_song":"Praise the Lord (Da Shine)"},{"name":"Gloria Estefan","emoji":"💃","meta":["pop","United States","since 1975"],"description":"The Cuban-American singer, together with Miami Sound Machine, turned Latin rhythms into worldwide pop hits in the 1980s. After a serious road accident in 1990 she managed to return to the stage and carried on as a solo artist. She was among the first to bring Latin American sound onto American radio on that scale.","fact":"After breaking her back in the 1990 crash, doctors doubted Estefan would walk again, yet she was back performing within a year.","wiki_en":"Gloria Estefan","top_song":"Conga"},{"name":"Julio Iglesias","emoji":"🌹","meta":["pop","Spain","since 1968"],"description":"The Spanish singer is one of the best-selling performers in the history of Latin and European popular song, and sings in several languages. He began as a football goalkeeper and turned to music after a bad car crash. His velvet voice made the romantic ballad the calling card of Spanish-language pop.","fact":"He is the father of Enrique Iglesias, who early in his career kept quiet about being related to his famous father.","wiki_en":"Julio Iglesias","top_song":"Begin the Beguine"},{"name":"Selena","emoji":"👑","meta":["Tejano / pop","United States","1971–1995"],"description":"The American singer of Mexican descent was crowned the Queen of Tejano music for carrying Latin rhythms into the English-language market. Her album \"Dreaming of You\" was released after she was killed and became one of the most successful Latin pop releases ever. Her life story became a biographical film starring Jennifer Lopez.","fact":"Selena was shot dead by the president of her own fan club, an event that shook the entire Latin American music industry.","wiki_en":"Selena","top_song":"Como la Flor"},{"name":"Arcade Fire","emoji":"🔥","meta":["indie rock","Canada","since 2001"],"description":"The Canadian indie rock band from Montreal became famous for an orchestral scale of sound and emotionally overwhelming concerts. The debut album \"Funeral\" made them one of the most influential indie acts of the 2000s, and \"The Suburbs\" won the Grammy for Album of the Year. On stage the band can run to a dozen musicians at once.","fact":"The name refers to a story the musicians once heard about a fire in an amusement arcade, though they will not confirm that it was true.","wiki_en":"Arcade Fire","top_song":"Wake Up"},{"name":"Stormzy","emoji":"🌩️","meta":["grime","United Kingdom","since 2014"],"description":"The British rapper is one of the central figures of the London grime scene, and his debut album \"Gang Signs & Prayer\" topped the British chart. His headline set at Glastonbury in 2019, played in a Union Jack stab vest designed by Banksy, became one of the emblems of British music in the late 2010s.","fact":"Stormzy founded a scholarship for Black British students at the University of Cambridge, paying their fees out of his own money.","wiki_en":"Stormzy","top_song":"Vossi Bop"},{"name":"Jessie J","emoji":"💫","meta":["pop","United Kingdom","since 2010"],"description":"The British pop singer has a huge voice and began as a songwriter for other artists before releasing her own hit \"Price Tag\". She is known for collaborations such as \"Bang Bang\" with Ariana Grande and Nicki Minaj, and for her stint as a coach on \"The Voice\".","fact":"Miley Cyrus's hit \"Party in the U.S.A.\" was written by Jessie J, before she had begun releasing songs under her own name.","wiki_en":"Jessie J","top_song":"Bang Bang"},{"name":"Leona Lewis","emoji":"💔","meta":["pop","United Kingdom","since 2006"],"description":"The British singer won \"The X Factor\" in 2006 and turned into a global star almost immediately with the single \"Bleeding Love\". She has a wide vocal range that shows to best effect in ballads.","fact":"\"Bleeding Love\" topped the charts in many countries, Britain and the United States among them, a rare success for a talent show winner.","wiki_en":"Leona Lewis","top_song":"Bleeding Love"},{"name":"Take That","emoji":"🕺","meta":["pop","United Kingdom","since 1990"],"description":"The British pop group is one of the most successful boy bands in British music history, with Gary Barlow and Robbie Williams in the early line-up. After breaking up in 1996 and losing Williams, the band returned triumphantly in 2006 as a quartet and topped the charts all over again.","fact":"Robbie Williams's departure in 1995 was taken at the time as the end of Take That, yet the band came back even more successful.","wiki_en":"Take That","top_song":"Back for Good"},{"name":"Westlife","emoji":"💙","meta":["pop","Ireland","since 1998"],"description":"The Irish pop group became one of the most successful boy bands at the turn of the 2000s with sentimental ballads and close harmony singing. Their singles topped the British charts again and again, and the group was put together under the wing of Louis Walsh, the manager behind Boyzone.","fact":"Westlife set the record among groups of their era for the most singles entering the British chart straight at number one.","wiki_en":"Westlife","top_song":"Flying Without Wings"},{"name":"S Club 7","emoji":"🎉","meta":["pop","United Kingdom","1998–2003"],"description":"The British pop group of seven was created for its own television series and quickly became one of the great teenage phenomena of the late 1990s. Their sunny hits, such as \"Reach\" and \"Never Had a Dream Come True\", came with bright television shows and a feature film.","fact":"S Club 7 produced Rachel Stevens, who went on to a successful solo career after the group broke up.","wiki_en":"S Club 7","top_song":"Reach"},{"name":"Little Mix","emoji":"💗","meta":["pop","United Kingdom","2011–2022"],"description":"The British girl group won \"The X Factor\" in 2011, the first act to win the show as a group rather than a soloist. They became one of the most successful girl groups of the 2010s, with songs about female solidarity and self-belief, before going on hiatus in 2022.","fact":"Little Mix were the first female group to win the Brit Award for Best British Group.","wiki_en":"Little Mix","top_song":"Shout Out to My Ex"},{"name":"Snow Patrol","emoji":"❄️","meta":["indie rock","United Kingdom","since 1994"],"description":"The rock band from Northern Ireland and Scotland made its name with atmospheric guitar ballads. Their single \"Chasing Cars\" became one of the most recognisable songs of the 2000s and was used constantly in film and television, including a finale of \"Grey's Anatomy\".","fact":"\"Chasing Cars\" has for years remained one of the most played songs on British radio in the entire history of the charts.","wiki_en":"Snow Patrol","top_song":"Chasing Cars"},{"name":"Deadmau5","emoji":"🐭","meta":["electronic","Canada","since 2005"],"description":"The Canadian electronic producer performs in an enormous glowing helmet with mouse ears, which became his visual calling card. He is one of the pioneers of progressive house, and is also known for a long legal fight with Disney over a similar mouse logo.","fact":"Deadmau5 spent years in litigation with Disney, which considered his mouse logo too close to the company's own imagery.","wiki_en":"Deadmau5","top_song":"Ghosts 'n' Stuff"},{"name":"Armin van Buuren","emoji":"🎧","meta":["trance","Netherlands","since 1995"],"description":"The Dutch DJ and producer is one of the leading figures of trance and the long-serving host of the radio show \"A State of Trance\", heard by millions around the world. He has been named the world's number one DJ several times in the DJ Mag poll.","fact":"Armin van Buuren's radio show \"A State of Trance\" has gone out every week for more than twenty years in a row.","wiki_en":"Armin van Buuren","top_song":"This Is What It Feels Like"},{"name":"Martin Garrix","emoji":"🎚️","meta":["electronic","Netherlands","since 2012"],"description":"The Dutch DJ and producer became famous while still a teenager with the hit \"Animals\", one of the defining festival tracks of its time. He is one of the youngest artists ever to top the poll of the world's best DJs.","fact":"Martin Garrix wrote and released \"Animals\" when he was only seventeen years old.","wiki_en":"Martin Garrix","top_song":"Animals"},{"name":"Zedd","emoji":"⚡","meta":["electronic","Germany","since 2009"],"description":"The German DJ and producer of Russian origin won a Grammy for the single \"Clarity\", one of the defining tracks of the early-2010s EDM wave. He is known for collaborations with pop stars such as Ariana Grande and Selena Gomez.","fact":"Zedd's real name is Anton Zaslavski: he was born in Saratov, grew up in Germany and started out as a musician in a rock band.","wiki_en":"Zedd","top_song":"Clarity"},{"name":"Steve Aoki","emoji":"🍰","meta":["electronic","United States","since 1996"],"description":"The American DJ and producer is known not only for his electro house tracks but for a trademark stage habit of throwing cakes into the crowd mid-set. He founded the influential indie label Dim Mak before his DJ career had even begun.","fact":"Steve Aoki is the son of Rocky Aoki, the founder of the international Japanese restaurant chain Benihana.","wiki_en":"Steve Aoki","top_song":"Delirious (Boneless)"},{"name":"Diplo","emoji":"🌴","meta":["electronic","United States","since 2004"],"description":"The American producer and DJ is the man behind Major Lazer and a long list of pop hits for other artists. He mixes electronics with dancehall, reggae and global rhythms, and has produced tracks for Beyoncé, Madonna and Justin Bieber.","fact":"Diplo is one of the founders of Major Lazer, whose cartoon commando character became the group's recognisable logo.","wiki_en":"Diplo","top_song":"Where Are Ü Now"},{"name":"DJ Snake","emoji":"🐍","meta":["electronic","France","since 2010"],"description":"The French DJ and producer broke into the world charts with \"Lean On\", made with Major Lazer and the singer MØ, which became one of the most-watched videos on YouTube. He was born and grew up in the Paris suburbs, in a family of Algerian descent.","fact":"DJ Snake's first major hit was \"Turn Down for What\" with the rapper Lil Jon, before \"Lean On\" ever came out.","wiki_en":"DJ Snake","top_song":"Lean On"},{"name":"Alan Walker","emoji":"🌫️","meta":["electronic","Norway","since 2012"],"description":"The Norwegian DJ and producer performs in a trademark hood that hides his face, which became part of his stage persona. He found worldwide fame with the track \"Faded\", one of the most-streamed pieces of electronic music on YouTube.","fact":"Alan Walker almost always appears in public in a hood, deliberately keeping his face less recognisable than his music.","wiki_en":"Alan Walker","top_song":"Faded"},{"name":"The Chainsmokers","emoji":"🎛️","meta":["electronic","United States","since 2012"],"description":"The American DJ duo began with viral tracks such as \"#Selfie\" but truly broke through with \"Closer\", one of the most successful singles of the mid-2010s, which joined EDM to pop. The duo often sets electronic beats against live vocals and rock elements.","fact":"\"Closer\" held the top of the Billboard Hot 100 for several weeks in a row in the summer of 2016.","wiki_en":"The Chainsmokers","top_song":"Closer"},{"name":"Neil Diamond","emoji":"💎","meta":["pop rock","United States","since 1962"],"description":"The American singer and songwriter had a baritone and a set of driving ballads that made him one of the most recognisable figures in 1970s pop. His \"Sweet Caroline\" turned into an unofficial sporting anthem that crowds still sing en masse in stadiums.","fact":"\"Sweet Caroline\" became so popular at sports grounds that it is called the unofficial anthem of the Boston Red Sox.","wiki_en":"Neil Diamond","top_song":"Sweet Caroline"},{"name":"Tom Jones","emoji":"🎩","meta":["pop","Wales","since 1963"],"description":"The Welsh singer has a huge baritone and became a star back in the 1960s with hits such as \"It's Not Unusual\" and the title song of the Bond film \"Thunderball\". He is known for magnetic live shows, at which fans traditionally threw underwear onto the stage.","fact":"Tom Jones sang the title song of the James Bond film \"Thunderball\", though he admitted he nearly passed out holding the final note.","wiki_en":"Tom Jones (singer)","top_song":"It's Not Unusual"},{"name":"The Everly Brothers","emoji":"🎸","meta":["rock and roll","United States","1957–2005"],"description":"The American vocal duo of brothers Don and Phil Everly sang in a close two-part harmony that shaped The Beatles and dozens of other bands. Hits such as \"Bye Bye Love\" and \"Wake Up Little Susie\" became classics of early rock and roll.","fact":"Paul McCartney and John Lennon repeatedly named the Everly Brothers' harmonies as one of the main inspirations behind early Beatles songs.","wiki_en":"The Everly Brothers","top_song":"Bye Bye Love"},{"name":"Roy Orbison","emoji":"🕶️","meta":["rock and roll","United States","1956–1988"],"description":"The American singer had a singular operatic tenor and trademark dark glasses, and wrote the ballads \"Oh, Pretty Woman\" and \"Crying\". At the end of the 1980s he enjoyed a full creative revival in the supergroup Traveling Wilburys, alongside Bob Dylan and George Harrison.","fact":"Roy Orbison started wearing the dark glasses that became his trademark because of poor eyesight, after forgetting his ordinary pair before a show.","wiki_en":"Roy Orbison","top_song":"Oh, Pretty Woman"},{"name":"Buddy Holly","emoji":"🤓","meta":["rock and roll","United States","1956–1959"],"description":"The American musician was one of the pioneers of rock and roll and shaped The Beatles and The Rolling Stones in a career that lasted barely two years. He died in a plane crash in February 1959 together with Ritchie Valens and The Big Bopper, a date remembered as the day the music died.","fact":"The phrase \"the day the music died\", from Don McLean's \"American Pie\", refers to the death of Buddy Holly.","wiki_en":"Buddy Holly","top_song":"That'll Be the Day"},{"name":"Little Richard","emoji":"🎹","meta":["rock and roll","United States","1947–2020"],"description":"The American singer and pianist was one of the chief architects of rock and roll, and the frenzied voice and sheer energy of \"Tutti Frutti\" set the tone for an entire genre. His stage eccentricity and his image shaped artists from James Brown to Prince.","fact":"The lyrics of \"Tutti Frutti\" had to be rewritten before recording: the original words were far too explicit for 1950s radio.","wiki_en":"Little Richard","top_song":"Tutti Frutti"},{"name":"Fats Domino","emoji":"🎹","meta":["rock and roll","United States","1949–2017"],"description":"The American pianist and singer from New Orleans was one of the best-selling artists of early rock and roll, alongside Elvis Presley. His distinctive boogie-woogie piano and soft voice are there in \"Blueberry Hill\", a classic of the genre.","fact":"Fats Domino refused to leave New Orleans, and after Hurricane Katrina he was rescued from his flooded house in the Ninth Ward.","wiki_en":"Fats Domino","top_song":"Blueberry Hill"},{"name":"Dusty Springfield","emoji":"💄","meta":["soul pop","United Kingdom","1958–1999"],"description":"The British singer had a velvet soul voice and a trademark beehive, and was one of very few white performers accepted as a genuine soul star in the 1960s. The album \"Dusty in Memphis\", with the single \"Son of a Preacher Man\", is considered one of the finest soul records ever made by a British artist.","fact":"\"Dusty in Memphis\" was recorded with the legendary Memphis session players, though Dusty herself doubted she could match them.","wiki_en":"Dusty Springfield","top_song":"Son of a Preacher Man"},{"name":"Boston","emoji":"🚀","meta":["arena rock","United States","since 1976"],"description":"The American rock band from Massachusetts saw its debut album become one of the best-selling debuts in rock history, largely on the strength of the hit \"More Than a Feeling\". Band leader Tom Scholz, an engineer by training, designed the sound equipment for their guitar tone himself.","fact":"Boston album covers traditionally feature a guitar shaped like a spaceship, the band's visual trademark.","wiki_en":"Boston (band)","top_song":"More Than a Feeling"},{"name":"Kansas","emoji":"🌾","meta":["art rock","United States","since 1973"],"description":"The American rock band from the state of Kansas joined hard rock to progressive arrangements and kept a violin in the line-up. The ballad \"Dust in the Wind\" became one of the most recognisable acoustic rock songs of the 1970s.","fact":"\"Dust in the Wind\" began as a guitar exercise that band member Kerry Livgren turned into a song at his wife's suggestion.","wiki_en":"Kansas (band)","top_song":"Dust in the Wind"},{"name":"Styx","emoji":"🤖","meta":["art rock","United States","since 1972"],"description":"The American rock band from Chicago combined hard rock with theatrical progressive elements. The ballad \"Come Sail Away\" and the futuristic hit \"Mr. Roboto\", with its trademark \"domo arigato\", made them one of the most recognisable names in arena rock.","fact":"The line \"domo arigato, Mr. Roboto\" became so widely quoted that it lodged in pop culture quite apart from the band itself.","wiki_en":"Styx (band)","top_song":"Come Sail Away"},{"name":"Survivor","emoji":"🐯","meta":["arena rock","United States","since 1978"],"description":"The American rock band is in the history books forever for \"Eye of the Tiger\", written at Sylvester Stallone's express request for the film \"Rocky III\". The song became one of the great motivational tracks in pop culture and is bound tightly to sport.","fact":"Stallone first wanted Queen's \"Another One Bites the Dust\" for \"Rocky III\", could not get the rights, and turned to Survivor instead.","wiki_en":"Survivor (band)","top_song":"Eye of the Tiger"},{"name":"The Cars","emoji":"🚗","meta":["new wave","United States","1976–1988"],"description":"The American rock band from Boston was one of the key acts of new wave, sitting where punk, synth-pop and classic rock meet. Hits such as \"Just What I Needed\" and \"Drive\" had a cool, stylish sound that shaped many artists in the 1980s.","fact":"The video for \"You Might Think\" won the very first MTV Video Music Award for Video of the Year.","wiki_en":"The Cars","top_song":"Drive"},{"name":"Devo","emoji":"🎩","meta":["new wave","United States","since 1973"],"description":"The American new wave band from Ohio is known for a concept built around the de-evolution of humanity and for their distinctive red cone-shaped hats. Their synth-punk hit \"Whip It\" became one of the most recognisable tracks of the early MTV era.","fact":"The red energy dome hats arrived in the early 1980s and have been Devo's defining visual trademark ever since.","wiki_en":"Devo","top_song":"Whip It"},{"name":"B-52's","emoji":"💇","meta":["new wave","United States","since 1976"],"description":"The American band from Georgia is named after the beehive hairdo, said to resemble the nose of a B-52 bomber, and is known for a gloriously kitsch style. The dance hits \"Rock Lobster\" and \"Love Shack\" made theirs one of the most recognisable sounds in new wave.","fact":"The band's biggest hit, \"Love Shack\", only came out in 1989, ten years after their debut album.","wiki_en":"The B-52s","top_song":"Love Shack"},{"name":"Lizzo","emoji":"💛","meta":["pop / hip-hop","United States","since 2013"],"description":"The American singer, rapper and flautist became one of the voices of body positivity in pop with the hits \"Truth Hurts\" and \"Good as Hell\". She is known for playing the flute brilliantly in the middle of her own concerts, bringing a classical training into pop and hip-hop.","fact":"Lizzo performs with a flute she calls Sasha Flute, working it straight into her concert routines.","wiki_en":"Lizzo","top_song":"Truth Hurts"},{"name":"Ice Spice","emoji":"🧊","meta":["hip-hop / drill","United States","since 2021"],"description":"The American rapper from the Bronx broke into the charts with \"Munch (Feelin' U)\" and became one of the faces of a new generation of New York drill. Her knitted look and unmistakable laid-back delivery quickly turned her into an internet phenomenon and a constant guest on pop collaborations.","fact":"With Nicki Minaj she recorded \"Barbie World\" for the soundtrack of the film \"Barbie\".","wiki_en":"Ice Spice","top_song":"Munch (Feelin' U)"},{"name":"Sabrina Carpenter","emoji":"☕","meta":["pop","United States","since 2014"],"description":"The American singer and actress started out on the Disney Channel and by the mid-2020s had become one of the biggest pop stars around, on the strength of witty lyrics and the hit \"Espresso\". She sets a retro pop sound against a knowing new-wave sex symbol persona.","fact":"Sabrina Carpenter began acting in children's series long before she was known as a singer.","wiki_en":"Sabrina Carpenter","top_song":"Espresso"},{"name":"Chappell Roan","emoji":"👑","meta":["pop","United States","since 2017"],"description":"The American pop singer became one of the great sensations of the mid-2020s with vivid drag-inspired visuals and the hit \"Good Luck, Babe!\". Before her success she was dropped by her label, and spent several years releasing music with almost no support behind her.","fact":"Before becoming a star, Chappell Roan was let go by her label and worked for several years as a barista.","wiki_en":"Chappell Roan","top_song":"Good Luck, Babe!"},{"name":"Benson Boone","emoji":"🤸","meta":["pop","United States","since 2021"],"description":"The American singer and songwriter made his name with the emotional ballad \"Beautiful Things\" and with a trademark stage stunt, a backflip performed mid-song. He started out posting videos on TikTok before signing to a label.","fact":"The backflip Benson Boone performs at almost every concert has become as recognisable as his songs.","wiki_en":"Benson Boone","top_song":"Beautiful Things"},{"name":"Tate McRae","emoji":"🩰","meta":["pop","Canada","since 2017"],"description":"The Canadian singer and dancer began on television dance competitions before turning to music full-time. The hit \"Greedy\", with its magnetic choreography, confirmed her as one of the leading pop stars of a new generation.","fact":"Before her music career, Tate McRae was a finalist on the American dance show \"So You Think You Can Dance\".","wiki_en":"Tate McRae","top_song":"Greedy"},{"name":"EXO","emoji":"🪐","meta":["K-pop","South Korea","since 2012"],"description":"The South Korean boy band from SM Entertainment debuted with a concept built on superpowers and split into separate Chinese and Korean sub-units. They were one of the most commercially successful K-pop acts of the 2010s and set the standard for the groups that followed.","fact":"At the start of their career EXO were promoted as two teams at once, EXO-K and EXO-M, performing in Korean and in Chinese.","wiki_en":"Exo (group)","top_song":"Growl"},{"name":"TWICE","emoji":"🍭","meta":["K-pop","South Korea","since 2015"],"description":"The South Korean girl group of nine was formed by the JYP agency through the reality show \"Sixteen\". Their exuberant hit \"TT\" and its signature sulking gesture became one of the most recognisable symbols of mid-2010s K-pop.","fact":"The dance gesture from the chorus of \"TT\", two fingers tracing tears down the face, became one of the most copied moves in K-pop.","wiki_en":"Twice (group)","top_song":"TT"},{"name":"Stray Kids","emoji":"🎛️","meta":["K-pop","South Korea","since 2018"],"description":"The South Korean boy band write and produce their own songs, which is unusual in the K-pop industry. They were formed on a reality show of the same name, and an aggressive, experimental sound has made them one of the most recognisable acts of the new wave of Korean pop.","fact":"Three members form the production unit 3RACHA, which wrote a large share of the group's songs before they had even debuted.","wiki_en":"Stray Kids","top_song":"God's Menu"},{"name":"NewJeans","emoji":"👖","meta":["K-pop","South Korea","since 2022"],"description":"The South Korean girl group debuted with an easy, everyday Y2K look and a retro sound drawn from the 1990s and 2000s, instead of the hyper-produced aesthetic K-pop usually runs on. They quickly became one of the most discussed new acts, with the hits \"Ditto\" and \"Super Shy\".","fact":"The name NewJeans plays on jeans, a garment that never goes out of fashion, which is exactly what the group means to be.","wiki_en":"NewJeans","top_song":"Ditto"},{"name":"The Supremes","emoji":"👗","meta":["soul / Motown","United States","1959–1977"],"description":"The American Motown trio, with Diana Ross out front, became one of the most successful female groups in the history of pop. Their immaculate harmonies and elegant stage presence produced a run of number ones such as \"Baby Love\" and \"Stop! In the Name of Love\".","fact":"Five Supremes singles topped the Billboard Hot 100 one after another, from \"Where Did Our Love Go\" to \"Back in My Arms Again\".","wiki_en":"The Supremes","top_song":"Baby Love"},{"name":"Barry White","emoji":"🕯️","meta":["soul","United States","1960s–2003"],"description":"The American singer had a trademark deep bass-baritone and became the emblem of romantic soul in the 1970s. His orchestral arrangements and slow, sensual ballads such as \"You're the First, the Last, My Everything\" made his music a byword for seduction.","fact":"Barry White's low bass is so recognisable that his voice is constantly parodied in films and adverts as the sound of seduction itself.","wiki_en":"Barry White","top_song":"You're the First, the Last, My Everything"},{"name":"Isaac Hayes","emoji":"⛓️","meta":["soul / funk","United States","1960s–2008"],"description":"The American singer, composer and producer was one of the architects of the Stax sound and won an Oscar for the theme to the film \"Shaft\". His deep voice and symphonic funk soul shaped the hip-hop producers of later decades, who sampled his records constantly.","fact":"Isaac Hayes became the first African American composer to win an Academy Award for Best Song, for the theme to \"Shaft\".","wiki_en":"Isaac Hayes","top_song":"Theme from Shaft"},{"name":"Jimmy Cliff","emoji":"🌴","meta":["reggae","Jamaica","since 1962"],"description":"The Jamaican singer and actor was one of the first musicians to introduce the world to reggae, before Bob Marley's global fame. His songs and his lead role in the film \"The Harder They Come\" helped the genre travel far beyond the Caribbean.","fact":"\"The Harder They Come\", starring Jimmy Cliff, is considered one of the first films to bring Jamaican musical culture to a mass audience.","wiki_en":"Jimmy Cliff","top_song":"Many Rivers to Cross"},{"name":"John Williams","emoji":"🎬","meta":["film composer","United States","since the 1950s"],"description":"The American composer wrote the music for \"Star Wars\", \"Indiana Jones\", \"Schindler's List\" and dozens of other landmark films. He is one of the most decorated film composers in history, and his themes are recognised even by people who have never seen the films.","fact":"John Williams's \"Star Wars\" theme is one of the most frequently performed orchestral pieces at classical concerts anywhere in the world.","wiki_en":"John Williams","top_song":"Star Wars (Main Title)"},{"name":"Hans Zimmer","emoji":"🎬","meta":["film composer","Germany","since the 1980s"],"description":"The German composer wrote the music for \"Gladiator\", \"Interstellar\", \"The Dark Knight\" and dozens of other blockbusters, and is known for a vast electronic-orchestral sound. He is one of the most sought-after film composers working, and has collaborated with Christopher Nolan across many films.","fact":"The soundtrack of \"Dunkirk\" is built on the ticking of Christopher Nolan's own pocket watch, which the director recorded and sent to the composer.","wiki_en":"Hans Zimmer","top_song":"Time"},{"name":"Ennio Morricone","emoji":"🤠","meta":["film composer","Italy","1946–2020"],"description":"The Italian composer wrote the music for Sergio Leone's westerns, including the whistling and electric guitar of \"The Good, the Bad and the Ugly\". His melodies became inseparable from the spaghetti western, and he received an honorary Oscar for his contribution to film music.","fact":"The whistling in Morricone's themes was performed by Alessandro Alessandroni, whose whistle became part of the spaghetti western sound.","wiki_en":"Ennio Morricone","top_song":"The Good, the Bad and the Ugly (Main Theme)"},{"name":"Eros Ramazzotti","emoji":"🎸","meta":["pop","Italy","since 1984"],"description":"The Italian singer and songwriter is one of the most successful pop performers in both Italian and Spanish. He began with a win at the Sanremo Festival and became one of very few Italian artists with a genuinely worldwide audience.","fact":"Eros Ramazzotti became famous at twenty, winning the young artists' category at the Sanremo Festival in 1984.","wiki_en":"Eros Ramazzotti","top_song":"Più bella cosa"},{"name":"Mick Jagger","emoji":"👄","meta":["rock","United Kingdom","since 1962"],"description":"The permanent frontman of The Rolling Stones, whose restless movement and theatrical charisma on stage set the standard for the rock and roll showman. Alongside the band he has made solo albums and acted in films, and has stayed an emblem of rock for six decades.","fact":"The famous Rolling Stones tongue logo was inspired by Mick Jagger's own lips and expressions.","wiki_en":"Mick Jagger","top_song":"Just Another Night"},{"name":"Keith Richards","emoji":"🎸","meta":["rock","United Kingdom","since 1962"],"description":"The guitarist of The Rolling Stones wrote the riffs that defined the band's sound for decades. He is known for a deliberately loose way of playing, a fondness for open tunings, and a standing as one of the most recognisable rock guitarists in history.","fact":"The famous riff of \"(I Can't Get No) Satisfaction\" came to Keith Richards in his sleep, and he recorded it on a tape machine while barely awake.","wiki_en":"Keith Richards","top_song":"(I Can't Get No) Satisfaction"},{"name":"Ringo Starr","emoji":"🥁","meta":["rock","United Kingdom","since 1962"],"description":"The drummer of The Beatles, whose steady yet inventive playing was the foundation of the band's sound. After the group broke up he had a successful solo career, and his good humour has kept him one of the most loved members of the quartet.","fact":"Ringo Starr is a stage name, invented because of the many rings the drummer wore on his fingers.","wiki_en":"Ringo Starr","top_song":"Photograph"},{"name":"George Harrison","emoji":"🎸","meta":["rock","United Kingdom","1958–2001"],"description":"The guitarist of The Beatles, known as the quiet Beatle, brought an interest in Indian culture and the sound of the sitar into the band's music. After the split he released one of the most successful solo albums by any former Beatle and organised the first major charity rock concert, the Concert for Bangladesh.","fact":"Frank Sinatra called \"Something\", written by Harrison, the greatest love song of the past fifty years.","wiki_en":"George Harrison","top_song":"My Sweet Lord"},{"name":"IOWA","emoji":"🎧","meta":["pop / electropop","Russia","since the late 2000s"],"description":"A pop band with a light electronic sound and the unmistakable voice of singer Katya Ivanchikova, who writes the group's songs herself. The hits \"Ulybaysya\" (\"Smile\"), \"Marshrutka\" and \"Prostaya pesnya\" (\"A Simple Song\") made IOWA a fixture on radio and in the charts in the mid-2010s.","fact":"The band began in Belarus, where its singer comes from, and only later moved to St Petersburg.","wiki_en":"Iowa (band)","top_song":"Улыбайся"},{"name":"Face","emoji":"🖤","meta":["hip-hop","Russia","since 2011"],"description":"The Russian rapper was one of the great provocateurs of the country's hip-hop scene in the mid-2010s, and became known nationwide with the track \"Burger King\". He pairs an aggressive delivery with deliberately brash, at times scandalous lyrics.","fact":"The single \"Burger King\" turned into a wave of memes and made Face one of the most discussed artists on the Russian internet almost overnight.","wiki_en":"Face (rapper)","top_song":"Бургер Кинг"},{"name":"25/17","emoji":"✊","meta":["hip-hop","Russia","since 2003"],"description":"The Russian hip-hop duo from Omsk is known for socially charged lyrics, literary imagery and a rapping style with an almost punk edge. Over the years live guitars have taken up more and more of their sound, and they remain one of the great names of the Russian rap underground.","fact":"The name is short for the group's first name, Ezekiel 25:17, a biblical verse many people know from \"Pulp Fiction\".","wiki_en":"25/17","top_song":"Метель","wiki_ru":"25/17"},{"name":"L'One","emoji":"🌊","meta":["hip-hop","Russia","since 2007"],"description":"The Russian rapper joined hip-hop to full-scale pop production and big stage shows. He was born in Yakutsk and made his name after moving to Moscow: the single \"Okean\" (\"Ocean\") became one of the most recognisable Russian-language rap hits of the second half of the 2010s.","fact":"Before going solo, L'One performed in the duo Marselle and then became one of the leading artists on the Black Star label.","wiki_en":"L'One","top_song":"Океан"},{"name":"INSTASAMKA","emoji":"💅","meta":["hip-hop / pop","Russia","since 2018"],"description":"The Russian performer built a career on a brazen glamorous image and lyrics about money and success, growing out of social media into one of the most-streamed artists in Russian rap. The single \"Za dengi da\" (\"For Money, Yes\") became one of the great viral hits of the Russian internet and dissolved into memes.","fact":"The stage name INSTASAMKA comes from Instagram, where she built her first audience before any music career.","wiki_en":"Instasamka","top_song":"За деньги да"},{"name":"HammAli & Navai","emoji":"💫","meta":["hip-hop / pop","Russia","since 2016"],"description":"The Russian duo became known for melodic songs about love and parting, such as \"Ptichka\" (\"Little Bird\") and \"Pryatki\" (\"Hide and Seek\"). Their lyrical, easily remembered tracks quickly made them two of the most-streamed artists on the Russian internet, and their concerts fill whole halls.","fact":"Navai is not an invented stage name but the real first name of one member of the duo, Navai Bakirov.","wiki_en":"HammAli & Navai","top_song":"Птичка"},{"name":"ANNA ASTI","emoji":"💋","meta":["pop","Russia","since 2021"],"description":"The Russian singer was formerly the voice of the duo Artik & Asti and has been building a successful solo career since the start of the 2020s. Her solo hits set an emotional voice against a striking stage image, and they reach the top of the Russian charts fast.","fact":"The stage name Anna Asti keeps part of the name of Artik & Asti, the duo where the singer began her career.","wiki_en":"Anna Asti","top_song":"По барам"},{"name":"SHAMAN","emoji":"🔥","meta":["pop","Russia","since 2022"],"description":"The Russian singer became widely known through songs released in the early 2020s, among them the single \"Ya russkiy\" (\"I Am Russian\"). He has a strong voice and a theatrical stage manner that quickly made him one of the most conspicuous figures in Russian popular music of the period.","fact":"The singer's real name is Yaroslav Dronov, and before the SHAMAN project he took part in television singing competitions.","wiki_en":"Shaman (singer)","top_song":"Я русский"},{"name":"Yuri Antonov","emoji":"🎹","meta":["estrada pop","USSR / Russia","since the 1970s"],"description":"The Soviet and Russian composer and singer wrote dozens of songs that became classics of Russian popular music, among them \"Pod kryshey doma tvoyego\" (\"Under the Roof of Your House\") and \"More, more\" (\"Sea, Oh Sea\"). He was one of the first in the USSR to perform his own songs rather than simply writing them for other artists.","fact":"\"Pod kryshey doma tvoyego\" became so popular that many people take it for a folk song.","wiki_en":"Yury Antonov","top_song":"Под крышей дома твоего","ru":true},{"name":"Igor Nikolaev","emoji":"🎹","meta":["estrada pop","Russia","since the 1980s"],"description":"The Russian composer, singer and producer wrote a great many hits of Russian popular music, both for himself and for others. His own songs, such as \"Vypyem za lyubov\" (\"Let's Drink to Love\") and \"Taksi, taksi\" (\"Taxi, Taxi\"), made him a recognisable voice on the Russian pop scene, and performing at the piano became his trademark.","fact":"Alla Pugacheva's hits \"Aysberg\" (\"Iceberg\") and \"Paromshchik\" (\"The Ferryman\") were both written by Igor Nikolaev.","wiki_en":"Igor Nikolaev","top_song":"Выпьем за любовь","ru":true},{"name":"Natasha Koroleva","emoji":"👸","meta":["pop","Russia","since 1991"],"description":"The Russian pop singer of Ukrainian descent became a star at the turn of the 2000s with light, immediately memorable pop hits. \"Zholtye tyulpany\" (\"Yellow Tulips\") became one of the calling cards of her career and is still played on radio.","fact":"\"Yellow Tulips\" was written for Natasha Koroleva by the composer Igor Nikolaev, with whom she began her career.","wiki_en":"Natasha Koroleva","top_song":"Жёлтые тюльпаны","ru":true},{"name":"Laima Vaikule","emoji":"🎭","meta":["estrada pop","Latvia","since the 1970s"],"description":"The Latvian singer became one of the most conspicuous stars of the Soviet and post-Soviet pop scene, on the strength of a striking stage image and a theatrical way of performing. Songs such as \"Vernisazh\" (\"Vernissage\") made her a recognisable voice of the 1980s and 1990s.","fact":"Laima Vaikule began her career as a performer at the Riga Music Hall before becoming a solo star across the whole Soviet Union.","wiki_en":"Laima Vaikule","top_song":"Вернисаж","ru":true},{"name":"Valeriya","emoji":"✨","meta":["pop","Russia","since the 1990s"],"description":"The Russian pop singer has been one of the most consistently successful artists in the country's show business since the late 1990s, known for the songs \"Chasiki\" (\"Little Clock\") and \"Byla lyubov\" (\"There Was Love\"). For many years she worked in a creative and production partnership with her husband Iosif Prigozhin.","fact":"\"Chasiki\" became one of Valeriya's most recognisable hits and several generations of listeners still associate it with her.","wiki_en":"Valeriya","top_song":"Часики","ru":true},{"name":"Nikolai Baskov","emoji":"🎼","meta":["pop / operetta","Russia","since 1996"],"description":"The Russian pop singer trained as an opera vocalist and became known at the end of the 1990s by pairing classical singing with a pop repertoire. His delivery and his flamboyant stage presentation made him one of the recognisable figures in Russian popular music.","fact":"Nikolai Baskov received a professional operatic training before becoming a star of pop rather than of the opera house.","wiki_en":"Nikolai Baskov","top_song":"Ты моя мелодия","ru":true},{"name":"Grigory Leps","emoji":"🎙️","meta":["pop / Russian chanson","Russia","since the 1990s"],"description":"The Russian singer has an unmistakable rasp, began as a rock musician and then became one of the biggest stars of Russian popular song and chanson. \"Ryumka vodki na stole\" (\"A Glass of Vodka on the Table\") is one of the most played songs in his repertoire, and his duet with Irina Allegrova, \"Ya tebe ne veryu\", was a huge radio hit.","fact":"Before becoming a star, Grigory Leps spent years singing in the restaurants and bands of his native Sochi.","wiki_en":"Grigory Leps","top_song":"Рюмка водки на столе","ru":true},{"name":"Stas Mikhailov","emoji":"💧","meta":["pop / Russian chanson","Russia","since the 2000s"],"description":"The Russian singer specialises in sentimental ballads about love and became one of the highest-grossing touring artists in Russian popular music across the 2000s and 2010s. His lyrical, faintly theatrical delivery made his name above all at large solo concerts.","fact":"Stas Mikhailov has for years been one of the artists with the most frequent and most extensive concert tours across Russia.","wiki_en":"Stas Mikhailov","top_song":"Всё для тебя","ru":true},{"name":"Ani Lorak","emoji":"🌹","meta":["pop","Ukraine","since the 1990s"],"description":"The Ukrainian singer became known across the former Soviet Union and in Russia after competing at the Eurovision Song Contest and releasing a run of Russian-language pop hits. Her stage name comes from her real one: Karolina read backwards gives Anilorak.","fact":"The singer's real name is Karolina Kuyek, and she represented Ukraine at Eurovision with the song \"Shady Lady\".","wiki_en":"Ani Lorak","top_song":"Shady Lady","ru":true},{"name":"Timati","emoji":"🎧","meta":["hip-hop / pop","Russia","since 2003"],"description":"The Russian rapper, producer and entrepreneur was one of the first artists to turn Russian rap into a mainstream pop product. He founded the Black Star label, which for several years was one of the great production empires of Russian popular music.","fact":"The Black Star label Timati founded grew not only as a music company but as a fashion and restaurant brand.","wiki_en":"Timati","top_song":"Лондон","ru":true},{"name":"Egor Kreed","emoji":"💔","meta":["pop / hip-hop","Russia","since 2011"],"description":"The Russian singer and rapper became known in the early 2010s through the battle rap scene and moved gradually to a melodic pop repertoire. His lyrical hits, such as \"Sumasshedshaya\" (\"Crazy Girl\"), made him one of the most-streamed young artists in Russian popular music.","fact":"Egor Kreed's real name is Egor Bulatkin, and he reached the big stage by signing to the Black Star label.","wiki_en":"Egor Kreed","top_song":"Сумасшедшая","ru":true},{"name":"Klava Koka","emoji":"🍭","meta":["pop","Russia","since 2018"],"description":"One of the most-streamed Russian pop artists: her light dance hits sit in the charts permanently and turn into soundtracks for viral clips on social media. The singer's real name is Klavdiya Vysokova, and she started her career in Yekaterinburg.","fact":"Her joint track \"Krash\" with NILETTO became one of the most popular duets in Russian streaming in the early 2020s.","wiki_en":"Klava Koka","top_song":"Мокрые кроссы","ru":true},{"name":"Artik & Asti","emoji":"💞","meta":["pop","Russia","since the 2010s"],"description":"The Russian pop duo of a producer and a singer is known for a lyrical sound and melodic hits about love and parting. Their songs sit at the top of the Russian streaming charts for years at a time, and their concerts fill large halls.","fact":"The duo's singer Anna Dzyuba left in 2021 and began a solo career as ANNA ASTI, while the duo carried on with a new vocalist.","wiki_en":"Artik & Asti","top_song":"Неделимы","ru":true},{"name":"Polina Gagarina","emoji":"🕊️","meta":["pop","Russia","since 2003"],"description":"The Russian singer became known across the country after appearing on the show \"Star Factory\", and internationally after Eurovision 2015, where she finished second with \"A Million Voices\". She is one of the most recognisable Russian pop performers of the 2010s.","fact":"Before Eurovision, Polina Gagarina won the second season of the television project \"Star Factory\".","wiki_en":"Polina Gagarina","top_song":"A Million Voices","ru":true},{"name":"Nyusha","emoji":"💋","meta":["pop","Russia","since 2009"],"description":"The Russian pop singer debuted with the single \"Voyu na lunu\" (\"Howling at the Moon\"), which made her one of the most conspicuous new artists in Russian popular music of the late 2000s. She is known for a bold stage image and a strong voice.","fact":"The debut single \"Voyu na lunu\" took the singer, still very young, straight to the top of the Russian radio charts.","wiki_en":"Nyusha","top_song":"Вою на луну","ru":true},{"name":"MakSim","emoji":"💔","meta":["pop","Russia","since 2006"],"description":"The Russian pop singer's debut album \"Trudnyy vozrast\" (\"Difficult Age\") became one of the best-selling records in Russia in the mid-2000s. Her emotional ballads about teenage feelings and about love made her one of the great stars of the Russian pop scene of that time.","fact":"The unusual spelling of her name, MakSim with a Latin S, became part of the singer's recognisable visual identity.","wiki_en":"MakSim","top_song":"Знаешь ли ты","wiki_ru":"МакSим","ru":true},{"name":"Slava","emoji":"💄","meta":["pop","Russia","since the 2000s"],"description":"The Russian pop singer became known in the early 2000s through bright, spirited hits and a stage image nobody forgot. \"Odinochestvo\" (\"Loneliness\") became one of the emblems of her career and of Russian pop music of that era.","fact":"The singer performs under the single stage name Slava, having dropped her surname from her professional name altogether.","wiki_en":"Slava (singer)","top_song":"Одиночество","ru":true},{"name":"Sergey Lazarev","emoji":"✨","meta":["pop","Russia","since the 1990s"],"description":"The Russian singer and actor began performing as a child and then in the duo Smash!!, before becoming one of the country's most successful solo pop artists. He has represented Russia at Eurovision twice, finishing third in 2016 with \"You Are the Only One\".","fact":"Lazarev's Eurovision 2016 performance, with its spectacular digital video mapping, was one of the most memorable acts of the contest.","wiki_en":"Sergey Lazarev","top_song":"You Are the Only One","ru":true},{"name":"Yolka","emoji":"🎄","meta":["pop","Russia","since 2005"],"description":"The Russian singer of Ukrainian descent is known for lyrical pop hits such as \"Provans\" (\"Provence\") and \"Greyu schastye\" (\"Keeping Happiness Warm\"). She pairs strong melody with a lightly ironic delivery, and her arrangements draw on soul and hip-hop.","fact":"The singer's real name is Yelizaveta Ivantsiv, and before her solo success she spent several years performing in Ukraine.","wiki_en":"Yolka (singer)","top_song":"Прованс","ru":true},{"name":"Zhasmin","emoji":"🌸","meta":["pop","Russia","since the 1990s"],"description":"The Russian pop singer is known for lyrical ballads and for the Eastern motifs in some of her songs, which echo her stage name. She was a steady presence in Russian popular music right through the 1990s and 2000s.","fact":"The singer's real name is Sara Manakhimova, and she comes from Derbent in Dagestan.","wiki_en":"Zhasmin","top_song":"Головоломка","ru":true},{"name":"Diskoteka Avariya","emoji":"🚨","meta":["pop / comedy","Russia","since 1990"],"description":"The Russian group is known for wry, often outright comic dance hits such as \"Disko Superzvezda\" (\"Disco Superstar\") and \"Malinki\". They were among the first in Russian pop to make send-up and parody their trademark, videos included.","fact":"The group comes from Ivanovo, where it formed at the turn of the 1990s, long before its first hits.","wiki_en":"Diskoteka Avariya","top_song":"Диско Суперзвезда","ru":true},{"name":"Uma2rman","emoji":"🎸","meta":["pop rock","Russia","since the 2000s"],"description":"The Russian duo of the Kristovsky brothers from Nizhny Novgorod became known for easy acoustic pop-rock songs such as \"Prostitsya\" (\"Saying Goodbye\") and \"Praskovya\". Their unforced, almost conversational singing set them apart from the grander end of Russian pop.","fact":"The name plays on the actress Uma Thurman: \"Uma2rman\" reads out almost exactly as her name does.","wiki_en":"Uma2rman","top_song":"Проститься","ru":true},{"name":"Chizh & Co","emoji":"🎸","meta":["rock","Russia","since 1994"],"description":"The Russian rock band led by Sergey Chigrakov joined blues rock to Russian lyric writing. Their song \"O lyubvi\" (\"About Love\") became one of the most recognisable Russian-language rock hits of the 1990s and is still played on radio and at concerts.","fact":"Band leader Sergey Chigrakov is also known as one of very few Russian rock musicians to engage seriously with the blues tradition.","wiki_en":"Chizh & Co","top_song":"О любви","ru":true},{"name":"Tantsy Minus","emoji":"🖤","meta":["rock / pop","Russia","since 1996"],"description":"The Russian rock band became known at the end of the 1990s with melancholy hits such as \"Polovinka\" (\"My Other Half\") and the lyrical manner of frontman Vyacheslav Petkun. Their sound joined rock to electronic textures and to a kind of urban poetry.","fact":"Frontman Vyacheslav Petkun sang Quasimodo in the Russian production of the musical \"Notre-Dame de Paris\": it was his voice on \"Belle\".","wiki_en":"Tantsy Minus","top_song":"Половинка","ru":true},{"name":"Zemlyane","emoji":"🌍","meta":["rock","USSR / Russia","since 1978"],"description":"The Soviet rock band wrote one of the great Russian rock hits, \"Trava u doma\" (\"The Grass Beside Our Home\"), a song dedicated to Soviet cosmonauts that became the unofficial anthem of Cosmonautics Day. They were one of the first Soviet rock bands to become popular across the whole country.","fact":"In 2009 \"Trava u doma\" was officially adopted as the anthem of Russian cosmonautics.","wiki_en":"Zemlyane","top_song":"Трава у дома","wiki_ru":"Земляне (группа)","ru":true},{"name":"Nogu Svelo!","emoji":"🦵","meta":["rock / punk","Russia","since 1988"],"description":"The Russian rock band led by Maxim Pokrovsky is known for an eccentric sound and lyrics thick with irony. The song \"Haru Mamburu\", whose title looks like nonsense, became one of the most recognisable Russian-language rock hits of the 1990s.","fact":"\"Haru Mamburu\" has no literal translation and was invented for the sound of it rather than for any meaning.","wiki_en":"Nogu Svelo!","top_song":"Хару Мамбуру","ru":true},{"name":"Smyslovye Gallyutsinatsii","emoji":"🌀","meta":["rock","Russia","since 1990"],"description":"The Russian rock band from Yekaterinburg became known in the early 2000s for lyrics that are wry and philosophical at the same time. Their song \"Vechno molodoy\" (\"Forever Young\") became one of the great rock hits of the era of the station Nashe Radio.","fact":"\"Vechno molodoy\" became a nationwide song after it was used in the film \"Brother 2\".","wiki_en":"Smyslovye Gallyutsinatsii","top_song":"Вечно молодой","ru":true},{"name":"Mnogotochie","emoji":"🖤","meta":["rap rock","Russia","since 1998"],"description":"The Russian rap-rock band joined rapping to melodic rock choruses, which was a rarity on the Russian scene of the early 2000s. Hits such as \"V zhizni tak byvaet\" (\"That's How Life Goes\") made them one of the notable phenomena of Russian alternative rock.","fact":"\"V zhizni tak byvaet\" is one of the most quoted songs in Russian rap, familiar even to people who never listen to the genre.","wiki_en":"Mnogotochie","top_song":"В жизни так бывает","ru":true},{"name":"Pilot","emoji":"✈️","meta":["punk rock","Russia","since 1997"],"description":"The Russian punk rock band led by Ilya Chert is known for fierce lyrics about freedom and about living close to the edge. Their concerts are marked by an unusual emotional intensity and by a fiercely loyal audience.","fact":"Band leader Ilya Chert writes not only songs but books, about his views on life, on creativity and on music.","wiki_en":"Pilot (Russian band)","top_song":"Идёт война","wiki_ru":"Пилот (группа)","ru":true},{"name":"Yu-Piter","emoji":"🪐","meta":["rock","Russia","since 2001"],"description":"The Russian rock project of Vyacheslav Butusov carried on the thread of his work after the band Nautilus Pompilius. The name plays on both the planet Jupiter and Piter, the nickname of St Petersburg, where the band formed and where its leader lives.","fact":"Yuri Kasparyan, the guitarist of the band Kino, played in Yu-Piter alongside Butusov for many years.","wiki_en":"U-Piter","top_song":"Крылья","wiki_ru":"Ю-Питер","ru":true},{"name":"Okean Elzy","emoji":"🌊","meta":["rock","Ukraine","since 1994"],"description":"The Ukrainian rock band led by Svyatoslav Vakarchuk is one of the most successful and recognisable rock acts anywhere in the former Soviet Union. \"Bez boyu\" (\"Without a Fight\") and \"Obiymy\" (\"Hold Me\"), along with dozens of other hits, made them an emblem of Ukrainian rock.","fact":"Frontman Svyatoslav Vakarchuk holds a doctorate in physics and mathematics and is the son of a physicist from Lviv.","wiki_en":"Okean Elzy","top_song":"Обійми","ru":true},{"name":"Ivanushki International","emoji":"🎈","meta":["pop","Russia","since 1995"],"description":"The Russian pop group became one of the great phenomena of Russian popular music in the second half of the 1990s, on the strength of light, melodic hits such as \"Topolinyy pukh\" (\"Poplar Fluff\"). Their simple, unforgettable songs stayed part of mass culture for years.","fact":"\"Topolinyy pukh\" lodged in the culture so firmly that a line from it became a stock phrase for the start of summer.","wiki_en":"Ivanushki International","top_song":"Тополиный пух","ru":true},{"name":"Na-Na","emoji":"🕺","meta":["pop","Russia","since 1990"],"description":"The Russian pop group was created by the producer Bari Alibasov and became one of the first genuinely mass-market boy bands of post-Soviet popular music. Vivid stage costumes and driving hits made them a recognisable emblem of the 1990s.","fact":"The Na-Na line-up changed many times over the years, yet the project stayed inseparable from the name of Bari Alibasov.","wiki_en":"Na Na (boy band)","top_song":"Фаина","wiki_ru":"На-На","ru":true},{"name":"Otpetye Moshenniki","emoji":"🎩","meta":["pop","Russia","since 1996"],"description":"The Russian pop group of the late 1990s was known for light dance hits with wry lyrics, among them \"Devushki byvayut raznye\" (\"Girls Come in All Kinds\") and \"Vsyako-razno\". Their name, which means hardened crooks, became part of a knowing comic persona.","fact":"The joke name Otpetye Moshenniki caught the generally unserious, playful tone of their songs and videos.","wiki_en":"Otpetye Moshenniki","top_song":"Девушки бывают разные","wiki_ru":"Отпетые мошенники (группа)","ru":true},{"name":"Strelki","emoji":"💘","meta":["pop","Russia","since 1999"],"description":"The Russian girl group was built on the girl band model and became one of the notable projects at the turn of the 2000s. Their singles had the light dance sound typical of Russian pop at that moment.","fact":"Strelki were assembled on the model of the casting-built pop projects that were popular around the turn of the millennium.","wiki_en":"Strelki","top_song":"Ты бросил меня","wiki_ru":"Стрелки (группа)","ru":true},{"name":"Blestyashchie","emoji":"✨","meta":["pop","Russia","since 1997"],"description":"The Russian girl group was one of the most successful in Russian popular music from the late 1990s into the early 2000s. Despite repeated changes of line-up, they held on to a recognisable light dance sound throughout.","fact":"The Blestyashchie line-up changed many times over the years, yet the name and the concept of the group stayed the same.","wiki_en":"Blestyashchie","top_song":"Восточные сказки","ru":true},{"name":"Fabrika","emoji":"🏭","meta":["pop","Russia","since 2002"],"description":"The Russian pop group was created within the television project \"Star Factory\" and became one of the most successful musical products of Russian television in the early 2000s. Several singers passed through the group and went on to successful solo careers.","fact":"The name Fabrika refers directly to the television show \"Star Factory\", the programme that formed the group.","wiki_en":"Fabrika","top_song":"Про любоff","wiki_ru":"Фабрика (группа)","ru":true},{"name":"Korni","emoji":"🌳","meta":["pop","Russia","since 2002"],"description":"The Russian pop group also grew out of the \"Star Factory\" project and is known for sentimental hits such as \"Ty uznayesh yeyo\" (\"You'll Recognise Her\") and \"S dnyom rozhdeniya, Vika\" (\"Happy Birthday, Vika\"). Their lyrical sound was aimed squarely at the broad radio audience of the early 2000s.","fact":"Korni, like Fabrika, came together through the television project \"Star Factory\" on Channel One.","wiki_en":"Korni","top_song":"Ты узнаешь её","wiki_ru":"Корни (группа)","ru":true},{"name":"Dinamit","emoji":"🧨","meta":["pop","Russia","since the 2000s"],"description":"The Russian pop group became a notable presence in Russian popular music in the early 2000s, with driving dance songs and heavy rotation on the music channels. The name underlined an explosive, high-voltage stage image.","fact":"The vivid name Dinamit underlined the group's energetic and forward-pushing presence on stage.","wiki_en":"Dinamit (band)","top_song":"Пьяное солнце","wiki_ru":"Динамит (группа)","ru":true},{"name":"Gorod 312","emoji":"🏙️","meta":["pop rock","Kyrgyzstan / Russia","since 2001"],"description":"The rock band has Kyrgyz roots, moved to Moscow and became known for melodic pop-rock hits such as \"Ostanus\" (\"I'll Stay\"). A lyrical, accessible sound and the voice of singer Aya made them one of the notable acts on Russian radio in the 2000s.","fact":"The name Gorod 312 refers to the telephone dialling code of Bishkek, the city the band members come from.","wiki_en":"Gorod 312","top_song":"Останусь","wiki_ru":"Город 312","ru":true},{"name":"Yuri Loza","emoji":"🛥️","meta":["pop","USSR / Russia","since the 1980s"],"description":"The Soviet and Russian singer-songwriter became known across the whole Soviet Union with \"Plot\" (\"The Raft\"), which long ago turned into one of the most recognisable emblems of late Soviet popular music. His work joined the bard song tradition to a pop sound.","fact":"\"Plot\" is bound so tightly to Yuri Loza's name that it has become almost a synonym for his whole output.","wiki_en":"Yuri Loza","top_song":"Плот","ru":true},{"name":"Laskovyi May","emoji":"🌸","meta":["pop","USSR","since 1986"],"description":"The Soviet pop group became a genuine phenomenon in the second half of the 1980s with sentimental songs about growing up in an orphanage and about love, including the hit \"Belye rozy\" (\"White Roses\"). Producer Andrey Razin's project became one of the great mass phenomena of late Soviet popular music.","fact":"\"White Roses\" grew so popular that in the late 1980s several different line-ups of Laskovyi May toured the country at once under the same name.","wiki_en":"Laskovyi Mai","top_song":"Белые розы","wiki_ru":"Ласковый май","ru":true},{"name":"Tekhnologiya","emoji":"🤖","meta":["synth-pop","Russia","since 1991"],"description":"The Russian synth-pop band was one of the first anywhere in the former Soviet Union to work seriously in electronic dance music. Hits such as \"Nazhmi na knopku\" (\"Press the Button\") made them an emblem of 1990s club culture.","fact":"\"Nazhmi na knopku\" became one of the first genuine club hits on the Russian pop scene of the 1990s.","wiki_en":"Technology (band)","top_song":"Нажми на кнопку","wiki_ru":"Технология (группа)","ru":true},{"name":"Mirage","emoji":"💿","meta":["disco / synth-pop","USSR","since 1986"],"description":"The Soviet synth-pop group became one of the great emblems of disco-flavoured popular music in the second half of the 1980s, with hits such as \"Muzyka nas svyazala\" (\"Music Bound Us Together\"). Unusually, the songs on record and the songs on stage were for years sung by different women.","fact":"For many years different singers might perform Mirage's songs in the studio and at concerts: the concept was built around a producer's idea rather than one voice.","wiki_en":"Mirage (Russian band)","top_song":"Музыка нас связала","wiki_ru":"Мираж (группа)","ru":true},{"name":"Kombinatsiya","emoji":"🧮","meta":["pop","USSR / Russia","since 1988"],"description":"The Soviet and Russian pop group became known for the wry song \"Bukhgalter\" (\"The Accountant\"), which was quoted everywhere at the turn of the 1990s. A light, joking sound made them one of the brightest phenomena of late Soviet popular music.","fact":"\"Bukhgalter\" lodged in mass culture so firmly that a line from it stayed a stock joke for decades afterwards.","wiki_en":"Kombinaciya","top_song":"Бухгалтер","wiki_ru":"Комбинация (группа)","ru":true},{"name":"Kar-Men","emoji":"🎩","meta":["pop / disco","USSR / Russia","since 1990"],"description":"The Soviet and Russian pop duo was known for vivid exotic personas and the dance hits \"London, gudbay\" (\"London, Goodbye\") and \"San-Frantsisko\". Striking costumes and videos full of foreign imagery made them instantly recognisable in the popular music of the early 1990s.","fact":"Kar-Men produced Bogdan Titomir, who went on to a loud solo career of his own.","wiki_en":"Car-Man","top_song":"Лондон, гудбай","wiki_ru":"Кар-мэн","ru":true},{"name":"Natalya Vetlitskaya","emoji":"💃","meta":["pop","Russia","since the 1980s"],"description":"The Russian pop singer began her career in the group Mirage and then became a well-known solo artist with the hit \"Posmotri v glaza\" (\"Look Me in the Eyes\"). She is one of the recognisable figures of the Russian pop scene of the 1990s.","fact":"Before becoming a solo star, Natalya Vetlitskaya was one of the singers in the group Mirage.","wiki_en":"Natalya Vetlitskaya","top_song":"Посмотри в глаза","ru":true},{"name":"Bogdan Titomir","emoji":"🕺","meta":["pop / rap","Russia","since 1988"],"description":"The Russian performer was one of the first artists in post-Soviet popular music to join breakdancing and rap elements to a pop sound. The hit \"Delay kak ya\" (\"Do As I Do\") and his sheer physical presence on stage made him one of the most conspicuous figures of the early 1990s.","fact":"Bogdan Titomir was among the first in the USSR to make breakdancing a real part of his stage performances.","wiki_en":"Bogdan Titomir","top_song":"Делай как я","ru":true},{"name":"Chris Kelmi","emoji":"🎹","meta":["rock","USSR / Russia","since the 1970s"],"description":"The Soviet and Russian rock musician and keyboard player played in Visokosnoe Leto, founded the band Rock-Atelier and then became a solo artist with the hit \"Nochnoe rendezvous\" (\"Night Rendezvous\"). He was one of the few Soviet rockers whose songs also played on official popular radio.","fact":"\"Zamykaya krug\" (\"Closing the Circle\"), sung together by dozens of Soviet stars in the late 1980s, was written by Chris Kelmi.","wiki_en":"Kris Kelmi","top_song":"Ночное рандеву","wiki_ru":"Кельми, Крис","ru":true},{"name":"Valery Leontiev","emoji":"🦚","meta":["pop","USSR / Russia","since the 1970s"],"description":"The Soviet and Russian pop singer is known for extravagant stage costumes and a physical energy that was thoroughly unusual for official Soviet popular music. For decades he has remained one of the most recognisable voices and images in Russian pop.","fact":"Valery Leontiev's vivid, at times outrageous stage costumes were already his trademark in the Soviet years.","wiki_en":"Valery Leontiev","top_song":"Дельтаплан","ru":true},{"name":"Alexander Rosenbaum","emoji":"🎻","meta":["bard song / chanson","USSR / Russia","since the 1970s"],"description":"The Soviet and Russian singer-songwriter, a doctor by training, joined the bard song tradition to the urban romance and to chanson. Songs such as \"Vals-boston\" (\"Boston Waltz\") became classics of Russian songwriting of the past few decades.","fact":"Alexander Rosenbaum first trained as an ambulance doctor and spent many years combining medicine with a music career.","wiki_en":"Alexander Rosenbaum","top_song":"Вальс-бостон","ru":true},{"name":"Mikhail Boyarsky","emoji":"🎩","meta":["actor / singer","USSR / Russia","since the 1970s"],"description":"The Soviet and Russian actor and singer became famous as D'Artagnan in the television film \"D'Artagnan and Three Musketeers\" and has been inseparable from a wide-brimmed hat ever since. His songs from films and musicals became a permanent part of Soviet screen music.","fact":"The wide-brimmed hat that became Boyarsky's trademark is not merely a costume: he wears one in everyday life too.","wiki_en":"Mikhail Boyarsky","top_song":"Пора-пора-порадуемся","ru":true},{"name":"Oleg Gazmanov","emoji":"🎸","meta":["pop / rock","USSR / Russia","since the 1980s"],"description":"The Soviet and Russian singer started out in rock and disco and later became known for driving pop hits and for songs such as \"Ofitsery\" (\"Officers\") and \"Moskva\" (\"Moscow\"). He is one of the most recognisable voices in Russian popular music of the 1990s and 2000s.","fact":"Oleg Gazmanov is the father of the singer Rodion Gazmanov, who as a child sang the hit \"Lyusi\" (\"Lucy\").","wiki_en":"Oleg Gazmanov","top_song":"Москва","ru":true},{"name":"Lyube","emoji":"🪖","meta":["rock / pop","Russia","since 1989"],"description":"The Russian band led by Nikolai Rastorguev joined rock to folk and army motifs. Songs such as \"Kombat\" and \"Atas\" made them one of the most recognisable voices in the male end of Russian popular music across the 1990s and 2000s.","fact":"The name Lyube refers to Lyubertsy near Moscow and to the lyubery, a prominent youth subculture of the late 1980s.","wiki_en":"Lyube","top_song":"Комбат","ru":true},{"name":"Joseph Kobzon","emoji":"🎩","meta":["estrada pop","USSR / Russia","1959–2018"],"description":"The Soviet and Russian singer was one of the most decorated performers of the Soviet era, with a formidable baritone and an immaculate stage bearing. For decades he was the emblem of official Soviet popular music, singing both lyrical and patriotic songs.","fact":"Joseph Kobzon went on giving concerts even while gravely ill, staying on stage right up to the last years of his life.","wiki_en":"Joseph Kobzon","top_song":"Мгновения","ru":true},{"name":"Edita Piekha","emoji":"🎀","meta":["estrada pop","USSR / Russia","since 1955"],"description":"The Soviet and Russian pop singer of Polish descent is one of the longest-performing artists on the Russian stage. Her soft, lyrical voice and songs such as \"Ogromnoe nebo\" (\"The Vast Sky\") made her one of the great stars of Soviet popular music in the 1960s and 1970s.","fact":"Edita Piekha was born in France to a Polish family and only came to the USSR as a student, to study in Leningrad.","wiki_en":"Edita Piekha","top_song":"Огромное небо","ru":true},{"name":"Tamara Gverdtsiteli","emoji":"🎹","meta":["estrada pop","Georgia / Russia","since the 1980s"],"description":"The Georgian and Russian singer and pianist is known for a powerful voice and a repertoire that takes in popular song, the romance and jazz. She is one of the most recognisable voices of the post-Soviet stage and performs both as a singer and as a classical pianist.","fact":"Tamara Gverdtsiteli is a professionally trained pianist, a conservatory graduate, and often accompanies herself in concert.","wiki_en":"Tamara Gverdtsiteli","top_song":"Виват, король, виват!","ru":true},{"name":"Larisa Dolina","emoji":"🎷","meta":["jazz / estrada pop","USSR / Russia","since the 1970s"],"description":"The Soviet and Russian singer has a formidable jazz voice and moves with equal confidence between a popular repertoire and jazz standards. She is one of the most decorated vocalists on the post-Soviet stage, with a career spanning decades.","fact":"Larisa Dolina has long combined a career in popular music with jazz projects, for which she has been recognised separately as a jazz singer.","wiki_en":"Larisa Dolina","top_song":"Погода в доме","ru":true},{"name":"Igor Talkov","emoji":"🕊️","meta":["rock / pop","USSR","1982–1991"],"description":"The Soviet singer and songwriter was known for politically engaged, at times fiercely social lyrics in songs such as \"Rossiya\" (\"Russia\") and \"Chistye prudy\" (\"Clean Ponds\"). He died in tragic circumstances in 1991, at a concert in St Petersburg.","fact":"Igor Talkov died of a gunshot wound backstage, before his own concert, in October 1991.","wiki_en":"Igor Talkov","top_song":"Россия","ru":true},{"name":"Pesniary","emoji":"🌾","meta":["vocal-instrumental ensemble","USSR (Belarus)","since 1969"],"description":"The Belarusian vocal and instrumental ensemble was one of the best-known groups of its kind in Soviet popular music, joining Belarusian folk song to rock and pop arrangements. \"Vologda\" and \"Aleksandrina\" became classics of the genre and are still played today.","fact":"The ensemble was created by Vladimir Mulyavin, who had the idea of joining Belarusian folk song to electric guitars and close harmony.","wiki_en":"Pesniary","top_song":"Вологда","ru":true},{"name":"Chyorny Obelisk","emoji":"🖤","meta":["heavy metal","USSR / Russia","since the 1980s"],"description":"The Soviet and Russian metal band was founded by Anatoly Krupnov and carried on after his death with other musicians. They were one of the first genuinely heavy rock acts anywhere in the USSR and laid the foundation for Russian-language heavy metal.","fact":"Chyorny Obelisk were one of the first bands in the USSR to play heavy rock with almost no regard for official censorship.","wiki_en":"Chyorny Obelisk","top_song":"Я остаюсь","wiki_ru":"Чёрный Обелиск (группа)","ru":true},{"name":"Piknik","emoji":"🎭","meta":["art rock","USSR / Russia","since 1978"],"description":"The Russian art rock band led by Edmund Shklyarsky is known for a theatrical stage presentation and for the mystical imagery of its lyrics. They are one of the longest-lasting and most consistently touring rock acts in the former Soviet Union.","fact":"Piknik concerts traditionally come with elaborate theatrical costumes and sets, which is rare for a rock act on that scale.","wiki_en":"Piknik (band)","top_song":"Иероглиф","ru":true},{"name":"Kalinov Most","emoji":"🌉","meta":["rock","USSR / Russia","since 1986"],"description":"The Siberian rock band led by Dmitry Revyakin joined rock to folk and Slavic motifs. They were one of the key bands of the Siberian rock scene of the late 1980s, and grew out of the Novosibirsk underground.","fact":"The name Kalinov Most refers to the mythological bridge of Russian folk tales that divides the world of the living from the world of the dead.","wiki_en":"Kalinov Most","top_song":"Сестра","ru":true},{"name":"Kasta","emoji":"🎙️","meta":["hip-hop","Russia","since 1996"],"description":"The Russian hip-hop group from Rostov-on-Don is one of the most respected in Russian rap, for the complexity of its lyrics and the freestyling skill of its members. The track \"Vokrug shum\" (\"Noise All Around\") became one of the great Russian-language rap hits of the 2000s.","fact":"The members of Kasta are known as some of the strongest freestylers on the Russian rap scene, and prove it regularly in battles.","wiki_en":"Kasta","top_song":"Вокруг шум","wiki_ru":"Каста (группа)","ru":true},{"name":"Guf","emoji":"🖤","meta":["hip-hop","Russia","since the 1990s"],"description":"The Russian rapper from Moscow was one of the key artists of the country's underground hip-hop in the 2000s, known for a melancholy delivery and lyrical writing. The album \"Gorod dorog\" (\"City of Roads\") and other records made him a cult figure in Russian rap.","fact":"Guf's real name is Alexey Dolmatov, and the nickname stuck to him when he was still young.","wiki_en":"Guf (rapper)","top_song":"Осень","wiki_ru":"Гуф","ru":true},{"name":"Kaspiysky Gruz","emoji":"🎧","meta":["hip-hop","Russia","since the 2000s"],"description":"The Russian rap group became known for wry, conversational lyrics about everyday life and criminal plots. Their unforced delivery and distinctive beats made them popular in the Russian-language hip-hop underground of the 2010s.","fact":"Kaspiysky Gruz songs spread across the country with almost no radio or television support, largely through the internet.","wiki_en":"Kaspiysky Gruz","top_song":"Билборды","wiki_ru":"Каспийский груз","ru":true},{"name":"Artur Pirozhkov","emoji":"💃","meta":["pop","Russia","since the 2010s"],"description":"The stage persona of the comedian Alexander Revva: a spoof pop artist whose dance hits \"Zatsepila\" (\"She Hooked Me\") and \"Chika\" spread through clubs and social media. Deliberately grotesque delivery and self-mocking videos made the project one of the most recognisable in Russian pop of the late 2010s.","fact":"Artur Pirozhkov is not a real name but a comic stage persona created by the performer Alexander Revva.","wiki_en":"Aleksandr Revva","top_song":"Зацепила","wiki_ru":"Ревва, Александр Владимирович","ru":true},{"name":"Valentin Strykalo","emoji":"🎸","meta":["indie rock","Ukraine / Russia","since the 2010s"],"description":"The project of Kharkiv musician Yuri Kaplan is known for wry indie rock and for the hit \"Nashe leto\" (\"Our Summer\"), one of the most recognisable Russian-language summer tracks ever made. It pairs simple melodies with conversational, easily remembered words.","fact":"It all began with Yuri Kaplan's home comedy videos, in which he first sang spoof songs straight to camera.","wiki_en":"Valentin Strykalo","top_song":"Наше лето","wiki_ru":"Валентин Стрыкало","ru":true},{"name":"Husky","emoji":"🐺","meta":["hip-hop","Russia","since 2013"],"description":"The Russian rapper is known for a bleak, poetic way with words and for socially sharp images of provincial Russia. He is one of the most respected artists on the independent Russian rap scene of the 2010s, and his lyrics are often analysed as contemporary poetry.","fact":"Husky's real name is Dmitry Kuznetsov, and he trained as a journalist rather than as a musician.","wiki_en":"Husky (rapper)","top_song":"Панелька","wiki_ru":"Хаски (рэпер)","ru":true},{"name":"LSP","emoji":"🎧","meta":["hip-hop","Belarus / Russia","since the 2010s"],"description":"The rapper and singer is known for a melancholy, atmospheric sound and lyrics about self-examination and urban loneliness. He is one of the artists who stood at the source of the Russian-language emo rap wave of the second half of the 2010s.","fact":"LSP comes from Minsk, where he started performing long before he became popular in Russia.","wiki_en":"LSP (rapper)","top_song":"Салют, Вера","ru":true},{"name":"Poshlaya Molly","emoji":"🎸","meta":["pop punk","Ukraine / Russia","since the 2010s"],"description":"The Russian-language pop-punk band from Kharkiv, led by Kirill Bledny, became one of the leading acts of the Russian-language emo and pop-punk wave of the second half of the 2010s. Their fierce, wry songs about growing up and about relationships found a wide young audience.","fact":"The band's name is deliberately provocative, chosen to stand out immediately against the more restrained names on the rock scene.","wiki_en":"Poshlaya Molly","top_song":"Дисфория","ru":true},{"name":"Krovostok","emoji":"🩸","meta":["hip-hop","Russia","since the 2000s"],"description":"The Russian rap group is known for deliberately brutal, grotesque lyrics and a black humour that balances on the edge of provocation. They are one of the most recognisable voices of the Russian hip-hop underground, on the strength of the contrast between real literary reading and a wilfully coarse delivery.","fact":"Krovostok's lyrics are often compared to crime fiction for their deliberately hard, cinematic language.","wiki_en":"Krovostok","top_song":"Танцпол","ru":true},{"name":"Mot","emoji":"🦋","meta":["hip-hop / pop","Russia","since the 2010s"],"description":"The Russian rapper and singer became known for melodic tracks about love that set rapped verses against pop choruses. In the second half of the 2010s his songs barely left the radio, and he recorded duet after duet with pop stars.","fact":"The artist's real name is Matvey Melnikov, and he became widely known as an artist on the Black Star label.","wiki_en":"Mot (rapper)","top_song":"Капкан","ru":true},{"name":"Djigan","emoji":"💎","meta":["hip-hop / pop","Russia","since the 2000s"],"description":"The Russian rapper was one of the artists who pushed Russian-language rap as close to pop and club music as it would go. A long list of joint tracks with other artists made him one of the most heavily played performers of club rap in the 2010s.","fact":"Djigan is known for the sheer number of tracks he has made with other artists: collaborations are effectively the backbone of his catalogue.","wiki_en":"GeeGun","top_song":"ДНК","wiki_ru":"Джиган","ru":true},{"name":"Stas Piekha","emoji":"🎹","meta":["pop","Russia","since the 2000s"],"description":"The Russian pop singer, grandson of the legendary Edita Piekha, became known in the early 2000s for lyrical pop ballads. He carries on the family's tradition on the popular stage while remaining very much a solo artist in his own right.","fact":"Stas Piekha is the grandson of the singer Edita Piekha, but built his career as an artist entirely in his own name.","wiki_en":"Stas Piekha","top_song":"Улетаю","ru":true},{"name":"Klavdiya Shulzhenko","emoji":"🌹","meta":["estrada pop","USSR","1928–1984"],"description":"The Soviet singer was one of the great stars of Russian popular music before and during the Second World War. It was her performance of \"Siniy platochek\" (\"The Blue Kerchief\") that made the song an emblem of the era: she sang it to soldiers at the front, and it has belonged to her ever since.","fact":"During the war Klavdiya Shulzhenko gave hundreds of concerts for soldiers, including in besieged Leningrad.","wiki_en":"Klavdiya Shulzhenko","top_song":"Синий платочек","ru":true},{"name":"Lyudmila Zykina","emoji":"🎼","meta":["folk song","USSR","1947–2009"],"description":"The Soviet and Russian singer was one of the great interpreters of Russian folk song in the twentieth century, with a deep and instantly recognisable voice. \"Techot reka Volga\" (\"The Volga Flows\") became one of the musical calling cards of her long career.","fact":"For many decades Lyudmila Zykina remained one of the central emblems of Russian folk song on the Soviet and Russian stage.","wiki_en":"Lyudmila Zykina","top_song":"Течёт река Волга","ru":true},{"name":"Eduard Khil","emoji":"🎩","meta":["estrada pop","USSR","1955–2012"],"description":"The Soviet singer was known for a rich baritone and cheerful songs, among them \"I Am So Glad, Because I'm Finally Returning Back Home\", which decades later became the internet meme Trololo thanks to its wordless vocalise.","fact":"Late in life Eduard Khil unexpectedly became a global internet star, thanks to the Trololo video that travelled around the world.","wiki_en":"Eduard Khil","top_song":"Я очень рад, ведь я, наконец, возвращаюсь домой","ru":true},{"name":"Lev Leshchenko","emoji":"🏅","meta":["estrada pop","USSR / Russia","since the 1960s"],"description":"The Soviet and Russian singer was one of the defining voices of official Soviet popular music, and sang \"Do svidaniya, Moskva\" (\"Goodbye, Moscow\") at the closing ceremony of the 1980 Moscow Olympics. He has stayed one of the emblematic figures of Russian popular song for decades.","fact":"Leshchenko sang \"Goodbye, Moscow\" as a duet with Tatyana Antsiferova: it was the song that played as the Olympic bear Misha floated into the sky.","wiki_en":"Lev Leshchenko","top_song":"До свидания, Москва","ru":true},{"name":"Mari Kraimbreri","emoji":"💗","meta":["pop","Russia","since the 2010s"],"description":"The Russian singer and songwriter writes her own repertoire: lyrical pop songs about love and parting. Her emotional, faintly theatrical delivery became her signature, and her tracks regularly reach the top of the Russian streaming charts.","fact":"Mari Kraimbreri writes both the words and the music of her own songs, which on the Russian pop scene is still not the most common story.","wiki_en":"Mari Kraimbrery","top_song":"Пряталась в ванной","wiki_ru":"Мари Краймбрери","ru":true},{"name":"Maybe Baby","emoji":"🌙","meta":["pop","Russia","since the 2020s"],"description":"The Russian singer of a younger generation built her popularity quickly on streaming services, with light, atmospheric pop songs. Her close, intimate way of singing found its audience above all among the young people of social media.","fact":"The name Maybe Baby was chosen straight from the English phrase, for how easy and memorable it sounds.","wiki_en":"Maybe Baby (singer)","top_song":"Дом","ru":true},{"name":"Dora","emoji":"🌈","meta":["pop / indie","Russia","since the 2010s"],"description":"The Russian singer and songwriter is known for a vivid eccentric image and an eclectic sound sitting between pop, indie and electronics. She started out on YouTube with comedy and music clips before becoming a pop artist in her own right.","fact":"Dora began her creative career with comedy videos on YouTube, long before she concentrated on music.","wiki_en":"Dora (singer)","top_song":"Втюрилась","wiki_ru":"Дора (певица)","ru":true}];
